window.lectureTexts = {"1":{"title":"1-ТАҚЫРЫП. АЗАМАТТЫҚ ҚҰҚЫҚТЫҢ ТҮСІНІГІ","blocks":[{"text":"Азаматтық құқық дәстүрлі түрде құқық жүйесінде жеке құқықтың орталық және ең кең таралған саласы ретінде қаралады. Ол заңды теңдік, шарт еркіндігі және қатысушылардың мүліктік дербестігі қағидаттарына негізделген мүліктік және оларға байланысты мүліктік емес қатынастарды реттейді. Қазіргі кезеңде Қазақстан азаматтық құқығының дамуы нарықтық қатынастардың трансформациясымен, жеке меншіктің күшеюімен және азаматтық айналым субъектілерін қорғауға бағытталған жеке-құқықтық механизмдердің кеңеюімен тығыз байланысты.","html":"Азаматтық құқық дәстүрлі түрде құқық жүйесінде жеке құқықтың орталық және ең кең таралған саласы ретінде қаралады. Ол заңды теңдік, шарт еркіндігі және қатысушылардың мүліктік дербестігі қағидаттарына негізделген мүліктік және оларға байланысты мүліктік емес қатынастарды реттейді. Қазіргі кезеңде Қазақстан азаматтық құқығының дамуы нарықтық қатынастардың трансформациясымен, жеке меншіктің күшеюімен және азаматтық айналым субъектілерін қорғауға бағытталған жеке-құқықтық механизмдердің кеңеюімен тығыз байланысты.","id":"lesson-1-paragraph-1"},{"text":"Қазақстан Республикасының Конституциясында «Қазақстан Республикасында мемлекеттік және жеке меншік танылады және бірдей қорғалады» деп бекітілген, бұл жеке құқықтың ұлттық құқық жүйесіндегі маңызды рөлін дәлелдейді [1].","html":"Қазақстан Республикасының Конституциясында «Қазақстан Республикасында мемлекеттік және жеке меншік танылады және бірдей қорғалады» деп бекітілген, бұл жеке құқықтың ұлттық құқық жүйесіндегі маңызды рөлін дәлелдейді [1].","id":"lesson-1-paragraph-2"},{"text":"Жеке құқық – бұл жеке тұлғалардың арасындағы қатынастарды теңдік, бастамашылық және диспозтивтілік қағидаттары негізінде реттейтін құқық салаларының жиынтығы. Бұған азаматтық, отбасылық, халықаралық жеке құқық, сондай-ақ кейбір елдерде сауда құқығы жатады. Қазақстандық құқықтық доктринада азаматтық құқық жеке құқық салаларының орталығы болып есептеледі, өйткені ол экономиканың тұрақты жұмыс істеуін қамтамасыз ететін мүліктік қатынастардың ең ауқымды жиынтығын реттейді.","html":"Жеке құқық – бұл жеке тұлғалардың арасындағы қатынастарды теңдік, бастамашылық және диспозтивтілік қағидаттары негізінде реттейтін құқық салаларының жиынтығы. Бұған азаматтық, отбасылық, халықаралық жеке құқық, сондай-ақ кейбір елдерде сауда құқығы жатады. Қазақстандық құқықтық доктринада азаматтық құқық жеке құқық салаларының орталығы болып есептеледі, өйткені ол экономиканың тұрақты жұмыс істеуін қамтамасыз ететін мүліктік қатынастардың ең ауқымды жиынтығын реттейді.","id":"lesson-1-paragraph-3"},{"text":"Жеке құқық теориясындағы негізгі белгілер – шарт еркіндігі, заңды теңдік және тараптардың мүліктік дербестігі. Бұл принциптер азаматтық – құқықтық реттеудің өзегін құрайды: тараптар шарттардың мазмұнын, құқықтарын қорғау тәсілдерін және міндеттемелердің шектерін өздері анықтайды. Императивтік нормалар тек белгілі жағдайларда – тараптардың мүдделер теңгерімін қамтамасыз ету немесе әлсіз тарапты қорғау қажет болғанда ғана қолданылады.","html":"Жеке құқық теориясындағы негізгі белгілер – шарт еркіндігі, заңды теңдік және тараптардың мүліктік дербестігі. Бұл принциптер азаматтық – құқықтық реттеудің өзегін құрайды: тараптар шарттардың мазмұнын, құқықтарын қорғау тәсілдерін және міндеттемелердің шектерін өздері анықтайды. Императивтік нормалар тек белгілі жағдайларда – тараптардың мүдделер теңгерімін қамтамасыз ету немесе әлсіз тарапты қорғау қажет болғанда ғана қолданылады.","id":"lesson-1-paragraph-4"},{"text":"Қазақстан Республикасының Азаматтық кодексі (бұдан әрі АК) азаматтық заңнаманың тараптардың теңдігі мен меншікке қол сұқпаушылық қағидаттарына негізделетінін нақты көрсетеді. Бұл сала табиғаттың жеке-құқықтық екенін дәлелдейді.","html":"Қазақстан Республикасының Азаматтық кодексі (бұдан әрі АК) азаматтық заңнаманың тараптардың теңдігі мен меншікке қол сұқпаушылық қағидаттарына негізделетінін нақты көрсетеді. Бұл сала табиғаттың жеке-құқықтық екенін дәлелдейді.","id":"lesson-1-paragraph-5"},{"text":"Азаматтық құқықтың пәні дәстүрлі түрде мүліктік және оларға байланысты мүліктік емес қатынастар ретінде түіндіріледі. ҚР Азаматтық кодексінде азаматтық – құқықтық реттеудің пәні «тауар-ақша және өзге де мүліктік қатынастар, сондай-ақ оларға байланысты жеке мүліктік емес қатынастар» деп айқындалған [2].","html":"Азаматтық құқықтың пәні дәстүрлі түрде мүліктік және оларға байланысты мүліктік емес қатынастар ретінде түіндіріледі. ҚР Азаматтық кодексінде азаматтық – құқықтық реттеудің пәні «тауар-ақша және өзге де мүліктік қатынастар, сондай-ақ оларға байланысты жеке мүліктік емес қатынастар» деп айқындалған [2].","id":"lesson-1-paragraph-6"},{"text":"Мүліктік қатынастарға меншік қатынастары, міндетемелер туралы қатынастар, зияткерлік меншік объектілеріне қатысты қатынастар, сондай-ақ заңды тұлғалар қатысушыларының ұжымдық қатынастары кіреді.","html":"Мүліктік қатынастарға меншік қатынастары, міндетемелер туралы қатынастар, зияткерлік меншік объектілеріне қатысты қатынастар, сондай-ақ заңды тұлғалар қатысушыларының ұжымдық қатынастары кіреді.","id":"lesson-1-paragraph-7"},{"text":"Экономикалық мазмұнның болуы бұл қатынастарды тең ерікті субъектілердің өзара әрекетіне айналдырады, сондықтан оларды реттеу үшін диспозитивтік әдіс қолданылады.","html":"Экономикалық мазмұнның болуы бұл қатынастарды тең ерікті субъектілердің өзара әрекетіне айналдырады, сондықтан оларды реттеу үшін диспозитивтік әдіс қолданылады.","id":"lesson-1-paragraph-8"},{"text":"Мүліктік емес қатынастарға жеке адамның өмірі, денсаулығы, қадір-қасиеті, абырой, игі атақ, іскерлік бедел, жеке өмірге қол сұқпаушылық және басқа да мүліктік емес игіліктер мен құқықтар жатады.","html":"Мүліктік емес қатынастарға жеке адамның өмірі, денсаулығы, қадір-қасиеті, абырой, игі атақ, іскерлік бедел, жеке өмірге қол сұқпаушылық және басқа да мүліктік емес игіліктер мен құқықтар жатады.","id":"lesson-1-paragraph-9"},{"text":"Азаматтық құқық әдісі – жеке құқық табиғатын айқындайтын белгі. Құқықтық реттеу әдісі – құқықтың қоғамдық қатынастарға ықпал ету тетігі. Азаматтық құқық әдісі диспозитивтік сипатқа ие. Бұл қатысушылардың өзара әрекеттерінің шарттарын өз еркімен анықтауға мүмкіндік береді [3].","html":"Азаматтық құқық әдісі – жеке құқық табиғатын айқындайтын белгі. Құқықтық реттеу әдісі – құқықтың қоғамдық қатынастарға ықпал ету тетігі. Азаматтық құқық әдісі диспозитивтік сипатқа ие. Бұл қатысушылардың өзара әрекеттерінің шарттарын өз еркімен анықтауға мүмкіндік береді [3].","id":"lesson-1-paragraph-10"},{"text":"Императивтік нормалар тек заңда белгіленген ерекше жағдайларда қолданылады, мысалы жария мүліктерді, әлсіз тарапты қорғау немесе құқықты теріс пайдалану фактісін болдырмау үшін.","html":"Императивтік нормалар тек заңда белгіленген ерекше жағдайларда қолданылады, мысалы жария мүліктерді, әлсіз тарапты қорғау немесе құқықты теріс пайдалану фактісін болдырмау үшін.","id":"lesson-1-paragraph-11"},{"text":"Диспозитивтік әдістің төмендегідей элементтері бар:","html":"Диспозитивтік әдістің төмендегідей элементтері бар:","id":"lesson-1-paragraph-12"},{"text":"тараптардың заңды теңдігі;","html":"тараптардың заңды теңдігі;","list":{"id":"2","ordered":false,"marker":"-","start":1},"id":"lesson-1-paragraph-13"},{"text":"шарт еркіндігі;","html":"шарт еркіндігі;","list":{"id":"2","ordered":false,"marker":"-","start":1},"id":"lesson-1-paragraph-14"},{"text":"мүліктік дербестік;","html":"мүліктік дербестік;","list":{"id":"2","ordered":false,"marker":"-","start":1},"id":"lesson-1-paragraph-15"},{"text":"құқықтарды сот арқылы қорғау.","html":"құқықтарды сот арқылы қорғау.","list":{"id":"2","ordered":false,"marker":"-","start":1},"id":"lesson-1-paragraph-16"},{"text":"Диспозитивтік сипат жеке құқықтың басты белгісі болып табылады.","html":"Диспозитивтік сипат жеке құқықтың басты белгісі болып табылады.","id":"lesson-1-paragraph-17"},{"text":"Азаматтық құқықтың қағидалары – азаматтық заңнаманың мәнін, бағытын және реттеу әдісін айқындайтын негізгі басталуар. Олар азаматтық құқық жүйесінің іргетасы болп табылды және барлық азаматтық-құқықтық нормалардың қоланылуына негіз болады.","html":"Азаматтық құқықтың қағидалары – азаматтық заңнаманың мәнін, бағытын және реттеу әдісін айқындайтын негізгі басталуар. Олар азаматтық құқық жүйесінің іргетасы болп табылды және барлық азаматтық-құқықтық нормалардың қоланылуына негіз болады.","id":"lesson-1-paragraph-18"},{"text":"ҚР АК-тің 2-бабында азаматтық құқықтың төмендегідей негізгі қағидалары бекітілген:","html":"ҚР АК-тің 2-бабында азаматтық құқықтың төмендегідей негізгі қағидалары бекітілген:","id":"lesson-1-paragraph-19"},{"text":"азаматтық қатынастарға қатысушылардың теңдігі;","html":"азаматтық қатынастарға қатысушылардың теңдігі;","list":{"id":"1","ordered":true,"marker":"%1)","start":1},"id":"lesson-1-paragraph-20"},{"text":"меншікке қол сұқпаушылық;","html":"меншікке қол сұқпаушылық;","list":{"id":"1","ordered":true,"marker":"%1)","start":1},"id":"lesson-1-paragraph-21"},{"text":"шарт еркіндігі;","html":"шарт еркіндігі;","list":{"id":"1","ordered":true,"marker":"%1)","start":1},"id":"lesson-1-paragraph-22"},{"text":"жеке істерге өз бетінше араласуға жол бермеу;","html":"жеке істерге өз бетінше араласуға жол бермеу;","list":{"id":"1","ordered":true,"marker":"%1)","start":1},"id":"lesson-1-paragraph-23"},{"text":"бұзылған құқықтарды қалпына келтіруді қамтамасыз ету;","html":"бұзылған құқықтарды қалпына келтіруді қамтамасыз ету;","list":{"id":"1","ordered":true,"marker":"%1)","start":1},"id":"lesson-1-paragraph-24"},{"text":"азаматтық құқықтарды кедергісіз жүзеге асыру;","html":"азаматтық құқықтарды кедергісіз жүзеге асыру;","list":{"id":"1","ordered":true,"marker":"%1)","start":1},"id":"lesson-1-paragraph-25"},{"text":"бұзылған құқықтарды сот арқылы қорғау [2].","html":"бұзылған құқықтарды сот арқылы қорғау [2].","list":{"id":"1","ordered":true,"marker":"%1)","start":1},"id":"lesson-1-paragraph-26"},{"text":"Азаматтық құқық қағидалары жеке құқыққа тән негізгі белгілерді айқындайды және азаматтық құқықтың нарықтық экономиканың құқықтық негізі ретіндегі рөлін күшейтеді. Бұл қағидалар азаматтық-құқықтық қатынастардың мазмұнын, олардың жүзеге асырылу тәртібін және құқықтарды қорғау тетіктерін анықтайды. Аталған қағидалардың мәнін түсіндіру үшін төмендегі мысалдар келтіріледі.","html":"Азаматтық құқық қағидалары жеке құқыққа тән негізгі белгілерді айқындайды және азаматтық құқықтың нарықтық экономиканың құқықтық негізі ретіндегі рөлін күшейтеді. Бұл қағидалар азаматтық-құқықтық қатынастардың мазмұнын, олардың жүзеге асырылу тәртібін және құқықтарды қорғау тетіктерін анықтайды. Аталған қағидалардың мәнін түсіндіру үшін төмендегі мысалдар келтіріледі.","id":"lesson-1-paragraph-27"},{"text":"Бірінші қағида – азаматтық қатынастарға қатысушылардың теңдігі. Қазақстан Республикасының Азаматтық кодексінің 2-бабына сәйкес азаматтар, заңды тұлғалар, мемлекет және мемлекеттік емес ұйымдар азаматтық-құқықтық қатынастарға тең құқықты субъектілер ретінде қатысады. Бұл қағидаға сәйкес қатысушылардың ешқайсысы екінші тарапқа үстемдік ете алмайды. Мысалы, азамат ірі құрылыс компаниясымен жалдау шартын жасасқанда, компанияның экономикалық мүмкіндіктері жоғары болғанына қарамастан, тараптар шартта тең құқықты болып табылады және шарт талаптары екі тараптың мүдделерін ескере отырып белгіленуі тиіс.","html":"Бірінші қағида – азаматтық қатынастарға қатысушылардың теңдігі. Қазақстан Республикасының Азаматтық кодексінің 2-бабына сәйкес азаматтар, заңды тұлғалар, мемлекет және мемлекеттік емес ұйымдар азаматтық-құқықтық қатынастарға тең құқықты субъектілер ретінде қатысады. Бұл қағидаға сәйкес қатысушылардың ешқайсысы екінші тарапқа үстемдік ете алмайды. Мысалы, азамат ірі құрылыс компаниясымен жалдау шартын жасасқанда, компанияның экономикалық мүмкіндіктері жоғары болғанына қарамастан, тараптар шартта тең құқықты болып табылады және шарт талаптары екі тараптың мүдделерін ескере отырып белгіленуі тиіс.","id":"lesson-1-paragraph-28"},{"text":"Екінші қағида – меншікке қол сұқпаушылық. Бұл қағидаға сәйкес меншік иесі өз мүлкін иеленуге, пайдалануға және оған билік етуге құқылы. Ешкімді оның мүлкінен сот шешімінсіз немесе заңда көзделген негіздерсіз айыруға болмайды. Мысалы, көрші тұлға сіздің жер учаскеңіздің бір бөлігін заңсыз иемденіп, қоршау орнатса, сіз сотқа жүгініп, жерді босатуды және келтірілген шығынды өндіруді талап ете аласыз.","html":"Екінші қағида – меншікке қол сұқпаушылық. Бұл қағидаға сәйкес меншік иесі өз мүлкін иеленуге, пайдалануға және оған билік етуге құқылы. Ешкімді оның мүлкінен сот шешімінсіз немесе заңда көзделген негіздерсіз айыруға болмайды. Мысалы, көрші тұлға сіздің жер учаскеңіздің бір бөлігін заңсыз иемденіп, қоршау орнатса, сіз сотқа жүгініп, жерді босатуды және келтірілген шығынды өндіруді талап ете аласыз.","id":"lesson-1-paragraph-29"},{"text":"Үшінші қағида – шарт еркіндігі. Бұл қағида бойынша тараптар шартты жасасу немесе жасасудан бас тарту, шарт түрін таңдау және оның талаптарын белгілеу мәселесінде еркін болады. Егер шарттың мазмұны заң талаптарына қайшы келмесе, тараптар өзара келісім арқылы қажетті талаптарды белгілей алады. Мысалы, екі кәсіпкер жеткізілім шартының бағасын, жеткізу мерзімін және басқа да талаптарын өзара келісім арқылы анықтай алады.","html":"Үшінші қағида – шарт еркіндігі. Бұл қағида бойынша тараптар шартты жасасу немесе жасасудан бас тарту, шарт түрін таңдау және оның талаптарын белгілеу мәселесінде еркін болады. Егер шарттың мазмұны заң талаптарына қайшы келмесе, тараптар өзара келісім арқылы қажетті талаптарды белгілей алады. Мысалы, екі кәсіпкер жеткізілім шартының бағасын, жеткізу мерзімін және басқа да талаптарын өзара келісім арқылы анықтай алады.","id":"lesson-1-paragraph-30"},{"text":"Төртінші қағида – жеке істерге өз бетінше араласуға жол бермеу. Бұл қағидаға сәйкес ешкім азаматтың жеке өміріне немесе кәсіпкерлік қызметіне заңсыз араласа алмайды. Мысалы, мемлекеттік орган заңда көзделмеген құжаттарды талап етуге құқылы емес. Сонымен қатар коммерциялық құпия мен жеке деректер заңмен қорғалады.","html":"Төртінші қағида – жеке істерге өз бетінше араласуға жол бермеу. Бұл қағидаға сәйкес ешкім азаматтың жеке өміріне немесе кәсіпкерлік қызметіне заңсыз араласа алмайды. Мысалы, мемлекеттік орган заңда көзделмеген құжаттарды талап етуге құқылы емес. Сонымен қатар коммерциялық құпия мен жеке деректер заңмен қорғалады.","id":"lesson-1-paragraph-31"},{"text":"Бесінші қағида – бұзылған құқықтарды қалпына келтіруді қамтамасыз ету. Азаматтық құқық бұзылған жағдайда ол міндетті түрде қалпына келтірілуі тиіс. Бұл мүлікті қайтару, келтірілген залалды өтеу, мәмілені жарамсыз деп тану сияқты құқықтық тәсілдер арқылы жүзеге асырылады. Мысалы, дүкен ақауы бар тауар сатқан жағдайда сатып алушы тауарды ауыстыруды, ақшасын қайтаруды немесе кемшіліктерді тегін жоюды талап етуге құқылы.","html":"Бесінші қағида – бұзылған құқықтарды қалпына келтіруді қамтамасыз ету. Азаматтық құқық бұзылған жағдайда ол міндетті түрде қалпына келтірілуі тиіс. Бұл мүлікті қайтару, келтірілген залалды өтеу, мәмілені жарамсыз деп тану сияқты құқықтық тәсілдер арқылы жүзеге асырылады. Мысалы, дүкен ақауы бар тауар сатқан жағдайда сатып алушы тауарды ауыстыруды, ақшасын қайтаруды немесе кемшіліктерді тегін жоюды талап етуге құқылы.","id":"lesson-1-paragraph-32"},{"text":"Алтыншы қағида – азаматтық құқықтарды кедергісіз жүзеге асыру. Азаматтық құқық субъектілері өз құқықтарын еркін жүзеге асыра алады, яғни мүлікке иелік етуге, мәмілелер жасауға, кәсіпкерлік қызметпен айналысуға құқылы. Мысалы, егер кәсіпкерге заңды негізсіз кәсіпкерлік қызметті тіркеуден бас тартылса, ол бұл шешімге шағым жасап, сот арқылы өз бизнесін тіркетуге құқылы.","html":"Алтыншы қағида – азаматтық құқықтарды кедергісіз жүзеге асыру. Азаматтық құқық субъектілері өз құқықтарын еркін жүзеге асыра алады, яғни мүлікке иелік етуге, мәмілелер жасауға, кәсіпкерлік қызметпен айналысуға құқылы. Мысалы, егер кәсіпкерге заңды негізсіз кәсіпкерлік қызметті тіркеуден бас тартылса, ол бұл шешімге шағым жасап, сот арқылы өз бизнесін тіркетуге құқылы.","id":"lesson-1-paragraph-33"},{"text":"Жетінші қағида – бұзылған құқықтарды сот арқылы қорғау. Әрбір тұлға өзінің құқықтары бұзылған жағдайда немесе дау туындаған кезде сотқа жүгінуге құқылы. Мысалы, жалға беруші шарт талаптарын заңсыз бұзып, жалға алушыны тұрғын үйден шығарып жіберсе, жалға алушы сотқа жүгініп, шартты қалпына келтіруді және келтірілген зиянды өтеуді талап ете алады. Жалпы алғанда, азаматтық құқық қағидалары – азаматтық айналымдағы тұрақтылықты, жеке меншік пен еркін экономикалық қатынастардың қауіпсіздігін қаматмасыз ететін құққтық және идеологиялық негіз. Олар азамттық құқықтың негізгі мақмұнын қалыптастырады тараптардың өзара қатынастарына бағыт-бағдар береді және құқықтық тәртіпті нығайтуда маңызды рөл атқарады.","html":"Жетінші қағида – бұзылған құқықтарды сот арқылы қорғау. Әрбір тұлға өзінің құқықтары бұзылған жағдайда немесе дау туындаған кезде сотқа жүгінуге құқылы. Мысалы, жалға беруші шарт талаптарын заңсыз бұзып, жалға алушыны тұрғын үйден шығарып жіберсе, жалға алушы сотқа жүгініп, шартты қалпына келтіруді және келтірілген зиянды өтеуді талап ете алады. Жалпы алғанда, азаматтық құқық қағидалары – азаматтық айналымдағы тұрақтылықты, жеке меншік пен еркін экономикалық қатынастардың қауіпсіздігін қаматмасыз ететін құққтық және идеологиялық негіз. Олар азамттық құқықтың негізгі мақмұнын қалыптастырады тараптардың өзара қатынастарына бағыт-бағдар береді және құқықтық тәртіпті нығайтуда маңызды рөл атқарады.","id":"lesson-1-paragraph-34"},{"text":"Азаматтық құқық жүйесі – бұл азаматтық құқық саласының ішкі құрылымы, яғни азаматтық заңнаманы ғылыми негізделген және логикалық түрде жеке институттар мен ішкі салаларға бөлінуі. Бұл жүйе азаматтық-құқықтық нормалардың мазмұнын, олардың өзара байланысын көрсетеді және мүліктік және оларға байланысты мүліктік емес қатынастарды кешенді түрде реттеуді қаматамасыз етеді [4].","html":"Азаматтық құқық жүйесі – бұл азаматтық құқық саласының ішкі құрылымы, яғни азаматтық заңнаманы ғылыми негізделген және логикалық түрде жеке институттар мен ішкі салаларға бөлінуі. Бұл жүйе азаматтық-құқықтық нормалардың мазмұнын, олардың өзара байланысын көрсетеді және мүліктік және оларға байланысты мүліктік емес қатынастарды кешенді түрде реттеуді қаматамасыз етеді [4].","id":"lesson-1-paragraph-35"},{"text":"Азаматтық құқық жүйесінің мәні мен маңызына келетін болсақ, азаматтық құқық жүйесі реттеу пәні мен әдісіне сүйене отырып қалыптасады. Оның негізгі қызметтері – азаматтың заң нормаларын жүйелеу, әр институттың құқық жүйесіндегі орнын айқындау, құқықтық реттеудің тұрақтылығы мен сабақтастығын қамтамасыз ету және нормалардың тәжірибеде қолданылуын жеңілдету. Жүйенің болуы заңнаманы түсінуді жеңілдетеді және құқық қолдануды тиімді етеді.","html":"Азаматтық құқық жүйесінің мәні мен маңызына келетін болсақ, азаматтық құқық жүйесі реттеу пәні мен әдісіне сүйене отырып қалыптасады. Оның негізгі қызметтері – азаматтың заң нормаларын жүйелеу, әр институттың құқық жүйесіндегі орнын айқындау, құқықтық реттеудің тұрақтылығы мен сабақтастығын қамтамасыз ету және нормалардың тәжірибеде қолданылуын жеңілдету. Жүйенің болуы заңнаманы түсінуді жеңілдетеді және құқық қолдануды тиімді етеді.","id":"lesson-1-paragraph-36"},{"text":"Қазақстан Республикасының Азаматтық кодексі екі негізгі бөлімнен тұрады: Жалпы бөлім және Ерекше бөлім. Бұл бөлімдер азаматтық құқық саласындағы қатынастарды жүйелі түрде реттеуге бағытталған.","html":"Қазақстан Республикасының Азаматтық кодексі екі негізгі бөлімнен тұрады: Жалпы бөлім және Ерекше бөлім. Бұл бөлімдер азаматтық құқық саласындағы қатынастарды жүйелі түрде реттеуге бағытталған.","id":"lesson-1-paragraph-37"},{"text":"Азаматтық кодекстің Жалпы бөлімі 1994 жылғы 27 желтоқсанда қабылданған және ол барлық азаматтық-құқықтық қатынастарға қолданылатын жалпы нормаларды қамтиды. Жалпы бөлім азаматтық құқықтың негізгі институттарын белгілейді және азаматтық-құқықтық қатынастардың жалпы қағидаларын айқындайды. Оның құрамына азаматтық құқықтың пәні мен принциптері, азаматтық құқық субъектілері (азаматтар, заңды тұлғалар және мемлекет), азаматтық құқық объектілері (заттар, ақша, бағалы қағаздар және басқа да мүліктер), мәмілелер, өкілдік және сенімхат, мерзімдер мен талап қою мерзімі, азаматтық құқықтарды жүзеге асыру және қорғау, сондай-ақ міндеттемені бұзғаны үшін жауапкершілік сияқты институттар кіреді.","html":"Азаматтық кодекстің Жалпы бөлімі 1994 жылғы 27 желтоқсанда қабылданған және ол барлық азаматтық-құқықтық қатынастарға қолданылатын жалпы нормаларды қамтиды. Жалпы бөлім азаматтық құқықтың негізгі институттарын белгілейді және азаматтық-құқықтық қатынастардың жалпы қағидаларын айқындайды. Оның құрамына азаматтық құқықтың пәні мен принциптері, азаматтық құқық субъектілері (азаматтар, заңды тұлғалар және мемлекет), азаматтық құқық объектілері (заттар, ақша, бағалы қағаздар және басқа да мүліктер), мәмілелер, өкілдік және сенімхат, мерзімдер мен талап қою мерзімі, азаматтық құқықтарды жүзеге асыру және қорғау, сондай-ақ міндеттемені бұзғаны үшін жауапкершілік сияқты институттар кіреді.","id":"lesson-1-paragraph-38"},{"text":"Азаматтық кодекстің Ерекше бөлімі 1999 жылғы 1 шілдеде қабылданған және нақты азаматтық-құқықтық қатынастарды реттейтін нормаларды қамтиды. Бұл бөлімде азаматтық құқықтың жекелеген институттары егжей-тегжейлі қарастырылған. Атап айтқанда, оған заттық құқық, міндеттемелік құқық, мұрагерлік құқық және зияткерлік меншік құқығы сияқты негізгі институттар жатады. Азаматтық құқық жүйесі заңнаманың бірлігін және ішкі үйлесімділігін қамтамасыз етуге, пәнді оқытуды жеңілдетуге, нормаларды дұрыс қолдануға көмектесуге, институттардың дамуына және заңнаманы жетілдіруге жағдай жасауда үлкен рөл атқарады.","html":"Азаматтық кодекстің Ерекше бөлімі 1999 жылғы 1 шілдеде қабылданған және нақты азаматтық-құқықтық қатынастарды реттейтін нормаларды қамтиды. Бұл бөлімде азаматтық құқықтың жекелеген институттары егжей-тегжейлі қарастырылған. Атап айтқанда, оған заттық құқық, міндеттемелік құқық, мұрагерлік құқық және зияткерлік меншік құқығы сияқты негізгі институттар жатады. Азаматтық құқық жүйесі заңнаманың бірлігін және ішкі үйлесімділігін қамтамасыз етуге, пәнді оқытуды жеңілдетуге, нормаларды дұрыс қолдануға көмектесуге, институттардың дамуына және заңнаманы жетілдіруге жағдай жасауда үлкен рөл атқарады.","id":"lesson-1-paragraph-39"}],"words":1193,"legacyAnchors":{"lesson-1-section-1":"lesson-1-paragraph-1","lesson-1-section-2":"lesson-1-paragraph-6","lesson-1-section-3":"lesson-1-paragraph-10","lesson-1-section-4":"lesson-1-paragraph-18","lesson-1-section-5":"lesson-1-paragraph-35"}},"2":{"title":"2-ТАҚЫРЫП. АЗАМАТТЫҚ ҚҰҚЫҚТЫҢ ҚАЙНАР КӨЗДЕРІ ЖӘНЕ ОЛАРДЫҢ ТҮРЛЕРІ","blocks":[{"text":"Азаматтық құқықтың қайнар көздері – азаматтық құқық нормаларын қамтитын нысандар, яғни азаматтық құқық нормаларын азаматтық-құқықтық қатынастарға қатысушыларға жеткізудің тәсілі болып табылады. Сонымен қатар олар азаматтық құқық нормаларының жиынтығынан тұратын ресми құжаттар ретінде де қарастырылады.","html":"Азаматтық құқықтың қайнар көздері – азаматтық құқық нормаларын қамтитын нысандар, яғни азаматтық құқық нормаларын азаматтық-құқықтық қатынастарға қатысушыларға жеткізудің тәсілі болып табылады. Сонымен қатар олар азаматтық құқық нормаларының жиынтығынан тұратын ресми құжаттар ретінде де қарастырылады.","id":"lesson-2-paragraph-1"},{"text":"Реттеу деңгейіне қарай азаматтық құқықтың қайнар көздері екі негізгі түрге бөлінеді. Біріншісі – халықаралық қайнар көздер. Оларға халықаралық шарттар, сондай-ақ халықаралық құқықтың жалпыға танылған қағидаттары мен нормалары жатады. Мұндай қайнар көздер ұлттық құқықпен салыстырғанда басым заңдық күшке ие. Екіншісі – ұлттық қайнар көздер. Олар мемлекет ішінде қолданылатын нормативтік құқықтық актілерден тұрады.","html":"Реттеу деңгейіне қарай азаматтық құқықтың қайнар көздері екі негізгі түрге бөлінеді. Біріншісі – халықаралық қайнар көздер. Оларға халықаралық шарттар, сондай-ақ халықаралық құқықтың жалпыға танылған қағидаттары мен нормалары жатады. Мұндай қайнар көздер ұлттық құқықпен салыстырғанда басым заңдық күшке ие. Екіншісі – ұлттық қайнар көздер. Олар мемлекет ішінде қолданылатын нормативтік құқықтық актілерден тұрады.","id":"lesson-2-paragraph-2"},{"text":"Маңызына қарай азаматтық құқықтың қайнар көздері негізгі және қосалқы болып бөлінеді. Негізгі қайнар көздерге азаматтық құқық нормалары қамтылған нормативтік құқықтық актілер жатады. Ал қосалқы қайнар көздерге әдет-ғұрыптар, соның ішінде әдеттегі құқықтар кіреді.","html":"Маңызына қарай азаматтық құқықтың қайнар көздері негізгі және қосалқы болып бөлінеді. Негізгі қайнар көздерге азаматтық құқық нормалары қамтылған нормативтік құқықтық актілер жатады. Ал қосалқы қайнар көздерге әдет-ғұрыптар, соның ішінде әдеттегі құқықтар кіреді.","id":"lesson-2-paragraph-3"},{"text":"Әдеттегі құқықтар, әсіресе іскерлік қызмет саласында қалыптасқан әдет-ғұрыптар, Қазақстан Республикасының қолданыстағы азаматтық заңдарына қайшы келмеген жағдайда азаматтық қатынастарды реттеуде қолданылуы мүмкін. Сонымен бірге әдет-ғұрыптар заң талаптарына және шарт талаптарына қайшы болмауы тиіс.","html":"Әдеттегі құқықтар, әсіресе іскерлік қызмет саласында қалыптасқан әдет-ғұрыптар, Қазақстан Республикасының қолданыстағы азаматтық заңдарына қайшы келмеген жағдайда азаматтық қатынастарды реттеуде қолданылуы мүмкін. Сонымен бірге әдет-ғұрыптар заң талаптарына және шарт талаптарына қайшы болмауы тиіс.","id":"lesson-2-paragraph-4"},{"text":"Азаматтық құқықтың негізгі қайнар көздері – нормативтік құқықтық актілер. Олар белгілі бір иерархиялық жүйеге бағынады. Яғни төменгі деңгейдегі нормативтік актілер жоғары деңгейдегі актілерге қайшы келмеуі тиіс. Егер мұндай қайшылық орын алса, онда жоғары тұрған нормативтік құқықтық актінің нормалары қолданылады.","html":"Азаматтық құқықтың негізгі қайнар көздері – нормативтік құқықтық актілер. Олар белгілі бір иерархиялық жүйеге бағынады. Яғни төменгі деңгейдегі нормативтік актілер жоғары деңгейдегі актілерге қайшы келмеуі тиіс. Егер мұндай қайшылық орын алса, онда жоғары тұрған нормативтік құқықтық актінің нормалары қолданылады.","id":"lesson-2-paragraph-5"},{"text":"Иерархиясына қарай азаматтық құқық нормалары қамтылған нормативтік құқықтық актілер белгілі бір жүйеге біріктіріледі. Бұл жүйе олардың заңдық күшіне және қабылдану деңгейіне байланысты қалыптасады. Азаматтық құқық саласындағы нормативтік актілердің иерархиялық жүйесі ең жоғары заңдық күші бар актіден бастап төмендегі тәртіппен орналасады.","html":"Иерархиясына қарай азаматтық құқық нормалары қамтылған нормативтік құқықтық актілер белгілі бір жүйеге біріктіріледі. Бұл жүйе олардың заңдық күшіне және қабылдану деңгейіне байланысты қалыптасады. Азаматтық құқық саласындағы нормативтік актілердің иерархиялық жүйесі ең жоғары заңдық күші бар актіден бастап төмендегі тәртіппен орналасады.","id":"lesson-2-paragraph-6"},{"text":"Ең алдымен, Қазақстан Республикасының Конституциясы тұрады. Конституция – мемлекеттегі барлық құқық салалары үшін негізгі және жоғары заңдық күші бар акт болып табылады. Одан кейін азаматтық құқық саласының негізгі кодификацияланған актісі – Қазақстан Республикасының Азаматтық кодексі (Жалпы және Ерекше бөлім) орналасады.","html":"Ең алдымен, Қазақстан Республикасының Конституциясы тұрады. Конституция – мемлекеттегі барлық құқық салалары үшін негізгі және жоғары заңдық күші бар акт болып табылады. Одан кейін азаматтық құқық саласының негізгі кодификацияланған актісі – Қазақстан Республикасының Азаматтық кодексі (Жалпы және Ерекше бөлім) орналасады.","id":"lesson-2-paragraph-7"},{"text":"Азаматтық кодекстен кейін Қазақстан Республикасының өзге де заңдары қолданылады. Сонымен қатар азаматтық-құқықтық қатынастарды реттеуде Қазақстан Республикасы Президентінің жарлықтары, Қазақстан Республикасы Үкіметінің қаулылары және Қазақстан Республикасының орталық атқарушы органдары қабылдайтын өзге де нормативтік құқықтық актілер пайдаланылады [5].","html":"Азаматтық кодекстен кейін Қазақстан Республикасының өзге де заңдары қолданылады. Сонымен қатар азаматтық-құқықтық қатынастарды реттеуде Қазақстан Республикасы Президентінің жарлықтары, Қазақстан Республикасы Үкіметінің қаулылары және Қазақстан Республикасының орталық атқарушы органдары қабылдайтын өзге де нормативтік құқықтық актілер пайдаланылады [5].","id":"lesson-2-paragraph-8"},{"text":"Аталған нормативтік актілердің барлығы өзара иерархиялық жүйе құрайды және әрбір төменгі деңгейдегі акт жоғары деңгейдегі актінің талаптарына қайшы келмеуі тиіс","html":"Аталған нормативтік актілердің барлығы өзара иерархиялық жүйе құрайды және әрбір төменгі деңгейдегі акт жоғары деңгейдегі актінің талаптарына қайшы келмеуі тиіс","id":"lesson-2-paragraph-9"},{"text":"ҚР Конституциясы. Азаматтық кодексте азаматтық құқықтың қайнар көздерінің қатарында ҚР Конституциясы аталып көрсетілмейді. Негізгі заңның азаматтық құқықтың қайнар көзі болып табылады ма деген сұраққа жауап бір жақты емес, өйткені ҚР Конституциясында қамтылған нормалардың қай құқық саласына жататыны туралы белгілі бір ғылыми пікірталас бар.","html":"ҚР Конституциясы. Азаматтық кодексте азаматтық құқықтың қайнар көздерінің қатарында ҚР Конституциясы аталып көрсетілмейді. Негізгі заңның азаматтық құқықтың қайнар көзі болып табылады ма деген сұраққа жауап бір жақты емес, өйткені ҚР Конституциясында қамтылған нормалардың қай құқық саласына жататыны туралы белгілі бір ғылыми пікірталас бар.","id":"lesson-2-paragraph-10"},{"text":"Бірінші көзқарасқа сәйкес, оны әдетте, конституциялық құқық саласының өкілдері қолдайды, ҚР Конституциясы құқықтың тек бір саласының –конституциялық құқықтың нормаларын қамтиды. Бұл көзқарас әдетте Конституцияның жоғары заңдық күші мен ҚР-ның негізгі заңнамалық актісі ретіндегі ерекше маңыздылығына сілтеме жасай отырып дәлелденеді.","html":"Бірінші көзқарасқа сәйкес, оны әдетте, конституциялық құқық саласының өкілдері қолдайды, ҚР Конституциясы құқықтың тек бір саласының –конституциялық құқықтың нормаларын қамтиды. Бұл көзқарас әдетте Конституцияның жоғары заңдық күші мен ҚР-ның негізгі заңнамалық актісі ретіндегі ерекше маңыздылығына сілтеме жасай отырып дәлелденеді.","id":"lesson-2-paragraph-11"},{"text":"Екінші көзқарасқа сәйкес, ҚР Конституциясы түрлі құқық саласына жататын нормаларды қамтиды, оның ішінде азаматтық құқық нормаларын да. Бұл тәсіл Конституцияның маңыздылығын жоққа шығармайды, алайда нормалардың құқықтық салаға қатыстылығын олардың маңыздылығымен емес, құқықтық реттеудің пәні мен әдісі негізінде анықтау қажет екенін атап көрсетеді.","html":"Екінші көзқарасқа сәйкес, ҚР Конституциясы түрлі құқық саласына жататын нормаларды қамтиды, оның ішінде азаматтық құқық нормаларын да. Бұл тәсіл Конституцияның маңыздылығын жоққа шығармайды, алайда нормалардың құқықтық салаға қатыстылығын олардың маңыздылығымен емес, құқықтық реттеудің пәні мен әдісі негізінде анықтау қажет екенін атап көрсетеді.","id":"lesson-2-paragraph-12"},{"text":"Жалпы алғанда, екінші көзқарас әлдеқайда негіздірек. Расында да, ҚР конституциясында мазмұны жағынан жалпы сипатқа ие болса да, бірқатар азаматтық-құқықтық нормалар бар. Атап айтқанда, жеке өмірдің қол сұғылмаушылығы, меншік формаларының теңдігі мен жеке меншік құқығының қорғалуы, кәсіпкерлік еркіндігі, шығармашылық еркіндігі, шығармашылық еркіндігі туралы нормалар азаматтық- құқықтық мазмұнға ие.","html":"Жалпы алғанда, екінші көзқарас әлдеқайда негіздірек. Расында да, ҚР конституциясында мазмұны жағынан жалпы сипатқа ие болса да, бірқатар азаматтық-құқықтық нормалар бар. Атап айтқанда, жеке өмірдің қол сұғылмаушылығы, меншік формаларының теңдігі мен жеке меншік құқығының қорғалуы, кәсіпкерлік еркіндігі, шығармашылық еркіндігі, шығармашылық еркіндігі туралы нормалар азаматтық- құқықтық мазмұнға ие.","id":"lesson-2-paragraph-13"},{"text":"Азаматтық заңнама – Қазақстан Республикасының айрықша құзыреті. Бұл дегеніміз жергілікті мемлекеттік органдар мен жергілікті өзін-өзі басқару органдары азаматтық құқықтық қатынастарды реттейтін ережелер қабылдай алмайды.","html":"Азаматтық заңнама – Қазақстан Республикасының айрықша құзыреті. Бұл дегеніміз жергілікті мемлекеттік органдар мен жергілікті өзін-өзі басқару органдары азаматтық құқықтық қатынастарды реттейтін ережелер қабылдай алмайды.","id":"lesson-2-paragraph-14"},{"text":"Қазақстан Республикасының Азаматтық кодексі – кодификацияланған нормативтік құқықтық акт, яғни заң. Кодификация – құқықты жүйелеудің ең жоғары деңгейі. Бұл заңда азаматтық –құқықтық қатынастардың негіздері, азаматтық құқықтың негізгі институттары т.б. жағдайлар нақты баяндалған [6].","html":"Қазақстан Республикасының Азаматтық кодексі – кодификацияланған нормативтік құқықтық акт, яғни заң. Кодификация – құқықты жүйелеудің ең жоғары деңгейі. Бұл заңда азаматтық –құқықтық қатынастардың негіздері, азаматтық құқықтың негізгі институттары т.б. жағдайлар нақты баяндалған [6].","id":"lesson-2-paragraph-15"},{"text":"Азаматтық кодекс бірқатар ерекшеліктерімен сипатталады. Ең алдымен, ол азаматтық құқық пәніне жататын барлық қоғамдық қатынастарды реттейтін негізгі заңнамалық акт болып табылады. Сонымен қатар, Кодекс жүйелі құрылымға ие және азаматтық құқық саласының ішкі құрылымына толық сәйкес келеді. Сондай-ақ азаматтық құқық саласындағы басқа заңдарға қарағанда жоғары заңдық күшке ие, сондықтан осы саладағы өзге нормативтік құқықтық актілер Азаматтық кодекс ережелеріне қайшы келмеуге тиіс.","html":"Азаматтық кодекс бірқатар ерекшеліктерімен сипатталады. Ең алдымен, ол азаматтық құқық пәніне жататын барлық қоғамдық қатынастарды реттейтін негізгі заңнамалық акт болып табылады. Сонымен қатар, Кодекс жүйелі құрылымға ие және азаматтық құқық саласының ішкі құрылымына толық сәйкес келеді. Сондай-ақ азаматтық құқық саласындағы басқа заңдарға қарағанда жоғары заңдық күшке ие, сондықтан осы саладағы өзге нормативтік құқықтық актілер Азаматтық кодекс ережелеріне қайшы келмеуге тиіс.","id":"lesson-2-paragraph-16"},{"text":"Қазақстан Республикасының Азаматтық кодексі Жалпы және Ерекше бөлімдерден тұрады. Жалпы бөлім 1994 жылы 27 желтоқсан күні қабылданып, 1995 жылы 1 наурызда заңдық күшіне енген, ал Ерекше бөлімі 1999 жылы 1 шілдеде заңдық күшіне енді.","html":"Қазақстан Республикасының Азаматтық кодексі Жалпы және Ерекше бөлімдерден тұрады. Жалпы бөлім 1994 жылы 27 желтоқсан күні қабылданып, 1995 жылы 1 наурызда заңдық күшіне енген, ал Ерекше бөлімі 1999 жылы 1 шілдеде заңдық күшіне енді.","id":"lesson-2-paragraph-17"},{"text":"Азаматтық кодекстің құрылымы бөлім, бөлімше, тарау және баптардан тұрады. Бұл құрылым азаматтық-құқықтық нормаларды жүйелі түрде орналастырып, оларды қолдануды жеңілдетуге бағытталған. Қазақстан Республикасының Азаматтық кодексі мазмұны бойынша жеті негізгі бөлімнен тұрады және азаматтық құқық саласындағы негізгі институттарды қамтиды.","html":"Азаматтық кодекстің құрылымы бөлім, бөлімше, тарау және баптардан тұрады. Бұл құрылым азаматтық-құқықтық нормаларды жүйелі түрде орналастырып, оларды қолдануды жеңілдетуге бағытталған. Қазақстан Республикасының Азаматтық кодексі мазмұны бойынша жеті негізгі бөлімнен тұрады және азаматтық құқық саласындағы негізгі институттарды қамтиды.","id":"lesson-2-paragraph-18"},{"text":"Бірінші бөлім – Жалпы ережелер. Бұл бөлімде азаматтық құқықтың негізгі қағидалары, азаматтық құқық субъектілері, мүліктің түрлері, мәмілелер, өкілдік, мерзімдер және азаматтық құқықтарды қорғау тәсілдері сияқты негізгі институттар қарастырылады.","html":"Бірінші бөлім – Жалпы ережелер. Бұл бөлімде азаматтық құқықтың негізгі қағидалары, азаматтық құқық субъектілері, мүліктің түрлері, мәмілелер, өкілдік, мерзімдер және азаматтық құқықтарды қорғау тәсілдері сияқты негізгі институттар қарастырылады.","id":"lesson-2-paragraph-19"},{"text":"Екінші бөлім – Меншік құқығы және өзге заттық құқықтар. Бұл бөлімде меншік нысандары (жеке, мемлекеттік және аралас меншік), меншік иесінің өкілеттіктері, шаруашылық жүргізу және жедел басқару құқықтары, сервитуттар және басқа да заттық құқықтар реттеледі.","html":"Екінші бөлім – Меншік құқығы және өзге заттық құқықтар. Бұл бөлімде меншік нысандары (жеке, мемлекеттік және аралас меншік), меншік иесінің өкілеттіктері, шаруашылық жүргізу және жедел басқару құқықтары, сервитуттар және басқа да заттық құқықтар реттеледі.","id":"lesson-2-paragraph-20"},{"text":"Үшінші бөлім – Міндеттемелік құқық. Бұл бөлімде міндеттемелердің пайда болуы, өзгеруі және тоқтатылуы, шарттардың ұғымы мен түрлері, оларды жасасу тәртібі, міндеттемелерді орындау және оларды бұзудың салдары, сондай-ақ міндеттемені орындамағаны үшін жауапкершілік мәселелері қамтылады.","html":"Үшінші бөлім – Міндеттемелік құқық. Бұл бөлімде міндеттемелердің пайда болуы, өзгеруі және тоқтатылуы, шарттардың ұғымы мен түрлері, оларды жасасу тәртібі, міндеттемелерді орындау және оларды бұзудың салдары, сондай-ақ міндеттемені орындамағаны үшін жауапкершілік мәселелері қамтылады.","id":"lesson-2-paragraph-21"},{"text":"Төртінші бөлім – Міндеттемелердің жекелеген түрлері. Бұл бөлім азаматтық айналымда жиі кездесетін шарттық қатынастарды реттейді. Оларға сатып алу-сату, жалға алу, мердігерлік, заем, сақтандыру, тасымалдау, сақтау, комиссия және басқа да шарт түрлері жатады.","html":"Төртінші бөлім – Міндеттемелердің жекелеген түрлері. Бұл бөлім азаматтық айналымда жиі кездесетін шарттық қатынастарды реттейді. Оларға сатып алу-сату, жалға алу, мердігерлік, заем, сақтандыру, тасымалдау, сақтау, комиссия және басқа да шарт түрлері жатады.","id":"lesson-2-paragraph-22"},{"text":"Бесінші бөлім – Интеллектуалдық меншік құқығы. Мұнда авторлық құқық, патенттік құқық, сабақтас құқықтар, өнертабыстарға және селекциялық жетістіктерге қатысты құқықтар сияқты зияткерлік меншік объектілерін қорғауға байланысты нормалар қарастырылған.","html":"Бесінші бөлім – Интеллектуалдық меншік құқығы. Мұнда авторлық құқық, патенттік құқық, сабақтас құқықтар, өнертабыстарға және селекциялық жетістіктерге қатысты құқықтар сияқты зияткерлік меншік объектілерін қорғауға байланысты нормалар қарастырылған.","id":"lesson-2-paragraph-23"},{"text":"Алтыншы бөлім – Мұрагерлік құқық. Бұл бөлімде өсиет бойынша және заң бойынша мұрагерлік, мұраны қабылдау тәртібі, мұра құрамына кіретін мүлік пен құқықтар сияқты институттар реттеледі.","html":"Алтыншы бөлім – Мұрагерлік құқық. Бұл бөлімде өсиет бойынша және заң бойынша мұрагерлік, мұраны қабылдау тәртібі, мұра құрамына кіретін мүлік пен құқықтар сияқты институттар реттеледі.","id":"lesson-2-paragraph-24"},{"text":"Жетінші бөлім – Халықаралық жеке құқық. Бұл бөлімде шетел элементі бар азаматтық-құқықтық қатынастарды реттеудің жалпы ережелері және коллизиялық нормалар қамтылған.","html":"Жетінші бөлім – Халықаралық жеке құқық. Бұл бөлімде шетел элементі бар азаматтық-құқықтық қатынастарды реттеудің жалпы ережелері және коллизиялық нормалар қамтылған.","id":"lesson-2-paragraph-25"},{"text":"Жалпы алғанда, 1124 баптан тұратын Қазақстан Республикасының Азаматтық кодексі азаматтық айналымдағы барлық құқықтық қатынастарды жүйелі түрде реттейтін негізгі кодификацияланған заң болып табылады. Оның Жалпы және Ерекше бөлімдері азаматтық құқықтың барлық институттарын қамтып, жеке және заңды тұлғалардың мүліктік және мүліктік емес құқықтарын қорғаудың кешенді құқықтық механизмдерін белгілейді.","html":"Жалпы алғанда, 1124 баптан тұратын Қазақстан Республикасының Азаматтық кодексі азаматтық айналымдағы барлық құқықтық қатынастарды жүйелі түрде реттейтін негізгі кодификацияланған заң болып табылады. Оның Жалпы және Ерекше бөлімдері азаматтық құқықтың барлық институттарын қамтып, жеке және заңды тұлғалардың мүліктік және мүліктік емес құқықтарын қорғаудың кешенді құқықтық механизмдерін белгілейді.","id":"lesson-2-paragraph-26"},{"text":"Азаматтық құқықтық қатынастарды реттеуде Азаматтық кодекспен қатар басқа да нормативтік құқықтық актілер қолданылады. Оларға азаматтық қатынастарды реттейтін арнайы заңдар, Қазақстан Республикасы Президентінің заң күші бар және жай жарлықтары, Парламенттің және оның палаталарының қаулылары жатады. Сонымен қатар заңға негізделген нормативтік құқықтық актілер де маңызды рөл атқарады. Мұндай актілерге министрліктердің, атқарушы органдардың және жергілікті органдардың азаматтық қатынастарды реттеуге бағытталған нормативтік актілері кіреді.","html":"Азаматтық құқықтық қатынастарды реттеуде Азаматтық кодекспен қатар басқа да нормативтік құқықтық актілер қолданылады. Оларға азаматтық қатынастарды реттейтін арнайы заңдар, Қазақстан Республикасы Президентінің заң күші бар және жай жарлықтары, Парламенттің және оның палаталарының қаулылары жатады. Сонымен қатар заңға негізделген нормативтік құқықтық актілер де маңызды рөл атқарады. Мұндай актілерге министрліктердің, атқарушы органдардың және жергілікті органдардың азаматтық қатынастарды реттеуге бағытталған нормативтік актілері кіреді.","id":"lesson-2-paragraph-27"},{"text":"Азаматтық құқықта әдет-ғұрыптардың да белгілі бір маңызы бар. Азаматтық кодекстің 3-бабына сәйкес іскерлік айналым әдет-ғұрыптары заңнамаға немесе шарт талаптарына қайшы келмеген жағдайда қолданылуы мүмкін. Әдет-ғұрыптар белгілі бір жергілікті жерде немесе белгілі бір әлеуметтік топ арасында қалыптасқан мінез-құлық ережелері ретінде түсіндіріледі. Ал іскерлік айналым әдет-ғұрыптары кәсіпкерлік қызмет барысында қалыптасқан тәжірибелік ережелерді білдіреді. Мысалы, әртүрлі мемлекеттерде орналасқан сатушы мен сатып алушы арасында тауарды жеткізуге байланысты шығындарды бөлу тәртібі іскерлік айналым әдет-ғұрыптарына жатуы мүмкін [7].","html":"Азаматтық құқықта әдет-ғұрыптардың да белгілі бір маңызы бар. Азаматтық кодекстің 3-бабына сәйкес іскерлік айналым әдет-ғұрыптары заңнамаға немесе шарт талаптарына қайшы келмеген жағдайда қолданылуы мүмкін. Әдет-ғұрыптар белгілі бір жергілікті жерде немесе белгілі бір әлеуметтік топ арасында қалыптасқан мінез-құлық ережелері ретінде түсіндіріледі. Ал іскерлік айналым әдет-ғұрыптары кәсіпкерлік қызмет барысында қалыптасқан тәжірибелік ережелерді білдіреді. Мысалы, әртүрлі мемлекеттерде орналасқан сатушы мен сатып алушы арасында тауарды жеткізуге байланысты шығындарды бөлу тәртібі іскерлік айналым әдет-ғұрыптарына жатуы мүмкін [7].","id":"lesson-2-paragraph-28"},{"text":"Сонымен қатар азаматтық құқықтың қайнар көздерінің бірі – халықаралық шарттар. Қазақстан тәуелсіз мемлекет ретінде басқа мемлекеттермен әртүрлі халықаралық шарттар жасасады. Егер мұндай шарттар азаматтық-құқықтық қатынастарды реттеуге қатысты болса, олар азаматтық құқықтың маңызды қайнар көздерінің бірі болып саналады. Халықаралық шарттардың нормалары ұлттық заңнамадан басым күшке ие, сондықтан ішкі заңдар халықаралық шарттардың ережелеріне қайшы келмеуі тиіс. Егер мұндай қайшылық туындаса, халықаралық шарттардың нормалары қолданылады.","html":"Сонымен қатар азаматтық құқықтың қайнар көздерінің бірі – халықаралық шарттар. Қазақстан тәуелсіз мемлекет ретінде басқа мемлекеттермен әртүрлі халықаралық шарттар жасасады. Егер мұндай шарттар азаматтық-құқықтық қатынастарды реттеуге қатысты болса, олар азаматтық құқықтың маңызды қайнар көздерінің бірі болып саналады. Халықаралық шарттардың нормалары ұлттық заңнамадан басым күшке ие, сондықтан ішкі заңдар халықаралық шарттардың ережелеріне қайшы келмеуі тиіс. Егер мұндай қайшылық туындаса, халықаралық шарттардың нормалары қолданылады.","id":"lesson-2-paragraph-29"},{"text":"Азаматтық заңнаманың тиімді қолданылуы оның уақыт бойынша, кеңістік бойынша және тұлғалар бойынша қолданылу тәртібін нақты анықтауға байланысты. Бұл өлшемдер құқық нормаларының қай кезде, қай жерде және кімге қатысты қолданылатынын айқындайды.","html":"Азаматтық заңнаманың тиімді қолданылуы оның уақыт бойынша, кеңістік бойынша және тұлғалар бойынша қолданылу тәртібін нақты анықтауға байланысты. Бұл өлшемдер құқық нормаларының қай кезде, қай жерде және кімге қатысты қолданылатынын айқындайды.","id":"lesson-2-paragraph-30"},{"text":"Уақыт бойынша қолданылуы заңның күшіне ену сәтін, қолданылу мерзімін және күшінің тоқтатылуын анықтайды. Нормативтік құқықтық актілер ресми жарияланғаннан кейін белгіленген мерзім өткен соң күшіне енеді және тек өз күшіне енгеннен кейін туындайтын құқықтық қатынастарға қолданылады. Заңдардың кері күшке ие болмауы құқықтық тұрақтылықтың маңызды кепілі болып табылады. Тек заңда арнайы көрсетілген жағдайларда ғана құқықтық нормалар бұрын туындаған қатынастарға қолданылуы мүмкін.","html":"Уақыт бойынша қолданылуы заңның күшіне ену сәтін, қолданылу мерзімін және күшінің тоқтатылуын анықтайды. Нормативтік құқықтық актілер ресми жарияланғаннан кейін белгіленген мерзім өткен соң күшіне енеді және тек өз күшіне енгеннен кейін туындайтын құқықтық қатынастарға қолданылады. Заңдардың кері күшке ие болмауы құқықтық тұрақтылықтың маңызды кепілі болып табылады. Тек заңда арнайы көрсетілген жағдайларда ғана құқықтық нормалар бұрын туындаған қатынастарға қолданылуы мүмкін.","id":"lesson-2-paragraph-31"},{"text":"Кеңістік бойынша қолданылуы азаматтық заңнаманың Қазақстан Республикасының бүкіл аумағында бірдей қолданылатынын білдіреді. Қазақстан унитарлық мемлекет болғандықтан, азаматтық заңнаманы аймақтық деңгейде өзгертуге немесе жергілікті нормалармен шектеуге жол берілмейді. Бұл елдің барлық өңірінде азаматтық-құқықтық қатынастардың біркелкі реттелуін қамтамасыз етеді.","html":"Кеңістік бойынша қолданылуы азаматтық заңнаманың Қазақстан Республикасының бүкіл аумағында бірдей қолданылатынын білдіреді. Қазақстан унитарлық мемлекет болғандықтан, азаматтық заңнаманы аймақтық деңгейде өзгертуге немесе жергілікті нормалармен шектеуге жол берілмейді. Бұл елдің барлық өңірінде азаматтық-құқықтық қатынастардың біркелкі реттелуін қамтамасыз етеді.","id":"lesson-2-paragraph-32"},{"text":"Ал тұлғалар бойынша қолданылуы заң нормаларының кімдерге қатысты қолданылатынын анықтайды. Азаматтық заңнама Қазақстан аумағында жүрген барлық азаматтарға, заңды тұлғаларға, мемлекетке және әкімшілік-аумақтық бірліктерге қолданылады. Сонымен қатар кейбір нормалар белгілі бір субъектілерге ғана бағытталуы мүмкін, мысалы кәсіпкерлерге немесе мемлекеттік органдарға.","html":"Ал тұлғалар бойынша қолданылуы заң нормаларының кімдерге қатысты қолданылатынын анықтайды. Азаматтық заңнама Қазақстан аумағында жүрген барлық азаматтарға, заңды тұлғаларға, мемлекетке және әкімшілік-аумақтық бірліктерге қолданылады. Сонымен қатар кейбір нормалар белгілі бір субъектілерге ғана бағытталуы мүмкін, мысалы кәсіпкерлерге немесе мемлекеттік органдарға.","id":"lesson-2-paragraph-33"},{"text":"Осы үш өлшемнің өзара байланысы азаматтық заңнаманың қолданылу механизмін толық әрі үйлесімді етеді. Уақыт бойынша қолданылуы құқықтық қатынастардың тұрақтылығын қамтамасыз етсе, кеңістік бойынша қолданылуы ел аумағында құқық нормаларының біркелкі әрекет етуін бекітеді, ал тұлғалар бойынша қолданылуы заң нормаларының кімге қатысты міндетті екенін айқындайды. Мұндай жүйе азаматтық айналымда құқықтық сенімділік пен құқықтық тәртіптің қалыптасуына ықпал етеді.","html":"Осы үш өлшемнің өзара байланысы азаматтық заңнаманың қолданылу механизмін толық әрі үйлесімді етеді. Уақыт бойынша қолданылуы құқықтық қатынастардың тұрақтылығын қамтамасыз етсе, кеңістік бойынша қолданылуы ел аумағында құқық нормаларының біркелкі әрекет етуін бекітеді, ал тұлғалар бойынша қолданылуы заң нормаларының кімге қатысты міндетті екенін айқындайды. Мұндай жүйе азаматтық айналымда құқықтық сенімділік пен құқықтық тәртіптің қалыптасуына ықпал етеді.","id":"lesson-2-paragraph-34"}],"words":1342,"legacyAnchors":{"lesson-2-section-1":"lesson-2-paragraph-1","lesson-2-section-2":"lesson-2-paragraph-5","lesson-2-section-3":"lesson-2-paragraph-10","lesson-2-section-4":"lesson-2-paragraph-15","lesson-2-section-5":"lesson-2-paragraph-27","lesson-2-section-6":"lesson-2-paragraph-30"}},"3":{"title":"3-ТАҚЫРЫП. АЗАМАТТЫҚ ҚҰҚЫҚТЫҚ ҚАТЫНАСТАР: ҰҒЫМЫ, ТҮРЛЕРІ ЖӘНЕ ЭЛЕМЕНТТЕРІ","blocks":[{"text":"Азаматтық-құқықтық қатынастар азаматтық құқық нормаларымен реттелетін қоғамдық қатынастардың негізгі нысаны болып табылады. Қазақстан Республикасының Азаматтық кодексінің (бұдан әрі ҚР АК) 1-бабына сәйкес, азаматтық заңнама мүліктік және онымен байланысты жеке мүліктік емес қатынастарды, сондай-ақ қатысушыларының теңдігіне, ерік бостандығына және мүліктік дербестігіне негізделген өзге де қатынастарды реттейді.","html":"Азаматтық-құқықтық қатынастар азаматтық құқық нормаларымен реттелетін қоғамдық қатынастардың негізгі нысаны болып табылады. Қазақстан Республикасының Азаматтық кодексінің (бұдан әрі ҚР АК) 1-бабына сәйкес, азаматтық заңнама мүліктік және онымен байланысты жеке мүліктік емес қатынастарды, сондай-ақ қатысушыларының теңдігіне, ерік бостандығына және мүліктік дербестігіне негізделген өзге де қатынастарды реттейді.","id":"lesson-3-paragraph-1"},{"text":"Азаматтық-құқықтық қатынастар дегеніміз – азаматтық құқық нормалары арқылы реттелетін, қатысушылары заң жүзінде тең болып табылатын, мүліктік немесе жеке мүліктік емес игіліктерге байланысты қоғамдық қатынастар. Бұл қатынастардың басты ерекшелігі – тараптардың әкімшілік бағыныштылықта болмауы және олардың құқықтық теңдігі [8].","html":"Азаматтық-құқықтық қатынастар дегеніміз – азаматтық құқық нормалары арқылы реттелетін, қатысушылары заң жүзінде тең болып табылатын, мүліктік немесе жеке мүліктік емес игіліктерге байланысты қоғамдық қатынастар. Бұл қатынастардың басты ерекшелігі – тараптардың әкімшілік бағыныштылықта болмауы және олардың құқықтық теңдігі [8].","id":"lesson-3-paragraph-2"},{"text":"Азаматтық құқықты реттеу тәсілдері диспозитивтік сипатқа ие. Яғни, қатынастардың мазмұны тараптардың өз еркімен, шарт екендігі қағидатына сәйкес айқындалады. Бұл азаматтық-құқықтық қатынастарды жария-құқықтық қатынастардан ажырататын негізгі белгі болып табылады.","html":"Азаматтық құқықты реттеу тәсілдері диспозитивтік сипатқа ие. Яғни, қатынастардың мазмұны тараптардың өз еркімен, шарт екендігі қағидатына сәйкес айқындалады. Бұл азаматтық-құқықтық қатынастарды жария-құқықтық қатынастардан ажырататын негізгі белгі болып табылады.","id":"lesson-3-paragraph-3"},{"text":"Азаматтық-құқықтық қатынастарды мазмұнына қарай мүліктік және жеке мүліктік емес қатынастар деп бөлуге болады. Мүліктік қатынастарға меншік құқығы, міндеттемелік құқықтар, мұрагерлік қатынастар жатады. Ал жеке мүліктік емес қатынастарға адамның ар-намысы, қадір-қасиеті, іскерлік беделі, авторлық құқықтармен байланысты қатынастар кіреді.","html":"Азаматтық-құқықтық қатынастарды мазмұнына қарай мүліктік және жеке мүліктік емес қатынастар деп бөлуге болады. Мүліктік қатынастарға меншік құқығы, міндеттемелік құқықтар, мұрагерлік қатынастар жатады. Ал жеке мүліктік емес қатынастарға адамның ар-намысы, қадір-қасиеті, іскерлік беделі, авторлық құқықтармен байланысты қатынастар кіреді.","id":"lesson-3-paragraph-4"},{"text":"Сонымен қатар азаматтық-құқықтық қатынастар абсолюттік және салыстырмалы болып бөлінеді. Абсолюттік қатынастарда құқық иесіне барлық үшінші тұлғалар қарсы тұрады (мысалы, меншік құқығы), ал салыстырмалы қатынастарда құқықтар мен міндеттер нақты тұлғалар арасында туындайды (шарттық міндеттемелер).","html":"Сонымен қатар азаматтық-құқықтық қатынастар абсолюттік және салыстырмалы болып бөлінеді. Абсолюттік қатынастарда құқық иесіне барлық үшінші тұлғалар қарсы тұрады (мысалы, меншік құқығы), ал салыстырмалы қатынастарда құқықтар мен міндеттер нақты тұлғалар арасында туындайды (шарттық міндеттемелер).","id":"lesson-3-paragraph-5"},{"text":"Азаматтық-құқықтық қатынастың құрылымы үш элементтен тұрады. Олар: субъект, объект және мазмұн.","html":"Азаматтық-құқықтық қатынастың құрылымы үш элементтен тұрады. Олар: субъект, объект және мазмұн.","id":"lesson-3-paragraph-6"},{"text":"Азаматтық-құқықтық қатынастың субъектілері – бұл азаматтық құқықтар мен міндеттерге ие болып, оларды жүзеге асыра алатын қатысушылар. Қазақстан. Республикасының Азаматтық кодексіне сәйкес азаматтық-құқықтық қатынастардың субъектілері болып мыналар табылады:","html":"Азаматтық-құқықтық қатынастың субъектілері<strong> </strong>– бұл азаматтық құқықтар мен міндеттерге ие болып, оларды жүзеге асыра алатын қатысушылар. Қазақстан. Республикасының Азаматтық кодексіне сәйкес азаматтық-құқықтық қатынастардың субъектілері болып мыналар табылады:","id":"lesson-3-paragraph-7"},{"text":"жеке тұлғалар (Қазақстан Республикасының азаматтары, шетел азаматтары, азаматтығы жоқ адамдар);","html":"жеке тұлғалар (Қазақстан Республикасының азаматтары, шетел азаматтары, азаматтығы жоқ адамдар);","list":{"id":"1","ordered":false,"marker":"-","start":1},"id":"lesson-3-paragraph-8"},{"text":"заңды тұлғалар;","html":"заңды тұлғалар;","list":{"id":"1","ordered":false,"marker":"-","start":1},"id":"lesson-3-paragraph-9"},{"text":"мемлекет, әкімшілік-аумақтық бірліктер.","html":"мемлекет, әкімшілік-аумақтық бірліктер.","list":{"id":"1","ordered":false,"marker":"-","start":1},"id":"lesson-3-paragraph-10"},{"text":"Жеке тұлғалардың азаматтық құқықтық мәртебесі олардың құқық қабілеттілігі мен әрекет қабілеттілігіне байланысты айқындалады. Құқық қабілеттілік туған сәттен бастап пайда болып, қайтыс болған кезде тоқтатылады, ал әрекет қабілеттілігі тұлғаның жасына және психикалық жағдайына байланысты белгіленеді.","html":"<strong> </strong>Жеке тұлғалардың азаматтық құқықтық мәртебесі олардың құқық қабілеттілігі мен әрекет қабілеттілігіне байланысты айқындалады. Құқық қабілеттілік туған сәттен бастап пайда болып, қайтыс болған кезде тоқтатылады, ал әрекет қабілеттілігі тұлғаның жасына және психикалық жағдайына байланысты белгіленеді.","id":"lesson-3-paragraph-11"},{"text":"Заңды тұлғалар дербес мүлкі бар, өз міндеттемелері бойынша сол мүлкімен жауап беретін, өз атынан құқықтар мен міндеттерге ие бола алатын ұйымдар болып табылады. Мемлекет азаматтық-құқықтық қатынастарға қатысқан кезде билік өкілеттігін пайдаланбай, өзге субъектілермен тең жағдайда әрекет етеді.","html":"Заңды тұлғалар дербес мүлкі бар, өз міндеттемелері бойынша сол мүлкімен жауап беретін, өз атынан құқықтар мен міндеттерге ие бола алатын ұйымдар болып табылады. Мемлекет азаматтық-құқықтық қатынастарға қатысқан кезде билік өкілеттігін пайдаланбай, өзге субъектілермен тең жағдайда әрекет етеді.","id":"lesson-3-paragraph-12"},{"text":"Азаматтық-құқықтық қатынастың объектісі – бұл құқықтық қатынас бағытталған және сол қатынастың аясында субъективтік құқықтар мен міндеттер жүзеге асырылатын игіліктер. Яғни азаматтық құқық субъектілері арасындағы қатынастар белгілі бір мүліктік немесе мүліктік емес игіліктерге байланысты туындайды.","html":"Азаматтық-құқықтық қатынастың объектісі – бұл құқықтық қатынас бағытталған және сол қатынастың аясында субъективтік құқықтар мен міндеттер жүзеге асырылатын игіліктер. Яғни азаматтық құқық субъектілері арасындағы қатынастар белгілі бір мүліктік немесе мүліктік емес игіліктерге байланысты туындайды.","id":"lesson-3-paragraph-13"},{"text":"Қазақстан Республикасының Азаматтық кодексінің 115-бабына сәйкес азаматтық құқық объектілеріне әртүрлі материалдық және материалдық емес игіліктер жатады. Атап айтқанда, азаматтық құқық объектілеріне заттар, ақша және бағалы қағаздар, жұмыстар мен қызметтер, зияткерлік қызмет нәтижелері, сондай-ақ жеке мүліктік емес игіліктер кіреді.","html":"Қазақстан Республикасының Азаматтық кодексінің 115-бабына сәйкес азаматтық құқық объектілеріне әртүрлі материалдық және материалдық емес игіліктер жатады. Атап айтқанда, азаматтық құқық объектілеріне заттар, ақша және бағалы қағаздар, жұмыстар мен қызметтер, зияткерлік қызмет нәтижелері, сондай-ақ жеке мүліктік емес игіліктер кіреді.","id":"lesson-3-paragraph-14"},{"text":"Заттарға жылжымалы және жылжымайтын мүлік жатады. Жылжымайтын мүлікке жер учаскелері, ғимараттар, құрылыстар және олармен тығыз байланысты өзге де объектілер кіреді. Ал жылжымалы мүлікке көлік құралдары, тұрмыстық заттар және басқа да қозғалатын мүліктер жатады.","html":"Заттарға жылжымалы және жылжымайтын мүлік жатады. Жылжымайтын мүлікке жер учаскелері, ғимараттар, құрылыстар және олармен тығыз байланысты өзге де объектілер кіреді. Ал жылжымалы мүлікке көлік құралдары, тұрмыстық заттар және басқа да қозғалатын мүліктер жатады.","id":"lesson-3-paragraph-15"},{"text":"Ақша және бағалы қағаздар да азаматтық құқықтың маңызды объектілерінің бірі болып табылады. Олар азаматтық айналымда төлем құралы ретінде немесе мүліктік құқықтарды куәландыратын құрал ретінде қолданылады.","html":"Ақша және бағалы қағаздар да азаматтық құқықтың маңызды объектілерінің бірі болып табылады. Олар азаматтық айналымда төлем құралы ретінде немесе мүліктік құқықтарды куәландыратын құрал ретінде қолданылады.","id":"lesson-3-paragraph-16"},{"text":"Жұмыстар мен қызметтер азаматтық-құқықтық қатынастардың тағы бір маңызды объектісі болып табылады. Мысалы, мердігерлік шарт бойынша орындалатын жұмыстар немесе қызмет көрсету шарты бойынша көрсетілетін қызметтер азаматтық құқық объектісі ретінде танылады.","html":"Жұмыстар мен қызметтер азаматтық-құқықтық қатынастардың тағы бір маңызды объектісі болып табылады. Мысалы, мердігерлік шарт бойынша орындалатын жұмыстар немесе қызмет көрсету шарты бойынша көрсетілетін қызметтер азаматтық құқық объектісі ретінде танылады.","id":"lesson-3-paragraph-17"},{"text":"Зияткерлік қызметтің нәтижелеріне ғылым, әдебиет және өнер туындылары, өнертабыстар, пайдалы модельдер, өнеркәсіптік үлгілер және басқа да шығармашылық қызмет нәтижелері жатады. Объект азаматтық - құқықтық қатынастың мазмұнын айқындауда маңызды рөл атқарады, өйткені құқықтар мен міндеттер дәл осы объектіге қатысты жүзеге асырылады. Мысалы, меншік құқығында объект ретінде мүлік қарастырылса, авторлық құқықта – шығармашылық қызмет нәтижесі объект болып табылады.","html":"Зияткерлік қызметтің нәтижелеріне ғылым, әдебиет және өнер туындылары, өнертабыстар, пайдалы модельдер, өнеркәсіптік үлгілер және басқа да шығармашылық қызмет нәтижелері жатады. Объект азаматтық - құқықтық қатынастың мазмұнын айқындауда маңызды рөл атқарады, өйткені құқықтар мен міндеттер дәл осы объектіге қатысты жүзеге асырылады. Мысалы, меншік құқығында объект ретінде мүлік қарастырылса, авторлық құқықта – шығармашылық қызмет нәтижесі объект болып табылады.","id":"lesson-3-paragraph-18"},{"text":"Азаматтық-құқықтық қатынастың мазмұны субъективтік құқықтар мен заңды міндеттердің жиынтығынан тұрады. Субъективтік құқық – бұл құқық субъектісінің белгілі бір әрекет жасауға, басқа тұлғалардан тиісті мінез-құлықты талап етуге немесе белгілі бір әрекеттер тартынуға заңмен немесе шартпен берілген мүмкіндігі.","html":"Азаматтық-құқықтық қатынастың мазмұны<strong> </strong>субъективтік құқықтар мен заңды міндеттердің жиынтығынан тұрады. Субъективтік құқық – бұл құқық субъектісінің белгілі бір әрекет жасауға, басқа тұлғалардан тиісті мінез-құлықты талап етуге немесе белгілі бір әрекеттер тартынуға заңмен немесе шартпен берілген мүмкіндігі.","id":"lesson-3-paragraph-19"},{"text":"Ал заңды міндет – бұл құқық субъектісінің екінші тараптың субъективтік құқығын жүзеге асыру үшін қажетті мінез-құлықты орындау міндеті. Заңды міндет әрекет жасау немесе әрекеттен тартыну нысанында көрініс табуы мүмкін.","html":"Ал заңды міндет – бұл құқық субъектісінің екінші тараптың субъективтік құқығын жүзеге асыру үшін қажетті мінез-құлықты орындау міндеті. Заңды міндет әрекет жасау немесе әрекеттен тартыну нысанында көрініс табуы мүмкін.","id":"lesson-3-paragraph-20"},{"text":"Мазмұн азаматтық-құқықтық қатынастың өзгермелі элементі болып табылады, себебі ол құқықтық қатынастардың пайда болуы, өзгеруі және тоқтатылуы барысында өзгеруі мүмкін.","html":"Мазмұн азаматтық-құқықтық қатынастың өзгермелі элементі болып табылады, себебі ол құқықтық қатынастардың пайда болуы, өзгеруі және тоқтатылуы барысында өзгеруі мүмкін.","id":"lesson-3-paragraph-21"},{"text":"Жалпы алғанда, азаматтық-құқықтық қатынас субъект, объект және мазмұн сияқты өзара тығыз байланысты элементтерден тұрады. Бұл элементтердің біреуінің болмауы азаматтық-құқықтық қатынастың пайда болуына кедергі болады. Азаматтық-құқықтық қатынастардың элементтерін дұрыс түсіну азаматтық заңнаманы тиімді қолданудың және құқықтық дауларды дұрыс шешудің маңызды шарты болып табылады.","html":"Жалпы алғанда, азаматтық-құқықтық қатынас субъект, объект және мазмұн сияқты өзара тығыз байланысты элементтерден тұрады. Бұл элементтердің біреуінің болмауы азаматтық-құқықтық қатынастың пайда болуына кедергі болады. Азаматтық-құқықтық қатынастардың элементтерін дұрыс түсіну азаматтық заңнаманы тиімді қолданудың және құқықтық дауларды дұрыс шешудің маңызды шарты болып табылады.","id":"lesson-3-paragraph-22"},{"text":"Азаматтық-құқықтық қатынастар белгілі бір заңды фактілердің негізінде пайда болады, өзгереді немесе тоқтатылады. ҚР АК-нің 7-бабына сәйкес заңды фактілерге шарттар мен өзге мәмілелер, әкімшілік актілер, сот шешімдері, зиян келтіру, негізсіз баю, оқиғалар және өзге де әрекеттер жатады [9].","html":"Азаматтық-құқықтық қатынастар белгілі бір заңды фактілердің негізінде пайда болады, өзгереді немесе тоқтатылады. ҚР АК-нің 7-бабына сәйкес заңды фактілерге шарттар мен өзге мәмілелер, әкімшілік актілер, сот шешімдері, зиян келтіру, негізсіз баю, оқиғалар және өзге де әрекеттер жатады [9].","id":"lesson-3-paragraph-23"},{"text":"Азаматтық-құқықтық қатынастардың ең кең таралған пайда болу негізі – шарт. Шарт тараптардың құқықтары мен міндеттерін айқындай отырып, құқықтық қатынастың мазмұнын қалыптастырады. Сонымен қатар қатынастар заңда тікелей көзделген жағдайларда да туындауы мүмкін. Құқықтық қатынастардың өзгеруі тараптардың келісімімен, шарт талаптарың қайта қарау арқылы немесе заңда көзделген өзге де негіздер бойынша жүзеге асырылады. Мысалы, міндеттеменің мазмұнын өзгерту, тарапты ауыстыру (цессия, борышты аудару) құқықтық қатынастың өзгеруіне әкеледі.","html":"Азаматтық-құқықтық қатынастардың ең кең таралған пайда болу негізі – шарт. Шарт тараптардың құқықтары мен міндеттерін айқындай отырып, құқықтық қатынастың мазмұнын қалыптастырады. Сонымен қатар қатынастар заңда тікелей көзделген жағдайларда да туындауы мүмкін. Құқықтық қатынастардың өзгеруі тараптардың келісімімен, шарт талаптарың қайта қарау арқылы немесе заңда көзделген өзге де негіздер бойынша жүзеге асырылады. Мысалы, міндеттеменің мазмұнын өзгерту, тарапты ауыстыру (цессия, борышты аудару) құқықтық қатынастың өзгеруіне әкеледі.","id":"lesson-3-paragraph-24"},{"text":"Азаматтық-құқықтық қатынастардың тоқтатылуы міндеттеменің орындалуына, тараптардың келісіміне, мерзімнің өтуіне, борышкердің немесе кредитордың жойылуына, сондай-ақ заңда көзделген өзге де жағдайларға байланысты болады. Міндеттеменің тиісті түрде орындалуы – азаматтық-құқықтық қатынастарды тоқтаудың негізгі және ең жиі кездесетін тәсілі болып табылады.","html":"Азаматтық-құқықтық қатынастардың тоқтатылуы міндеттеменің орындалуына, тараптардың келісіміне, мерзімнің өтуіне, борышкердің немесе кредитордың жойылуына, сондай-ақ заңда көзделген өзге де жағдайларға байланысты болады. Міндеттеменің тиісті түрде орындалуы – азаматтық-құқықтық қатынастарды тоқтаудың негізгі және ең жиі кездесетін тәсілі болып табылады.","id":"lesson-3-paragraph-25"}],"words":783,"legacyAnchors":{"lesson-3-section-1":"lesson-3-paragraph-1","lesson-3-section-2":"lesson-3-paragraph-4","lesson-3-section-3":"lesson-3-paragraph-6","lesson-3-section-4":"lesson-3-paragraph-13","lesson-3-section-5":"lesson-3-paragraph-19"}},"4":{"title":"4-ТАҚЫРЫП. АЗАМАТТЫҚ-ҚҰҚЫҚТЫҚ ҚАТЫНАСТЫҢ СУБЪЕКТІ РЕТІНДЕ  ЖЕКЕ ТҰЛҒАЛАР","blocks":[{"text":"Азаматтық құқық саласындағы қоғамдық қатынастардың негізгі қатысушыларының бірі – жеке тұлғалар болып табылады. Жеке тұлғалардың азаматтық-құқықтық қатынастарға қатысуы азаматтық құқықтың адамға, оның мүдделері мен еркіндігіне бағдарланғанын көрсетеді. Осы тұрғыда жеке тұлға азаматтық құқық субъектісі ретінде азаматтық айналымда дербес орын алады және құқықтық қатынастардың қалыптасуы мен дамуына тікелей ықпал етеді.","html":"Азаматтық құқық саласындағы қоғамдық қатынастардың негізгі қатысушыларының бірі – жеке тұлғалар болып табылады. Жеке тұлғалардың азаматтық-құқықтық қатынастарға қатысуы азаматтық құқықтың адамға, оның мүдделері мен еркіндігіне бағдарланғанын көрсетеді. Осы тұрғыда жеке тұлға азаматтық құқық субъектісі ретінде азаматтық айналымда дербес орын алады және құқықтық қатынастардың қалыптасуы мен дамуына тікелей ықпал етеді.","id":"lesson-4-paragraph-1"},{"text":"Қазақстан Республикасының Азаматтық кодексінде жеке тұлға ұғымы нақты бекітіліп, оның азаматтық құқықтық мәртебесінің негізгі элементтері айқындалған. Атап айтқанда, Кодекске сәйкес жеке тұлға ретінде Қазақстан Республикасының азаматтары, шетел азаматтары сондай-ақ азаматтығы жоқ адамдар танылады. Бұл ереже азаматтық құқықтық қатынастардың субъектілік құрамының әмбебап сипатын көрсетіп, теңдік қағидасын қамтамасыз етеді.","html":"Қазақстан Республикасының Азаматтық кодексінде жеке тұлға ұғымы нақты бекітіліп, оның азаматтық құқықтық мәртебесінің негізгі элементтері айқындалған. Атап айтқанда, Кодекске сәйкес жеке тұлға ретінде Қазақстан Республикасының азаматтары, шетел азаматтары сондай-ақ азаматтығы жоқ адамдар танылады. Бұл ереже азаматтық құқықтық қатынастардың субъектілік құрамының әмбебап сипатын көрсетіп, теңдік қағидасын қамтамасыз етеді.","id":"lesson-4-paragraph-2"},{"text":"Жеке тұлғаның азаматтық-құқықтық мәртебесі, ең алдымен, оның құқық қабілеттілігімен және әрекет қабілеттілігімен айқындалады. Азаматтық құқық қабілеттілігі жеке тұлғаның азаматтық құқықтарға ие болу және міндеттерді атқару мүмкіндігін білдіреді. ҚР Азаматтық кодексінде құқық қабілеттілігі адамның туған сәтінен бастап пайда болып, оның қайтыс болуымен тоқтатылатыны көзделген. Бұл қағида жеке тұлғаның құқықтық мәртебесінің табиғи және ажырамас сипатын көрсетеді [10].","html":"Жеке тұлғаның азаматтық-құқықтық мәртебесі, ең алдымен, оның құқық қабілеттілігімен және әрекет қабілеттілігімен айқындалады. Азаматтық құқық қабілеттілігі жеке тұлғаның азаматтық құқықтарға ие болу және міндеттерді атқару мүмкіндігін білдіреді. ҚР Азаматтық кодексінде құқық қабілеттілігі адамның туған сәтінен бастап пайда болып, оның қайтыс болуымен тоқтатылатыны көзделген. Бұл қағида жеке тұлғаның құқықтық мәртебесінің табиғи және ажырамас сипатын көрсетеді [10].","id":"lesson-4-paragraph-3"},{"text":"Құқық қабілеттілігі барлық жеке тұлғалар үшін тең болып табылады және ол мүліктік те, мүліктік емес те құқықтарды қамтиды. Мәселен, жеке тұлға меншік иесі болуға, мұрагерлікке, кәсіпкерлік қызметпен айналысуға, мәмілелер жасауға, сондай-ақ ар-намысын, қадір-қасиетін және іскерлік беделін қорғауға құқылы. Бұл құқықтардың көлемі жеке тұлғаның жынысына, ұлтына, әлеуметтік жағдайына немесе тұрғылықты жеріне байланысты шектелмейді.","html":"Құқық қабілеттілігі барлық жеке тұлғалар үшін тең болып табылады және ол мүліктік те, мүліктік емес те құқықтарды қамтиды. Мәселен, жеке тұлға меншік иесі болуға, мұрагерлікке, кәсіпкерлік қызметпен айналысуға, мәмілелер жасауға, сондай-ақ ар-намысын, қадір-қасиетін және іскерлік беделін қорғауға құқылы. Бұл құқықтардың көлемі жеке тұлғаның жынысына, ұлтына, әлеуметтік жағдайына немесе тұрғылықты жеріне байланысты шектелмейді.","id":"lesson-4-paragraph-4"},{"text":"Азаматтық құқықтық қатынастардағы жеке тұлғаның құқықтық мәртебесін айқындайтын келесі маңызды элемент – әрекет қабілеттілігі. Әрекет қабілеттілігі жеке тұлғаның өз әрекеттері арқылы азаматтық құқықтар мен міндеттерді жүзеге асыру қабілетін білдіреді. ҚР Азаматтық кодексіне сәйкес толық әрекет қабілеттілігі, әдетте, он сегіз жасқа толған сәттен бастап пайда болады. Бұл жас шамасы тұлғаның азаматтық айналымға саналы және жауапты түрде қатысу мүмкіндігін білдіреді.","html":"Азаматтық құқықтық қатынастардағы жеке тұлғаның құқықтық мәртебесін айқындайтын келесі маңызды элемент – әрекет қабілеттілігі. Әрекет қабілеттілігі жеке тұлғаның өз әрекеттері арқылы азаматтық құқықтар мен міндеттерді жүзеге асыру қабілетін білдіреді. ҚР Азаматтық кодексіне сәйкес толық әрекет қабілеттілігі, әдетте, он сегіз жасқа толған сәттен бастап пайда болады. Бұл жас шамасы тұлғаның азаматтық айналымға саналы және жауапты түрде қатысу мүмкіндігін білдіреді.","id":"lesson-4-paragraph-5"},{"text":"Сонымен қатар, Азаматтық кодексте әрекет қабілеттілігінің шектелген және ішінара, түрлері де көзделген. Кәмелетке толмаған тұлғалар жас ерекшеліктеріне қарай белгілі бір көлемде азаматтық құқықтарды дербес жүзеге асыра алады. Бұл нормалар жеке тұлғаның мүдделерін қорғауға және оның құқықтық қауіпсіздігін қамтамасыз етуге бағытталған. Ал сот шешімімен әрекет қабілеттілігі шектелген немесе әрекетке қабілетсіз деп танылған тұлғалардың азаматтық құқықтық қатынастарға қатысуы заңда белгіленген тәртіппен жүзеге асырылады.","html":"Сонымен қатар, Азаматтық кодексте әрекет қабілеттілігінің шектелген және ішінара, түрлері де көзделген. Кәмелетке толмаған тұлғалар жас ерекшеліктеріне қарай белгілі бір көлемде азаматтық құқықтарды дербес жүзеге асыра алады. Бұл нормалар жеке тұлғаның мүдделерін қорғауға және оның құқықтық қауіпсіздігін қамтамасыз етуге бағытталған. Ал сот шешімімен әрекет қабілеттілігі шектелген немесе әрекетке қабілетсіз деп танылған тұлғалардың азаматтық құқықтық қатынастарға қатысуы заңда белгіленген тәртіппен жүзеге асырылады.","id":"lesson-4-paragraph-6"},{"text":"Жеке тұлғалар азаматтық-құқықтық қатынастарға әртүрлі құқықтық негіздер арқылы қатысады. Олар шарттық қатынастардың тараптары ретінде, мұрагер ретінде, меншік иесі ретінде, зиян келтіруші немесе зиян шегуші тұлға ретінде әрекет ете алады. Бұл ретте азаматтық құқықтық қатынастардың мазмұны жеке тұлғаның субъективтік құқықтары мен заңдық міндеттерінің жиынтығынан тұрады.","html":"Жеке тұлғалар азаматтық-құқықтық қатынастарға әртүрлі құқықтық негіздер арқылы қатысады. Олар шарттық қатынастардың тараптары ретінде, мұрагер ретінде, меншік иесі ретінде, зиян келтіруші немесе зиян шегуші тұлға ретінде әрекет ете алады. Бұл ретте азаматтық құқықтық қатынастардың мазмұны жеке тұлғаның субъективтік құқықтары мен заңдық міндеттерінің жиынтығынан тұрады.","id":"lesson-4-paragraph-7"},{"text":"Азаматтық кодексте жеке тұлғалардың құқықтарын жүзеге асыру қағидаттары да нақты бекітілген. Атап айтқанда, азаматтық құқықтарды адал, ақылға қонымды және әділ түрде жүзеге асыру талабы белгіленген. Бұл қағида жеке тұлғаның өз құқықтарын жүзеге асыру барысында басқа қатысушылардың құқықтары мен заңды мүдделеріне зиян келтірмеуін қамтамасыз етеді. Құқықты теріс пайдалану азаматтық құқықта жол берілмейтін әрекет ретінде танылады және ол заңмен белгіленген құқықтық салдарға әкеп соғады.","html":"Азаматтық кодексте жеке тұлғалардың құқықтарын жүзеге асыру қағидаттары да нақты бекітілген. Атап айтқанда, азаматтық құқықтарды адал, ақылға қонымды және әділ түрде жүзеге асыру талабы белгіленген. Бұл қағида жеке тұлғаның өз құқықтарын жүзеге асыру барысында басқа қатысушылардың құқықтары мен заңды мүдделеріне зиян келтірмеуін қамтамасыз етеді. Құқықты теріс пайдалану азаматтық құқықта жол берілмейтін әрекет ретінде танылады және ол заңмен белгіленген құқықтық салдарға әкеп соғады.","id":"lesson-4-paragraph-8"},{"text":"Жеке тұлғалардың азаматтық-құқықтық қатынастардағы жауапкершілігі де маңызды мәнге ие. Азаматтық құқықта жеке тұлға өз міндеттерін орындамағаны немесе тиісінше орындамағаны үшін мүліктік жауапкершілікке тартылады. Бұл жауапкершілік, әдетте, келтірілген залалды өтеу, айыппұл немесе өсімпұл төлеу түрінде көрініс табады. Мұндай құқықтық тетіктер азаматтық айналымдағы тұрақтылық пен сенімділікті қамтамасыз етуге бағытталған.","html":"Жеке тұлғалардың азаматтық-құқықтық қатынастардағы жауапкершілігі де маңызды мәнге ие. Азаматтық құқықта жеке тұлға өз міндеттерін орындамағаны немесе тиісінше орындамағаны үшін мүліктік жауапкершілікке тартылады. Бұл жауапкершілік, әдетте, келтірілген залалды өтеу, айыппұл немесе өсімпұл төлеу түрінде көрініс табады. Мұндай құқықтық тетіктер азаматтық айналымдағы тұрақтылық пен сенімділікті қамтамасыз етуге бағытталған.","id":"lesson-4-paragraph-9"},{"text":"Жеке тұлғалар азаматтық-құқықтық қатынастардың негізгі әрі әмбебап субъектілері болып табылады. Олардың құқықтық мәртебесі ҚР Азаматтық кодексінде жан-жақты реттеліп, құқық қабілеттілігі мен әрекет қабілеттілігі арқылы айқындалады. Жеке тұлғалардың азаматтық айналымға қатысуы құқықтық теңдік, еркіндік және жауапкершілік қағидаттарына негізделеді. Бұл өз кезегінде азаматтық құқықтың қоғамдағы реттеуші рөлін күшейтіп, жеке адамның құқықтары мен заңды мүдделерін тиімді қорғауға мүмкіндік береді.","html":"Жеке тұлғалар азаматтық-құқықтық қатынастардың негізгі әрі әмбебап субъектілері болып табылады. Олардың құқықтық мәртебесі ҚР Азаматтық кодексінде жан-жақты реттеліп, құқық қабілеттілігі мен әрекет қабілеттілігі арқылы айқындалады. Жеке тұлғалардың азаматтық айналымға қатысуы құқықтық теңдік, еркіндік және жауапкершілік қағидаттарына негізделеді. Бұл өз кезегінде азаматтық құқықтың қоғамдағы реттеуші рөлін күшейтіп, жеке адамның құқықтары мен заңды мүдделерін тиімді қорғауға мүмкіндік береді.","id":"lesson-4-paragraph-10"},{"text":"Жеке тұлғаның азаматтық-құқықтық қатынастарға қатысу мүмкіндігі оның әрекет қабілеттілігімен тікелей байланысты. Әрекет қабілеттілігі азаматтық құқықта тұлғаның өз әрекеттері арқылы азаматтық құқықтар мен міндеттерді иелену, оларды жүзеге асыру және орындау қабілетін білдіреді. Қазақстан Республикасының Азаматтық кодексінде әрекет қабілеттіліктің көлемі тұлғаның жасына, психикалық жағдайына және сот шешіміне байланысты айқындалады.","html":"Жеке тұлғаның азаматтық-құқықтық қатынастарға қатысу мүмкіндігі оның әрекет қабілеттілігімен тікелей байланысты. Әрекет қабілеттілігі азаматтық құқықта тұлғаның өз әрекеттері арқылы азаматтық құқықтар мен міндеттерді иелену, оларды жүзеге асыру және орындау қабілетін білдіреді. Қазақстан Республикасының Азаматтық кодексінде әрекет қабілеттіліктің көлемі тұлғаның жасына, психикалық жағдайына және сот шешіміне байланысты айқындалады.","id":"lesson-4-paragraph-11"},{"text":"ҚР Азаматтық кодексіне сәйкес он төрт жасқа дейінгі кәмелетке толмағандар толық әрекет қабілеттілігіне ие болмайды. Бұл жас санатындағы тұлғалар, әдетте, өз атынан азаматтық-құқықтық мәмілелер жасай алмайды. Олардың атынан мәмілелерді ата-аналары, асырап алушылары немесе қамқоршылары жүзеге асырады.","html":"ҚР Азаматтық кодексіне сәйкес он төрт жасқа дейінгі кәмелетке толмағандар толық әрекет қабілеттілігіне ие болмайды. Бұл жас санатындағы тұлғалар, әдетте, өз атынан азаматтық-құқықтық мәмілелер жасай алмайды. Олардың атынан мәмілелерді ата-аналары, асырап алушылары немесе қамқоршылары жүзеге асырады.","id":"lesson-4-paragraph-12"},{"text":"Сонымен бірге заңда тұрмыстық ұсақ мәмілелер жасау мүмкіндігі көзделген. Мұндай мәмілелер баланың жасына сай келетін, күнделікті тұрмыстық қажеттіліктерді қанағаттандыруға бағытталған және айтарлықтай мүліктік салдарға әкеп соқпайтын әрекеттерді қамтиды. Бұл ереже баланың күнделікті өмірге бейімделуін қамтамасыз етуге және оның мүдделерін қорғауға бағытталған.","html":"Сонымен бірге заңда тұрмыстық ұсақ мәмілелер жасау мүмкіндігі көзделген. Мұндай мәмілелер баланың жасына сай келетін, күнделікті тұрмыстық қажеттіліктерді қанағаттандыруға бағытталған және айтарлықтай мүліктік салдарға әкеп соқпайтын әрекеттерді қамтиды. Бұл ереже баланың күнделікті өмірге бейімделуін қамтамасыз етуге және оның мүдделерін қорғауға бағытталған.","id":"lesson-4-paragraph-13"},{"text":"Он төрт жастан он сегіз жасқа дейінгі кәмелетке толмағандар ішінара әрекет қабілеттілігіне ие болып табылады. ҚР Азаматтық кодексінде бұл жас санатындағы тұлғаларға белгілі бір азаматтық құқықтарды дербес жүзеге асыру мүмкіндігі берілген. Атап айтқанда, олар өз еңбегінен, стипендиясынан немесе өзге де заңды табыстарынан өз бетінше билік етуге құқылы [11].","html":"Он төрт жастан он сегіз жасқа дейінгі кәмелетке толмағандар ішінара әрекет қабілеттілігіне ие болып табылады. ҚР Азаматтық кодексінде бұл жас санатындағы тұлғаларға белгілі бір азаматтық құқықтарды дербес жүзеге асыру мүмкіндігі берілген. Атап айтқанда, олар өз еңбегінен, стипендиясынан немесе өзге де заңды табыстарынан өз бетінше билік етуге құқылы [11].","id":"lesson-4-paragraph-14"},{"text":"Сонымен қатар, мұндай тұлғалар авторлық құқық объектілеріне құқықтарды жүзеге асыра алады, банктік салымдар енгізуге және оларды басқаруға құқылы. Алайда, өзге мәмілелерді жасау үшін олардың заңды өкілдерінің келісімі талап етіледі. Бұл шектеулер кәмелетке толмаған тұлғаның құқықтарын қорғау және оның азаматтық айналымдағы қауіпсіздігін қамтамасыз ету мақсатында белгіленген.","html":"Сонымен қатар, мұндай тұлғалар авторлық құқық объектілеріне құқықтарды жүзеге асыра алады, банктік салымдар енгізуге және оларды басқаруға құқылы. Алайда, өзге мәмілелерді жасау үшін олардың заңды өкілдерінің келісімі талап етіледі. Бұл шектеулер кәмелетке толмаған тұлғаның құқықтарын қорғау және оның азаматтық айналымдағы қауіпсіздігін қамтамасыз ету мақсатында белгіленген.","id":"lesson-4-paragraph-15"},{"text":"Әрекет қабілеттілікті шектеу институты азаматтық құқықта ерекше мәнге ие. ҚР Азаматтық кодексіне сәйкес, спирттік ішімдіктерді, есірткі немесе психотроптық заттарды шамадан тыс пайдалануы салдарынан өз отбасын ауыр материалдық жағдайға ұшырататын тұлға сот тәртібімен әрекет қабілеттілігі шектеулі деп танылуы мүмкін [2].","html":"Әрекет қабілеттілікті шектеу институты азаматтық құқықта ерекше мәнге ие. ҚР Азаматтық кодексіне сәйкес, спирттік ішімдіктерді, есірткі немесе психотроптық заттарды шамадан тыс пайдалануы салдарынан өз отбасын ауыр материалдық жағдайға ұшырататын тұлға сот тәртібімен әрекет қабілеттілігі шектеулі деп танылуы мүмкін [2].","id":"lesson-4-paragraph-16"},{"text":"Әрекет қабілеттілігі шектеулі тұлға ұсақ тұрмыстық мәмілелерді өз бетінше жасай алады, ал өзге мәмілелерді тек қамқоршысының келісімімен жүзеге асырады. Мұндай құқықтық тетік тұлғаның мүдделерімен қатар, оның отбасы мүшелерінің де құқықтары мен заңды мүдделерін қорғауға бағытталған.","html":"Әрекет қабілеттілігі шектеулі тұлға ұсақ тұрмыстық мәмілелерді өз бетінше жасай алады, ал өзге мәмілелерді тек қамқоршысының келісімімен жүзеге асырады. Мұндай құқықтық тетік тұлғаның мүдделерімен қатар, оның отбасы мүшелерінің де құқықтары мен заңды мүдделерін қорғауға бағытталған.","id":"lesson-4-paragraph-17"},{"text":"Әрекет қабілеттіліктен айыру – азаматтық құқықтағы ең қатаң шектеу шараларының бірі. ҚР Азаматтық кодексіне сәйкес, психикалық ауруы немесе ақыл-есінің кемістігі салдарынан өз әрекеттерінің мәнін түсіне алмайтын немесе оларды басқара алмайтын тұлға сот шешімімен әрекетке қабілетсіз деп танылуы мүмкін.","html":"Әрекет қабілеттіліктен айыру – азаматтық құқықтағы ең қатаң шектеу шараларының бірі. ҚР Азаматтық кодексіне сәйкес, психикалық ауруы немесе ақыл-есінің кемістігі салдарынан өз әрекеттерінің мәнін түсіне алмайтын немесе оларды басқара алмайтын тұлға сот шешімімен әрекетке қабілетсіз деп танылуы мүмкін.","id":"lesson-4-paragraph-18"},{"text":"Мұндай тұлғаның атынан барлық азаматтық-құқықтық мәмілелерді оның заңды өкілі – қорғаншысы жүзеге асырады. Әрекет қабілеттіліктен айыру тұлғаның жеке басын кемсіту емес, керісінше оның құқықтары мен мүдделерін қорғауға бағытталған құқықтық құрал болып табылады.","html":"Мұндай тұлғаның атынан барлық азаматтық-құқықтық мәмілелерді оның заңды өкілі – қорғаншысы жүзеге асырады. Әрекет қабілеттіліктен айыру тұлғаның жеке басын кемсіту емес, керісінше оның құқықтары мен мүдделерін қорғауға бағытталған құқықтық құрал болып табылады.","id":"lesson-4-paragraph-19"},{"text":"Хабар-ошарсыз кету институты азаматтық құқықтық қатынастардағы құқықтық айқындықты қамтамасыз етуге бағытталған. ҚР Азаматтық кодексіне сәйкес, егер тұлға өзінің тұрғылықты жерінде бір жыл бойы хабарсыз жоғалып кетсе және оның қайда екендігі туралы мәлімет болмаса, сот оны хабар-ошарсыз кетті деп тануы мүмкін.","html":"Хабар-ошарсыз кету институты азаматтық құқықтық қатынастардағы құқықтық айқындықты қамтамасыз етуге бағытталған. ҚР Азаматтық кодексіне сәйкес, егер тұлға өзінің тұрғылықты жерінде бір жыл бойы хабарсыз жоғалып кетсе және оның қайда екендігі туралы мәлімет болмаса, сот оны хабар-ошарсыз кетті деп тануы мүмкін.","id":"lesson-4-paragraph-20"},{"text":"Хабар-ошарсыз кеткен тұлғаның мүлкіне қамқоршылық белгіленеді. Бұл шара мүліктің сақталуын және оның заңды пайдаланылуын қамтамасыз етуге бағытталған.","html":"Хабар-ошарсыз кеткен тұлғаның мүлкіне қамқоршылық белгіленеді. Бұл шара мүліктің сақталуын және оның заңды пайдаланылуын қамтамасыз етуге бағытталған.","id":"lesson-4-paragraph-21"},{"text":"Егер тұлға белгілі бір мерзім бойы хабарсыз болып, оның тірі екендігі туралы деректер болмаса, заңда белгіленген жағдайларда сот оны өлді деп жариялауы мүмкін. ҚР Азаматтық кодексінде бұл мерзімдер нақты көрсетілген және ерекше жағдайларда қысқартылуы мүмкін.","html":"Егер тұлға белгілі бір мерзім бойы хабарсыз болып, оның тірі екендігі туралы деректер болмаса, заңда белгіленген жағдайларда сот оны өлді деп жариялауы мүмкін. ҚР Азаматтық кодексінде бұл мерзімдер нақты көрсетілген және ерекше жағдайларда қысқартылуы мүмкін.","id":"lesson-4-paragraph-22"},{"text":"Өлді деп жариялау азаматтық құқықтық қатынастарда мұрагерлік, неке қатынастарының тоқтатылуы және мүліктік құқықтардың ауысуы сияқты құқықтық салдарға әкеп соғады.","html":"Өлді деп жариялау азаматтық құқықтық қатынастарда мұрагерлік, неке қатынастарының тоқтатылуы және мүліктік құқықтардың ауысуы сияқты құқықтық салдарға әкеп соғады.","id":"lesson-4-paragraph-23"},{"text":"Өлді деп жарияланған немесе хабар-ошарсыз кетті деп танылған тұлға тірі оралған жағдайда, ҚР Азаматтық. Кодексінде арнайы құқықтық салдарлар көзделген. Мұндай жағдайда сот шешімі жойылады, ал тұлғаның құқықтық мәртебесі қалпына келтіріледі.","html":"Өлді деп жарияланған немесе хабар-ошарсыз кетті деп танылған тұлға тірі оралған жағдайда, ҚР Азаматтық. Кодексінде арнайы құқықтық салдарлар көзделген. Мұндай жағдайда сот шешімі жойылады, ал тұлғаның құқықтық мәртебесі қалпына келтіріледі.","id":"lesson-4-paragraph-24"},{"text":"Тұлға өзіне тиесілі мүлікті заңда көзделген тәртіппен қайтаруды талап етуге құқылы. Бұл норма азаматтық құқықтағы әділеттілік пен құқықтарды қалпына келтіру қағидаттарының көрінісі болып табылады.","html":"Тұлға өзіне тиесілі мүлікті заңда көзделген тәртіппен қайтаруды талап етуге құқылы. Бұл норма азаматтық құқықтағы әділеттілік пен құқықтарды қалпына келтіру қағидаттарының көрінісі болып табылады.","id":"lesson-4-paragraph-25"}],"words":1057,"legacyAnchors":{"lesson-4-section-1":"lesson-4-paragraph-1","lesson-4-section-2":"lesson-4-paragraph-3","lesson-4-section-3":"lesson-4-paragraph-11","lesson-4-section-4":"lesson-4-paragraph-16","lesson-4-section-5":"lesson-4-paragraph-20"}},"5":{"title":"5-ТАҚЫРЫП. АЗАМАТТЫҚ-ҚҰҚЫҚТЫҢ СУБЪЕКТІ РЕТІНДЕ ЗАҢДЫ ТҰЛҒАЛАР. ЖАЛПЫ ЕРЕЖЕЛЕР","blocks":[{"text":"Азаматтық құқық қоғамдық қатынастарды реттейтін құқық саласы ретінде мүліктік және мүліктік емес қатынастарға қатысатын субъектілердің құқықтық мәртебесін анықтайды. Азаматтық-құқықтық қатынастардың маңызды әрі кең таралған қатысушыларының бірі – заңды тұлғалар болып табылады. Қазіргі заманда өндірістік, сауда, қызмет көрсету, қаржы, білім беру және өзге де салалардағы азаматтық айналымның елеулі бөлігі заңды тұлғалардың қатысуымен жүзеге асырылатындықтан, олардың құқықтық табиғатын талдау теориялық та, практикалық та маңызға ие.","html":"<strong> </strong>Азаматтық құқық қоғамдық қатынастарды реттейтін құқық саласы ретінде мүліктік және мүліктік емес қатынастарға қатысатын субъектілердің құқықтық мәртебесін анықтайды. Азаматтық-құқықтық қатынастардың маңызды әрі кең таралған қатысушыларының бірі – заңды тұлғалар болып табылады. Қазіргі заманда өндірістік, сауда, қызмет көрсету, қаржы, білім беру және өзге де салалардағы азаматтық айналымның елеулі бөлігі заңды тұлғалардың қатысуымен жүзеге асырылатындықтан, олардың құқықтық табиғатын талдау теориялық та, практикалық та маңызға ие.","id":"lesson-5-paragraph-1"},{"text":"Қазақстан Республикасының азаматтық заңнамасында заңды тұлға институты жан-жақты реттеледі. ҚР Азаматтық кодексіне сәйкес, заңды тұлға – азаматтық құқықтарға ие болып, міндеттерді атқара алатын, өз атынан мүліктік және жеке мүліктік емес құқықтарды жүзеге асыратын, сотта талапкер және жауапкер бола алатын ұйым ретінде танылады. Бұл анықтама заңды тұлғаның азаматтық айналымдағы дербес орнын және оның құқықтық қатынастарға өз бетінше қатысу мүмкіндігін көрсетеді.","html":"Қазақстан Республикасының азаматтық заңнамасында заңды тұлға институты жан-жақты реттеледі. ҚР Азаматтық кодексіне сәйкес, заңды тұлға – азаматтық құқықтарға ие болып, міндеттерді атқара алатын, өз атынан мүліктік және жеке мүліктік емес құқықтарды жүзеге асыратын, сотта талапкер және жауапкер бола алатын ұйым ретінде танылады. Бұл анықтама заңды тұлғаның азаматтық айналымдағы дербес орнын және оның құқықтық қатынастарға өз бетінше қатысу мүмкіндігін көрсетеді.","id":"lesson-5-paragraph-2"},{"text":"Заңды тұлғаның азаматтық құқық субъектісі ретінде танылуы үшін белгілі бір заңдық белгілердің жиынтығы болуы қажет. Бірінші кезекте, заңды тұлға ұйымдастырушылық бірлікпен сипатталады. Бұл оның ішкі құрылымының, басқару органдарының қалыптасқандығын және қызметін белгілі тәртіппен ұйымдастыруға қабілетті екенін білдіреді. Ұйымдастырушылық бірлік заңды тұлғаның жарғысы, құрылтай шарты немесе өзге де құрылтай құжаттары арқылы бекітіліп, ұйымның мақсаттарын, басқару жүйесін және қызмет ету тәртібін айқындайды [12].","html":"Заңды тұлғаның азаматтық құқық субъектісі ретінде танылуы үшін белгілі бір заңдық белгілердің жиынтығы болуы қажет. Бірінші кезекте, заңды тұлға ұйымдастырушылық бірлікпен сипатталады. Бұл оның ішкі құрылымының, басқару органдарының қалыптасқандығын және қызметін белгілі тәртіппен ұйымдастыруға қабілетті екенін білдіреді. Ұйымдастырушылық бірлік заңды тұлғаның жарғысы, құрылтай шарты немесе өзге де құрылтай құжаттары арқылы бекітіліп, ұйымның мақсаттарын, басқару жүйесін және қызмет ету тәртібін айқындайды [12].","id":"lesson-5-paragraph-3"},{"text":"Екінші маңызды белгі – заңды тұлғаның оқшауланған мүлкінің болуы. Заңды тұлғаның мүлкі оның құрылтайшыларының немесе қатысушыларының мүлкінен бөлектенеді және ұйымның дербес балансында немесе сметасында көрсетіледі. Оқшауланған мүліктің болуы заңды тұлғаның азаматтық айналымға тәуелсіз түрде қатысуына, шаруашылық жүргізуіне және өз міндеттемелерін орындауына мүмкіндік береді.","html":"Екінші маңызды белгі – заңды тұлғаның оқшауланған мүлкінің болуы. Заңды тұлғаның мүлкі оның құрылтайшыларының немесе қатысушыларының мүлкінен бөлектенеді және ұйымның дербес балансында немесе сметасында көрсетіледі. Оқшауланған мүліктің болуы заңды тұлғаның азаматтық айналымға тәуелсіз түрде қатысуына, шаруашылық жүргізуіне және өз міндеттемелерін орындауына мүмкіндік береді.","id":"lesson-5-paragraph-4"},{"text":"Үшінші белгі – заңды тұлғаның өз міндеттемелері бойынша дербес жауапкершілігі. Азаматтық заңнама қағидаларына сәйкес, заңды тұлға өзіне тиесілі мүлік шегінде жауап береді. Бұл ереже азаматтық айналымдағы тұрақтылықты қамтамасыз етуге және заңды тұлға қатысушыларының тәуекелін нақтылауға бағытталған. Жалпы тәртіп бойынша қатысушылар (құрылтайшылар) заңды тұлғаның міндеттемелері бойынша жауап бермейді, ал заңды тұлға құрылтайшылардың міндеттемелері бойынша жауапты емес. Алайда заңнамада немесе құрылтай құжаттарында көзделген ерекше жағдайларда өзгеше ережелер қолданылауы мүмкін.","html":"Үшінші белгі – заңды тұлғаның өз міндеттемелері бойынша дербес жауапкершілігі. Азаматтық заңнама қағидаларына сәйкес, заңды тұлға өзіне тиесілі мүлік шегінде жауап береді. Бұл ереже азаматтық айналымдағы тұрақтылықты қамтамасыз етуге және заңды тұлға қатысушыларының тәуекелін нақтылауға бағытталған. Жалпы тәртіп бойынша қатысушылар (құрылтайшылар) заңды тұлғаның міндеттемелері бойынша жауап бермейді, ал заңды тұлға құрылтайшылардың міндеттемелері бойынша жауапты емес. Алайда заңнамада немесе құрылтай құжаттарында көзделген ерекше жағдайларда өзгеше ережелер қолданылауы мүмкін.","id":"lesson-5-paragraph-5"},{"text":"Төртінші белгі – заңды тұлғаның азаматтық-құқықтық қатынастарға өз атынан қатысу қабілеті. Заңды тұлға өз атымен шарттар жасайды, мәмілелерге қатысады, мүлікке ие болады, құқықтарды иеленеді, оларды жүзеге асырады және қорғайды. Осыған сәйкес заңды тұлға сотта талапкер немесе жауапкер ретінде қатыса алады. Бұл оның азаматтық-құқықтық дербестігін білдіреді және қорғайды. Осыған сәйкес заңды тұлға сотта талапкер немесе жауапкер ретінде қатыса алады. Бұл оның азаматтық-құқықтық дербестігін білдіреді және құқықтық қатынастардың мазмұнын қалыптастыруда маңызды рөл атқарады.","html":"Төртінші белгі – заңды тұлғаның азаматтық-құқықтық қатынастарға өз атынан қатысу қабілеті. Заңды тұлға өз атымен шарттар жасайды, мәмілелерге қатысады, мүлікке ие болады, құқықтарды иеленеді, оларды жүзеге асырады және қорғайды. Осыған сәйкес заңды тұлға сотта талапкер немесе жауапкер ретінде қатыса алады. Бұл оның азаматтық-құқықтық дербестігін білдіреді және қорғайды. Осыған сәйкес заңды тұлға сотта талапкер немесе жауапкер ретінде қатыса алады. Бұл оның азаматтық-құқықтық дербестігін білдіреді және құқықтық қатынастардың мазмұнын қалыптастыруда маңызды рөл атқарады.","id":"lesson-5-paragraph-6"},{"text":"Заңды тұлғаның құқық субъектілігі оның құқық қабілеттілігі мен әрекет қабілеттілігі арқылы көрініс табады. Жеке тұлғалардан ерекшелігі – заңды тұлғаның құқық қабілеттілігі мемлекеттік тіркеуден өткен кезден бастап пайда болады. Тиісінше, ол тарату рәсімі аяқталып, заңды тұлға тіркеуден шығарылған кезде тоқтатылады. Бұл – заңды тұлғаның құқықтық өмірі мемлекеттік тіркеу фактісімен тікелей байланыстылығын көрсетеді.","html":"Заңды тұлғаның құқық субъектілігі оның құқық қабілеттілігі мен әрекет қабілеттілігі арқылы көрініс табады. Жеке тұлғалардан ерекшелігі – заңды тұлғаның құқық қабілеттілігі мемлекеттік тіркеуден өткен кезден бастап пайда болады. Тиісінше, ол тарату рәсімі аяқталып, заңды тұлға тіркеуден шығарылған кезде тоқтатылады. Бұл – заңды тұлғаның құқықтық өмірі мемлекеттік тіркеу фактісімен тікелей байланыстылығын көрсетеді.","id":"lesson-5-paragraph-7"},{"text":"Заңды тұлға өзінің құқықтары мен міндеттерін арнайы құрылған органдары арқылы жүзеге асырады. Заңды тұлға – қағаз жүзінде құрылған ұйым. Оның адам сияқты өз ойы мен еркі болмайды. Сондықтан ұйымның еркі басқару органдарының шешімдері арқылы қалыптасады және сыртқа танылады. Заңды тұлғаның органдарына директор, басқарма, қатысушылардың жалпы жиналысы және заңнама мен құрылтай құжаттарында көзделген өзге де органдар жатады. Олардың өкілеттігі мен құзыреті заңмен бекітілген тәртіпте жүзеге асырылады.","html":"Заңды тұлға өзінің құқықтары мен міндеттерін арнайы құрылған органдары арқылы жүзеге асырады. Заңды тұлға – қағаз жүзінде құрылған ұйым. Оның адам сияқты өз ойы мен еркі болмайды. Сондықтан ұйымның еркі басқару органдарының шешімдері арқылы қалыптасады және сыртқа танылады. Заңды тұлғаның органдарына директор, басқарма, қатысушылардың жалпы жиналысы және заңнама мен құрылтай құжаттарында көзделген өзге де органдар жатады. Олардың өкілеттігі мен құзыреті заңмен бекітілген тәртіпте жүзеге асырылады.","id":"lesson-5-paragraph-8"},{"text":"Азаматтық заңнамада заңды тұлғалар қызметінің мақсаттарына қарай коммерциялық және коммерциялық емес ұйымдар болып бөлінеді. Коммерциялық ұйымдардың негізгі мақсаты – таза табыс табу, ал алынған табыс қатысушылар арасында бөлінуі мүмкін. Коммерциялық ұйымдардың түрлері азаматтық заңнамада және арнайы заңдарда нақтыланып көрсетіледі [13].","html":"Азаматтық заңнамада заңды тұлғалар қызметінің мақсаттарына қарай коммерциялық және коммерциялық емес ұйымдар болып бөлінеді. Коммерциялық ұйымдардың негізгі мақсаты – таза табыс табу, ал алынған табыс қатысушылар арасында бөлінуі мүмкін. Коммерциялық ұйымдардың түрлері азаматтық заңнамада және арнайы заңдарда нақтыланып көрсетіледі [13].","id":"lesson-5-paragraph-9"},{"text":"Коммерциялық емес ұйымдар, керісінше, табыс табуды негізгі мақсат ретінде көздемейді және табысты қатысушылар арасында бөлмейді. Коммерциялық емес ұйымдар қоғамдық, әлеуметтік, қайырымдылық, мәдени, ғылыми, білім беру және өзге де мақсаттарға бағытталады. Дегенмен коммерциялық емес ұйымдар заңда рұқсат етілген шектерде кіріс әкелетін қызметпен айналыса алады, бірақ бұл кірістер тек жарғылық мақсаттарға жұмсалуы тиіс.","html":"Коммерциялық емес ұйымдар, керісінше, табыс табуды негізгі мақсат ретінде көздемейді және табысты қатысушылар арасында бөлмейді. Коммерциялық емес ұйымдар қоғамдық, әлеуметтік, қайырымдылық, мәдени, ғылыми, білім беру және өзге де мақсаттарға бағытталады. Дегенмен коммерциялық емес ұйымдар заңда рұқсат етілген шектерде кіріс әкелетін қызметпен айналыса алады, бірақ бұл кірістер тек жарғылық мақсаттарға жұмсалуы тиіс.","id":"lesson-5-paragraph-10"},{"text":"Заңды тұлғаның құрылуы белгілі бір құқықтық рәсімге бағынады. Әдетте ол құрылтайшылардың шешімімен құрылады, құрылтай құжаттары қабылданады, басқару органдары анықталады және уәкілетті мемлекеттік органда тіркеуден өтеді. Мемлекеттік тіркеу заңды тұлғаның заңдық тұлға ретінде пайда болуын, оның азаматтық құқық субъектілігін ресми түрде тануды білдіреді. Сондықтан тіркеусіз ұйым азаматтық айналымда толыққанды субъект ретінде әрекет ете алмайды [14].","html":"Заңды тұлғаның құрылуы белгілі бір құқықтық рәсімге бағынады. Әдетте ол құрылтайшылардың шешімімен құрылады, құрылтай құжаттары қабылданады, басқару органдары анықталады және уәкілетті мемлекеттік органда тіркеуден өтеді. Мемлекеттік тіркеу заңды тұлғаның заңдық тұлға ретінде пайда болуын, оның азаматтық құқық субъектілігін ресми түрде тануды білдіреді. Сондықтан тіркеусіз ұйым азаматтық айналымда толыққанды субъект ретінде әрекет ете алмайды [14].","id":"lesson-5-paragraph-11"},{"text":"Азаматтық айналымда заңды тұлғалар көбіне қызметін кеңейту мақсатында өкілдіктер мен филиалдар ашады. Өкілдік – заңды тұлғаның мүддесін қорғау және өкілдік ету үшін құрылған оқшау бөлімше болса, филиал – заңды тұлғаның барлық немесе белгілі бір бөлігін жүзеге асыратын бөлімше болып табылады. Дегенмен филиал да, өкілдік те жеке заңды тұлға мәртебесіне ие емес. Олар негізгі ұйымның атынан әрекет етеді және негізгі заңды тұлға бекіткен ережелерге сәйкес қызмет атқарады.","html":"Азаматтық айналымда заңды тұлғалар көбіне қызметін кеңейту мақсатында өкілдіктер мен филиалдар ашады. Өкілдік – заңды тұлғаның мүддесін қорғау және өкілдік ету үшін құрылған оқшау бөлімше болса, филиал – заңды тұлғаның барлық немесе белгілі бір бөлігін жүзеге асыратын бөлімше болып табылады. Дегенмен филиал да, өкілдік те жеке заңды тұлға мәртебесіне ие емес. Олар негізгі ұйымның атынан әрекет етеді және негізгі заңды тұлға бекіткен ережелерге сәйкес қызмет атқарады.","id":"lesson-5-paragraph-12"},{"text":"Заңды тұлға қызметінің тоқтатылуы қайта ұйымдастыру немесе тарату арқылы жүзеге асырылады. Қайта ұйымдастыру кезінде заңды тұлғаның құқықтары мен міндеттері құқық мирасқорлығы тәртібімен басқа субъектілерге өтеді. Ал тарату – заңды тұлғаның қызметін тоқтатудың ең соңғы нысаны, мұнда ұйымның құқық субъектілігі толық жойылады. Тарату ерікті түрде немесе сот тәртібімен жүргізілуі мүмкін. Тарату барысында кредиторлардың талаптары қанағаттандырылып, қалған мүлік заңда көзделген тәртіппен бөлінеді.","html":"Заңды тұлға қызметінің тоқтатылуы қайта ұйымдастыру немесе тарату арқылы жүзеге асырылады. Қайта ұйымдастыру кезінде заңды тұлғаның құқықтары мен міндеттері құқық мирасқорлығы тәртібімен басқа субъектілерге өтеді. Ал тарату – заңды тұлғаның қызметін тоқтатудың ең соңғы нысаны, мұнда ұйымның құқық субъектілігі толық жойылады. Тарату ерікті түрде немесе сот тәртібімен жүргізілуі мүмкін. Тарату барысында кредиторлардың талаптары қанағаттандырылып, қалған мүлік заңда көзделген тәртіппен бөлінеді.","id":"lesson-5-paragraph-13"},{"text":"Заңды тұлғалар азаматтық-құқықтық қатынастардың негізгі әрі әмбебап субъектілері болып табылады. Олардың құқықтық мәртебесі азаматтық заңнамада дербес мүлікке ие болу, азаматтық айналымға өз атынан қатысу, міндеттемелері бойынша дербес жауапкершілік және мемлекеттік тіркеу қағидалары арқылы айқындалады. Заңды тұлға институты азаматтық айналымның тұрақты дамуына, құқықтық қатынастардың жүйелі реттелуіне және нарықтық экономикалық тиімді қызмет етуіне мүмкіндік береді [15].","html":"Заңды тұлғалар азаматтық-құқықтық қатынастардың негізгі әрі әмбебап субъектілері болып табылады. Олардың құқықтық мәртебесі азаматтық заңнамада дербес мүлікке ие болу, азаматтық айналымға өз атынан қатысу, міндеттемелері бойынша дербес жауапкершілік және мемлекеттік тіркеу қағидалары арқылы айқындалады. Заңды тұлға институты азаматтық айналымның тұрақты дамуына, құқықтық қатынастардың жүйелі реттелуіне және нарықтық экономикалық тиімді қызмет етуіне мүмкіндік береді [15].","id":"lesson-5-paragraph-14"}],"words":805,"legacyAnchors":{"lesson-5-section-1":"lesson-5-paragraph-1","lesson-5-section-2":"lesson-5-paragraph-3","lesson-5-section-3":"lesson-5-paragraph-7","lesson-5-section-4":"lesson-5-paragraph-9","lesson-5-section-5":"lesson-5-paragraph-11"}},"6":{"title":"6-ТАҚЫРЫП. АЗАМАТЫҚ ҚҰҚЫҚТЫҢ СУБЪЕКТІСІ РЕТІНДЕ КОММЕРЦИЯЛЫҚ ҰЙЫМДАР","blocks":[{"text":"Азаматтық құқықта қоғамдық қатынастардың басым бөлігі мүліктік айналыммен байланысты болады. Яғни адамдар мен ұйымдар арасында мүлік сатып алу, сату, жалға беру, құрылыс жүргізу, қызмет көрсету, қаржы тарту, өнім өндіру сияқты қатынастар үнемі жүріп жатады. Осындай азаматтық айналымға қатысатын тұлғалар азаматтық құқық субъектілері болып есептеледі. Қазақстан Республикасының Азаматтық кодексі (бұдан әрі – ҚР АК) азаматтық құқық субъектілеріне жеке тұлғаларды, заңды тұлғаларды және мемлекетті жатқызады. Бұл субъектілер тең құқықты негізде әрекет етеді, олардың арасындағы қатынастар әкімшілік бағыныштылыққа емес, шарт еркіндігіне және теңдік қағидатына сүйенеді.","html":"Азаматтық құқықта қоғамдық қатынастардың басым бөлігі мүліктік айналыммен байланысты болады. Яғни адамдар мен ұйымдар арасында мүлік сатып алу, сату, жалға беру, құрылыс жүргізу, қызмет көрсету, қаржы тарту, өнім өндіру сияқты қатынастар үнемі жүріп жатады. Осындай азаматтық айналымға қатысатын тұлғалар азаматтық құқық субъектілері болып есептеледі. Қазақстан Республикасының Азаматтық кодексі (бұдан әрі – ҚР АК) азаматтық құқық субъектілеріне жеке тұлғаларды, заңды тұлғаларды және мемлекетті жатқызады. Бұл субъектілер тең құқықты негізде әрекет етеді, олардың арасындағы қатынастар әкімшілік бағыныштылыққа емес, шарт еркіндігіне және теңдік қағидатына сүйенеді.","id":"lesson-6-paragraph-1"},{"text":"Заңды тұлғалардың ішінде азаматтық айналымда ең көп кездесетіндері – коммерциялық ұйымдар. Коммерциялық ұйым дегеніміз – пайда табу мақсатында құрылатын заңды тұлға. Коммерциялық ұйым өзінің қызметінен тапқан табысын қатысушылары арасында бөле алады. Бұл оның коммерциялық емес ұйымдардан негізгі айырмашылығы болып табылады. Коммерциялық ұйымдар кәсіпкерлік қызметтің басты қатысушылары болғандықтан, олардың құқықтық мәртебесін дұрыс түсіну азаматтық құқықтық қатынастарды дұрыс қолданудың маңызды шарты саналады.","html":"Заңды тұлғалардың ішінде азаматтық айналымда ең көп кездесетіндері – коммерциялық ұйымдар. Коммерциялық ұйым дегеніміз – пайда табу мақсатында құрылатын заңды тұлға. Коммерциялық ұйым өзінің қызметінен тапқан табысын қатысушылары арасында бөле алады. Бұл оның коммерциялық емес ұйымдардан негізгі айырмашылығы болып табылады. Коммерциялық ұйымдар кәсіпкерлік қызметтің басты қатысушылары болғандықтан, олардың құқықтық мәртебесін дұрыс түсіну азаматтық құқықтық қатынастарды дұрыс қолданудың маңызды шарты саналады.","id":"lesson-6-paragraph-2"},{"text":"ҚР АК 33-бабына сәйкес заңды тұлға – меншік, шаруашылық жүргізу немесе жедел басқару құқығындағы оқшау мүлкі бар және сол мүлікпен өз міндеттемелері бойынша жауап беретін, өз атынан құқықтар мен міндеттерге ие болып, оларды жүзеге асыра алатын ұйым. Заңды тұлғаның құқық қабілеттілігі мемлекеттік тіркеуден өткен кезден бастап пайда болады. Осыған байланысты тіркеусіз кез келген ұйым заңды тұлға болып саналмайды. Демек, коммерциялық ұйым болу үшін міндетті түрде мемлекеттік тіркеу қажет.","html":"ҚР АК 33-бабына сәйкес заңды тұлға – меншік, шаруашылық жүргізу немесе жедел басқару құқығындағы оқшау мүлкі бар және сол мүлікпен өз міндеттемелері бойынша жауап беретін, өз атынан құқықтар мен міндеттерге ие болып, оларды жүзеге асыра алатын ұйым. Заңды тұлғаның құқық қабілеттілігі мемлекеттік тіркеуден өткен кезден бастап пайда болады. Осыған байланысты тіркеусіз кез келген ұйым заңды тұлға болып саналмайды. Демек, коммерциялық ұйым болу үшін міндетті түрде мемлекеттік тіркеу қажет.","id":"lesson-6-paragraph-3"},{"text":"Коммерциялық ұйымдар ҚР заңнамасы бойынша бірнеше ұйымдық-құқықтық нысанда құрылады. Солардың ішінде азаматтық айналымда кең таралған негізгі түрлері: мемлекеттік кәсіпорын, шаруашылық серіктестік, акционерлік қоғам және өндірістік кооператив болып табылады.","html":"Коммерциялық ұйымдар ҚР заңнамасы бойынша бірнеше ұйымдық-құқықтық нысанда құрылады. Солардың ішінде азаматтық айналымда кең таралған негізгі түрлері: мемлекеттік кәсіпорын, шаруашылық серіктестік, акционерлік қоғам және өндірістік кооператив болып табылады.","id":"lesson-6-paragraph-4"},{"text":"Коммерциялық ұйымның жалпы сипаттамасына тоқталатын болсақ, коммерциялық ұйымдардың ортақ белгілеріне мыналарды жатқызуға болады: біріншіден, олардың басты мақсаты – пайда табу; екіншіден, олар өз атынан мәмілелер жасап, азаматтық құқықтық қатынастарға қатыса алады; үшіншіден, олардың жеке мүлкі болады және сол мүлікпен міндеттемелері бойынша жауап береді; төртіншіден, коммерциялық ұйымдар құқықтық теңдік негізінде әрекет етеді, яғни мемлекетпен немесе басқа ұйымдармен шарт жасасқанда тең тарап болып есептеледі.","html":"Коммерциялық ұйымның жалпы сипаттамасына тоқталатын болсақ, коммерциялық ұйымдардың ортақ белгілеріне мыналарды жатқызуға болады: біріншіден, олардың басты мақсаты – пайда табу; екіншіден, олар өз атынан мәмілелер жасап, азаматтық құқықтық қатынастарға қатыса алады; үшіншіден, олардың жеке мүлкі болады және сол мүлікпен міндеттемелері бойынша жауап береді; төртіншіден, коммерциялық ұйымдар құқықтық теңдік негізінде әрекет етеді, яғни мемлекетпен немесе басқа ұйымдармен шарт жасасқанда тең тарап болып есептеледі.","id":"lesson-6-paragraph-5"},{"text":"Мысалы, белгілі бір дүкенің атынан «ЖШС “Береке”» тауар сатады делік. Бұл жағдайда сатып алушымен қатынас жеке кәсіпкермен немесе нақты адаммен емес, заңды тұлға – ЖШС-пен пайда болады. Егер сатып алынған тауар сапасыз болып шықса, тұтынушы арызды жеке сатушыға емес, заңды тұлға ретінде сол ЖШС-ке қоя алады.","html":"Мысалы, белгілі бір дүкенің атынан «ЖШС “Береке”» тауар сатады делік. Бұл жағдайда сатып алушымен қатынас жеке кәсіпкермен немесе нақты адаммен емес, заңды тұлға – ЖШС-пен пайда болады. Егер сатып алынған тауар сапасыз болып шықса, тұтынушы арызды жеке сатушыға емес, заңды тұлға ретінде сол ЖШС-ке қоя алады.","id":"lesson-6-paragraph-6"},{"text":"Коммерциялық ұйымдардың әр түрі өз ерекшеліктеріне ие. Бұл ерекшеліктер олардың меншік нысанына, мүлікке иелік ету тәртібіне, қатысушылардың жауапкершілігіне және басқару құрылымына байланысты.","html":"Коммерциялық ұйымдардың әр түрі өз ерекшеліктеріне ие. Бұл ерекшеліктер олардың меншік нысанына, мүлікке иелік ету тәртібіне, қатысушылардың жауапкершілігіне және басқару құрылымына байланысты.","id":"lesson-6-paragraph-7"},{"text":"Мемлекеттік кәсіпорын – коммерциялық ұйымдардың ерекше түрі. Бұл ұйым мемлекетке тиесілі мүлік негізінде құрылады және оның мүлкі мемлекеттің меншігі болып қалады. Мемлекеттік кәсіпорын өз қызметін кәсіпкерлік негізде жүзеге асырып, табыс табуды көздейді, бірақ оның мүлкіне меншік құқығы мемлекетке тиесілі болады.","html":"Мемлекеттік кәсіпорын – коммерциялық ұйымдардың ерекше түрі. Бұл ұйым мемлекетке тиесілі мүлік негізінде құрылады және оның мүлкі мемлекеттің меншігі болып қалады. Мемлекеттік кәсіпорын өз қызметін кәсіпкерлік негізде жүзеге асырып, табыс табуды көздейді, бірақ оның мүлкіне меншік құқығы мемлекетке тиесілі болады.","id":"lesson-6-paragraph-8"},{"text":"Мемлекеттік кәсіпорын екі негізгі құқықтық режимде құрылады: шаруашылық жүргізу құқығындағы мемлекеттік кәсіпорын және жедел басқару құқығындағы мемлекеттік кәсіпорын. Мұндай кәсіпорындардың азаматтық құқықтағы мәртебесі ҚР АК нормаларымен реттеледі.","html":"Мемлекеттік кәсіпорын екі негізгі құқықтық режимде құрылады: шаруашылық жүргізу құқығындағы мемлекеттік кәсіпорын және жедел басқару құқығындағы мемлекеттік кәсіпорын. Мұндай кәсіпорындардың азаматтық құқықтағы мәртебесі ҚР АК нормаларымен реттеледі.","id":"lesson-6-paragraph-9"},{"text":"Мысал ретінде: егер қала ішінде жолаушылар тасымалымен айналысатын «Қалалық автобус паркі» мемлекеттік кәсіпорын ретінде құрылған болса, ол кәсіпкерлік қызмет жүргізіп, кіріс табады. Бірақ автобустар, гараж, ғимараттар мемлекет меншігінде болады. Кәсіпорын сол мүлікті тек өз қызметін жүзеге асыру үшін пайдаланады және белгілі шектеулерде билік етеді. Егер кәсіпорынның қарызы пайда болса, ол өзіне бекітілген мүлік аясында жауап береді.","html":"Мысал ретінде: егер қала ішінде жолаушылар тасымалымен айналысатын «Қалалық автобус паркі» мемлекеттік кәсіпорын ретінде құрылған болса, ол кәсіпкерлік қызмет жүргізіп, кіріс табады. Бірақ автобустар, гараж, ғимараттар мемлекет меншігінде болады. Кәсіпорын сол мүлікті тек өз қызметін жүзеге асыру үшін пайдаланады және белгілі шектеулерде билік етеді. Егер кәсіпорынның қарызы пайда болса, ол өзіне бекітілген мүлік аясында жауап береді.","id":"lesson-6-paragraph-10"},{"text":"Шаруашылық серіктестік – Қазақстанда ең көп таралған коммерциялық ұйымның нысаны. Азаматтық айналымда көптеген кәсіпкерлер дәл осы серіктестік нысанын таңдайды. Себебі ол бір немесе бірнеше адамның қатысуымен құрылып, кәсіпкерлік қызметті тиімді жүргізуге мүмкіндік береді.","html":"<strong> </strong>Шаруашылық серіктестік – Қазақстанда ең көп таралған коммерциялық ұйымның нысаны. Азаматтық айналымда көптеген кәсіпкерлер дәл осы серіктестік нысанын таңдайды. Себебі ол бір немесе бірнеше адамның қатысуымен құрылып, кәсіпкерлік қызметті тиімді жүргізуге мүмкіндік береді.","id":"lesson-6-paragraph-11"},{"text":"Шаруашылық серіктестіктердің ішінде ең кең таралған түрі – жауапкершілігі шектеулі серіктестік (ЖШС). ЖШС-тің ерекшелігі – қатысушылар серіктестіктің міндеттемелері бойынша өздерінің енгізген үлесі көлемінде тәуекел етеді және серіктестіктің қарызы үшін жеке мүлкімен жауап бермейді [16].","html":"Шаруашылық серіктестіктердің ішінде ең кең таралған түрі – жауапкершілігі шектеулі серіктестік (ЖШС). ЖШС-тің ерекшелігі – қатысушылар серіктестіктің міндеттемелері бойынша өздерінің енгізген үлесі көлемінде тәуекел етеді және серіктестіктің қарызы үшін жеке мүлкімен жауап бермейді [16].","id":"lesson-6-paragraph-12"},{"text":"Мысалы, үш азамат бірігіп жиһаз цехын ашты делік. Олар «ЖШС “Алтын жиһаз”» құрып, әрқайсысы 2 млн теңгеден жарғылық капитал енгізді. Кейін серіктестік банкпен несие шартын жасасып, 10 млн теңге несие алды. Егер бизнес жүрмей қалып, несие төленбей қалса, банк талапты серіктестікке қояды. Қатысушылардың жеке пәтері немесе көлігі автоматты түрде өндірілмейді. Яғни серіктестік өз міндеттемесі бойынша өзі жауап береді.","html":"Мысалы, үш азамат бірігіп жиһаз цехын ашты делік. Олар «ЖШС “Алтын жиһаз”» құрып, әрқайсысы 2 млн теңгеден жарғылық капитал енгізді. Кейін серіктестік банкпен несие шартын жасасып, 10 млн теңге несие алды. Егер бизнес жүрмей қалып, несие төленбей қалса, банк талапты серіктестікке қояды. Қатысушылардың жеке пәтері немесе көлігі автоматты түрде өндірілмейді. Яғни серіктестік өз міндеттемесі бойынша өзі жауап береді.","id":"lesson-6-paragraph-13"},{"text":"Шаруашылық серіктестіктері туралы Қазақстан Республикасының 1995 жылғы 2 мамырдағы N 2255 Заңына сәйкес шаруашылық серіктестіктердің басқа түрлері де бар: толық серіктестік, сенім серіктестігі және қосымша жауапкершілігі бар серіктестік. Бірақ тәжірибеде ең жиі қолданылатыны – ЖШС.","html":"Шаруашылық серіктестіктері туралы Қазақстан Республикасының 1995 жылғы 2 мамырдағы N 2255 Заңына сәйкес шаруашылық серіктестіктердің басқа түрлері де бар: толық серіктестік, сенім серіктестігі және қосымша жауапкершілігі бар серіктестік. Бірақ тәжірибеде ең жиі қолданылатыны – ЖШС.","id":"lesson-6-paragraph-14"},{"text":"Акционерлік қоғам (AҚ) – коммерциялық ұйымдардың ішіндегі ірі бизнесті жүргізуге арналған ұйымдық-құқықтық нысан. Мұнда капитал қатысушылардың үлесі арқылы емес, акция шығару арқылы қалыптасады. Яғни ұйымның қатысушылары акционерлер деп аталады және олардың құқықтары акция санына байланысты болады [17].","html":"<strong> </strong>Акционерлік қоғам (AҚ) – коммерциялық ұйымдардың ішіндегі ірі бизнесті жүргізуге арналған ұйымдық-құқықтық нысан. Мұнда капитал қатысушылардың үлесі арқылы емес, акция шығару арқылы қалыптасады. Яғни ұйымның қатысушылары акционерлер деп аталады және олардың құқықтары акция санына байланысты болады [17].","id":"lesson-6-paragraph-15"},{"text":"Акционерлік қоғамда басқару органдары құрылымы күрделірек келеді. Әдетте акционерлердің жалпы жиналысы, директорлар кеңесі, атқарушы орган болады. Акционерлік қоғам капитал жинауда тиімді, себебі көптеген инвесторлар акция сатып алып, қоғамның дамуына қаражат сала алады. Мысалы, еліміздегі белгілі өндірістік компания АҚ ретінде тіркелген делік. Ол жаңа зауыт салу үшін қосымша қаржы қажет етеді. Сол кезде қоғам акцияларын шығарып, инвесторларға сатады. Инвестор акция сатып алып, қоғамның акционері болады. Егер қоғам пайда тапса, акционер дивиденд алуы мүмкін. Бірақ қоғам шығынға ұшыраса, акционер қоғамның қарызы үшін жеке мүлкімен жауап бермейді, тек өз акциясының құнымен тәуекел етеді.","html":"Акционерлік қоғамда басқару органдары құрылымы күрделірек келеді. Әдетте акционерлердің жалпы жиналысы, директорлар кеңесі, атқарушы орган болады. Акционерлік қоғам капитал жинауда тиімді, себебі көптеген инвесторлар акция сатып алып, қоғамның дамуына қаражат сала алады. Мысалы, еліміздегі белгілі өндірістік компания АҚ ретінде тіркелген делік. Ол жаңа зауыт салу үшін қосымша қаржы қажет етеді. Сол кезде қоғам акцияларын шығарып, инвесторларға сатады. Инвестор акция сатып алып, қоғамның акционері болады. Егер қоғам пайда тапса, акционер дивиденд алуы мүмкін. Бірақ қоғам шығынға ұшыраса, акционер қоғамның қарызы үшін жеке мүлкімен жауап бермейді, тек өз акциясының құнымен тәуекел етеді.","id":"lesson-6-paragraph-16"},{"text":"Акционерлік қоғамдар туралы Қазақстан Республикасының 2003 жылғы 13 мамырдағы N 415 Заңына сәйкес, акционерлік қоғам азаматтық айналымда келісімшарттар жасасуға, өз атынан мүлік алуға, кредиторлармен және мердігерлермен жұмыс жасауға құқылы заңды тұлға болып табылады.","html":"Акционерлік қоғамдар туралы Қазақстан Республикасының 2003 жылғы 13 мамырдағы N 415 Заңына сәйкес, акционерлік қоғам азаматтық айналымда келісімшарттар жасасуға, өз атынан мүлік алуға, кредиторлармен және мердігерлермен жұмыс жасауға құқылы заңды тұлға болып табылады.","id":"lesson-6-paragraph-17"},{"text":"Өндірістік кооператив – азаматтардың бірлескен еңбек қызметіне және мүшелердің мүліктік жарналарына негізделген коммерциялық ұйым. Өндірістік кооперативтің басты ерекшелігі – оның мүшелері кооператив жұмысына жеке еңбегімен қатысуы тиіс. Бұл кооперативті серіктестіктен ажыратады. Себебі серіктестікте қатысушы міндетті түрде еңбек етпеуі мүмкін, тек үлес енгізіп қатыса алады [18].","html":"Өндірістік кооператив<strong> </strong>– азаматтардың бірлескен еңбек қызметіне және мүшелердің мүліктік жарналарына негізделген коммерциялық ұйым. Өндірістік кооперативтің басты ерекшелігі – оның мүшелері кооператив жұмысына жеке еңбегімен қатысуы тиіс. Бұл кооперативті серіктестіктен ажыратады. Себебі серіктестікте қатысушы міндетті түрде еңбек етпеуі мүмкін, тек үлес енгізіп қатыса алады [18].","id":"lesson-6-paragraph-18"},{"text":"Өндірістік кооператив көбіне ауыл шаруашылығында, шағын өндірісте немесе қызмет көрсету саласында кездеседі. Мысалы, ауылда бірнеше адам бірігіп сүт өнімдерін өндіретін цех ашты делік. Олар әрқайсысы құрал-жабдық әкеліп, еңбек етеді және бірлесіп өндіріс жүргізеді. Ұйым өндірістік кооператив болып тіркеледі. Түскен пайда мүшелердің еңбек үлесіне және кооператив жарнасына қарай бөлінуі мүмкін. Егер кооператив қарызға батса, заңда белгіленген тәртіпке сәйкес мүшелері қосымша жауапкершілік көтеруі ықтимал. Бұл да кооперативтің маңызды белгісі.","html":"Өндірістік кооператив көбіне ауыл шаруашылығында, шағын өндірісте немесе қызмет көрсету саласында кездеседі. Мысалы, ауылда бірнеше адам бірігіп сүт өнімдерін өндіретін цех ашты делік. Олар әрқайсысы құрал-жабдық әкеліп, еңбек етеді және бірлесіп өндіріс жүргізеді. Ұйым өндірістік кооператив болып тіркеледі. Түскен пайда мүшелердің еңбек үлесіне және кооператив жарнасына қарай бөлінуі мүмкін. Егер кооператив қарызға батса, заңда белгіленген тәртіпке сәйкес мүшелері қосымша жауапкершілік көтеруі ықтимал. Бұл да кооперативтің маңызды белгісі.","id":"lesson-6-paragraph-19"},{"text":"Жоғарыда аталған әр ұйымның құқықтық мәртебесі мен құрылымы әртүрлі болғанымен, барлығы да азаматтық құқық нормалары арқылы реттеледі және қатысушылардың теңдігі, шарт еркіндігі қағидаларына сүйене отырып әрекет етеді. Коммерциялық ұйымдардың осы ерекшеліктерін дұрыс түсіну тәжірибеде дұрыс шарт жасасуға, жауапкершілікті дұрыс анықтауға және құқықтық дауларды дұрыс шешуге мүмкіндік береді.","html":"Жоғарыда аталған әр ұйымның құқықтық мәртебесі мен құрылымы әртүрлі болғанымен, барлығы да азаматтық құқық нормалары арқылы реттеледі және қатысушылардың теңдігі, шарт еркіндігі қағидаларына сүйене отырып әрекет етеді. Коммерциялық ұйымдардың осы ерекшеліктерін дұрыс түсіну тәжірибеде дұрыс шарт жасасуға, жауапкершілікті дұрыс анықтауға және құқықтық дауларды дұрыс шешуге мүмкіндік береді.","id":"lesson-6-paragraph-20"}],"words":970,"legacyAnchors":{"lesson-6-section-1":"lesson-6-paragraph-1","lesson-6-section-2":"lesson-6-paragraph-8","lesson-6-section-3":"lesson-6-paragraph-11","lesson-6-section-4":"lesson-6-paragraph-15","lesson-6-section-5":"lesson-6-paragraph-18"}},"7":{"title":"7-ТАҚЫРЫП. АЗАМАТТЫҚ ҚҰҚЫҚТЫҢ СУБЪЕКТІ РЕТІНДЕ  КОММЕРЦИЯЛЫҚ ЕМЕС ҰЙЫМДАР","blocks":[{"text":"Азаматтық құқықта “субъект” дегеніміз – азаматтық құқықтар мен міндеттерге ие бола алатын, оларды жүзеге асырып, өз әрекеттері үшін жауап беретін тұлға. Мұндай субъектілер қатарына жеке тұлғалармен қатар заңды тұлғалар да жатады. Коммерциялық емес ұйымдар (КЕҰ) – заңды тұлғаның бір түрі.","html":"Азаматтық құқықта “субъект” дегеніміз – азаматтық құқықтар мен міндеттерге ие бола алатын, оларды жүзеге асырып, өз әрекеттері үшін жауап беретін тұлға. Мұндай субъектілер қатарына жеке тұлғалармен қатар заңды тұлғалар да жатады. Коммерциялық емес ұйымдар (КЕҰ) – заңды тұлғаның бір түрі.","id":"lesson-7-paragraph-1"},{"text":"Коммерциялық емес ұйымдардың басты ерекшелігі – олардың негізгі мақсаты пайда табу емес. Олар көбіне әлеуметтік, мәдени, ғылыми, білім беру, қайырымдылық, діни, спорттық және басқа да қоғамдық пайдалы мақсаттарды жүзеге асыру үшін құрылады. Бірақ бұл ұйымдар мүлде табыс таба алмайды деген сөз емес: олар белгілі бір қызметтен кіріс алуы мүмкін. Алайда алынған кіріс қатысушыларға үлестірілмейді, қайта ұйым мақсаттарына жұмсалады. Мысалы, қайырымдылық қоры демеушілерден ақша алып, сол қаржыға балалар үйіне көмек көрсетеді. Егер қор қандай да бір қызмет арқылы кіріс тапса, ол ақшаны құрылтайшылар өзара бөлісе алмайды. Бұл ақша қордың мақсатты қызметіне жұмсалуы тиіс.","html":"Коммерциялық емес ұйымдардың басты ерекшелігі – олардың негізгі мақсаты пайда табу емес. Олар көбіне әлеуметтік, мәдени, ғылыми, білім беру, қайырымдылық, діни, спорттық және басқа да қоғамдық пайдалы мақсаттарды жүзеге асыру үшін құрылады. Бірақ бұл ұйымдар мүлде табыс таба алмайды деген сөз емес: олар белгілі бір қызметтен кіріс алуы мүмкін. Алайда алынған кіріс қатысушыларға үлестірілмейді, қайта ұйым мақсаттарына жұмсалады. Мысалы, қайырымдылық қоры демеушілерден ақша алып, сол қаржыға балалар үйіне көмек көрсетеді. Егер қор қандай да бір қызмет арқылы кіріс тапса, ол ақшаны құрылтайшылар өзара бөлісе алмайды. Бұл ақша қордың мақсатты қызметіне жұмсалуы тиіс.","id":"lesson-7-paragraph-2"},{"text":"Коммерциялық ұйым мен коммерциялық емес ұйым арасындағы негізгі айырмашылықты былай түсінуге болады: коммерциялық ұйым – кәсіпкерлік жасап, пайда табуды көздейді (мысалы, ЖШС, АҚ). Ал коммерциялық емес ұйым – қоғамдық пайдалы мақсаттарды көздейді, ал табыс көмекші сипатта ғана болады.","html":"Коммерциялық ұйым мен коммерциялық емес ұйым арасындағы негізгі айырмашылықты былай түсінуге болады: коммерциялық ұйым – кәсіпкерлік жасап, пайда табуды көздейді (мысалы, ЖШС, АҚ). Ал коммерциялық емес ұйым – қоғамдық пайдалы мақсаттарды көздейді, ал табыс көмекші сипатта ғана болады.","id":"lesson-7-paragraph-3"},{"text":"Осылайша, коммерциялық емес ұйымдар азаматтық құқықтың дербес субъектісі ретінде өз атынан мүлікке ие бола алады, шарттар жасайды, сотта талапкер де, жауапкер де бола алады.","html":"Осылайша, коммерциялық емес ұйымдар азаматтық құқықтың дербес субъектісі ретінде өз атынан мүлікке ие бола алады, шарттар жасайды, сотта талапкер де, жауапкер де бола алады.","id":"lesson-7-paragraph-4"},{"text":"Коммерциялық емес ұйым азаматтық құқық субъектісі ретінде құқық қабілеттілігіне және әрекет қабілеттілігіне ие болады. Құқық қабілеттілік – ұйымның құқықтар мен міндеттерге ие бола алу мүмкіндігі. Ал әрекет қабілеттілік – сол құқықтарды өз әрекетімен жүзеге асыру қабілеті.","html":"Коммерциялық емес ұйым азаматтық құқық субъектісі ретінде құқық қабілеттілігіне және әрекет қабілеттілігіне ие болады. Құқық қабілеттілік – ұйымның құқықтар мен міндеттерге ие бола алу мүмкіндігі. Ал әрекет қабілеттілік – сол құқықтарды өз әрекетімен жүзеге асыру қабілеті.","id":"lesson-7-paragraph-5"},{"text":"Заңды тұлға ретінде коммерциялық емес ұйым мемлекеттік тіркеуден өткен сәттен бастап субъектілікке ие болады. Яғни тіркелмей тұрған ұйым толыққанды заңды тұлға болып есептелмейді, оның мәмілелері де тәуекелді болуы мүмкін [12].","html":"Заңды тұлға ретінде коммерциялық емес ұйым мемлекеттік тіркеуден өткен сәттен бастап субъектілікке ие болады. Яғни тіркелмей тұрған ұйым толыққанды заңды тұлға болып есептелмейді, оның мәмілелері де тәуекелді болуы мүмкін [12].","id":"lesson-7-paragraph-6"},{"text":"Мысалы, екі адам “спорт клубын” құрып, құжатсыз жаттығу залын жалға алуға шарт жасасты делік. Егер ұйым тіркелмеген болса, шартты заң жүзінде ұйым емес, сол азаматтардың өздері жасаған болып танылады. Бұл жағдайда жауапкершілік те жеке тұлғалардың мойнында болады.","html":"Мысалы, екі адам “спорт клубын” құрып, құжатсыз жаттығу залын жалға алуға шарт жасасты делік. Егер ұйым тіркелмеген болса, шартты заң жүзінде ұйым емес, сол азаматтардың өздері жасаған болып танылады. Бұл жағдайда жауапкершілік те жеке тұлғалардың мойнында болады.","id":"lesson-7-paragraph-7"},{"text":"Коммерциялық емес ұйымның құқық субъектілігі көбіне арнайы сипатта болады. Бұл дегеніміз – ұйым тек өз жарғысында көрсетілген мақсаттарға сәйкес әрекет етуі керек. Егер ұйым өз мақсатынан тыс қызмет жасаса, бұл заңға қайшы болып танылуы мүмкін. Мысалы, “Экологиялық қор” жарғысында табиғатты қорғау жобаларын қаржыландыру міндеті көрсетілген. Егер осы қор саудамен айналысып, дүкен ашса, бұл – жарғылық мақсатқа сай келмейтін қызмет. Мұндай жағдайда уәкілетті орган мәселе көтеріп, ұйымға шара қолдануы ықтимал.","html":"Коммерциялық емес ұйымның құқық субъектілігі көбіне арнайы сипатта болады. Бұл дегеніміз – ұйым тек өз жарғысында көрсетілген мақсаттарға сәйкес әрекет етуі керек. Егер ұйым өз мақсатынан тыс қызмет жасаса, бұл заңға қайшы болып танылуы мүмкін. Мысалы, “Экологиялық қор” жарғысында табиғатты қорғау жобаларын қаржыландыру міндеті көрсетілген. Егер осы қор саудамен айналысып, дүкен ашса, бұл – жарғылық мақсатқа сай келмейтін қызмет. Мұндай жағдайда уәкілетті орган мәселе көтеріп, ұйымға шара қолдануы ықтимал.","id":"lesson-7-paragraph-8"},{"text":"Коммерциялық емес ұйымдардың бірнеше түрлері бар. Қазақстанда коммерциялық емес ұйымдар бірнеше нысанда құрылады. Азаматтық құқық нормалары мен арнайы заңдарда КЕҰ-дың негізгі түрлері көрсетілген. Солардың ішіндегі кең тарағандары:","html":"Коммерциялық емес ұйымдардың бірнеше түрлері бар. Қазақстанда коммерциялық емес ұйымдар бірнеше нысанда құрылады. Азаматтық құқық нормалары мен арнайы заңдарда КЕҰ-дың негізгі түрлері көрсетілген. Солардың ішіндегі кең тарағандары:","id":"lesson-7-paragraph-9"},{"text":"Қоғамдық бірлестіктер – азаматтардың ортақ мүдделерін қорғау үшін","html":"Қоғамдық бірлестіктер – азаматтардың ортақ мүдделерін қорғау үшін","list":{"id":"1","ordered":true,"marker":"%1.","start":1},"id":"lesson-7-paragraph-10"},{"text":"құрылады (мысалы, жастар ұйымы, спорт федерациясы, кәсіптік одақ).","html":"құрылады (мысалы, жастар ұйымы, спорт федерациясы, кәсіптік одақ).","id":"lesson-7-paragraph-11"},{"text":"Қорлар – қайырымдылық, әлеуметтік қолдау, мәдениет пен білімді","html":"Қорлар – қайырымдылық, әлеуметтік қолдау, мәдениет пен білімді","list":{"id":"1","ordered":true,"marker":"%1.","start":1},"id":"lesson-7-paragraph-12"},{"text":"дамыту мақсатында құрылады.","html":"дамыту мақсатында құрылады.","id":"lesson-7-paragraph-13"},{"text":"Тұтыну кооперативтері – қатысушыларының белгілі бір қажеттілігін","html":"Тұтыну кооперативтері – қатысушыларының белгілі бір қажеттілігін","list":{"id":"1","ordered":true,"marker":"%1.","start":1},"id":"lesson-7-paragraph-14"},{"text":"қамтамасыз етуге бағытталады (мысалы, тұрғын үй кооперативі).","html":"қамтамасыз етуге бағытталады (мысалы, тұрғын үй кооперативі).","id":"lesson-7-paragraph-15"},{"text":"4.Діни бірлестіктер – діни сенімді жүзеге асыруға арналған ұйымдар.","html":"4.Діни бірлестіктер – діни сенімді жүзеге асыруға арналған ұйымдар.","id":"lesson-7-paragraph-16"},{"text":"5.Мекемелер – мемлекеттік немесе жеке меншік мекеме болуы мүмкін","html":"5.Мекемелер – мемлекеттік немесе жеке меншік мекеме болуы мүмкін","id":"lesson-7-paragraph-17"},{"text":"(мысалы, музей, университет).","html":"(мысалы, музей, университет).","id":"lesson-7-paragraph-18"},{"text":"6.Заңды тұлғалар бірлестігі (қауымдастық, одақ) – бірнеше ұйым","html":"6.Заңды тұлғалар бірлестігі (қауымдастық, одақ) – бірнеше ұйым","id":"lesson-7-paragraph-19"},{"text":"бірлесіп, ортақ мүдде үшін құрылады (мысалы, салалық ассоциация).","html":"бірлесіп, ортақ мүдде үшін құрылады (мысалы, салалық ассоциация).","id":"lesson-7-paragraph-20"},{"text":"Әр ұйымның нысаны оның мақсаттарына, басқару тәртібіне, мүлік режиміне әсер етеді. Сондықтан ұйым құрғанда құқықтық нысанды дұрыс таңдау өте маңызды.","html":"Әр ұйымның нысаны оның мақсаттарына, басқару тәртібіне, мүлік режиміне әсер етеді. Сондықтан ұйым құрғанда құқықтық нысанды дұрыс таңдау өте маңызды.","id":"lesson-7-paragraph-21"},{"text":"Коммерциялық емес ұйым азаматтық құқық субъектісі ретінде өзіндік оқшау мүлкіне ие болуы керек. Бұл мүлік ұйымның балансында есепке алынады. Оған құрылтайшылардың жарналары, қайырымдылық қаражаттар, демеушілік қаржы, гранттар және рұқсат етілген қызметтен түсетін кіріс кіруі мүмкін. Коммерциялық емес ұйым өз міндеттемелері бойынша өз мүлкімен жауап береді. Ал құрылтайшылар ұйымның қарызы үшін жалпы жағдайда жауап бермейді [13].","html":"Коммерциялық емес ұйым азаматтық құқық субъектісі ретінде өзіндік оқшау мүлкіне ие болуы керек. Бұл мүлік ұйымның балансында есепке алынады. Оған құрылтайшылардың жарналары, қайырымдылық қаражаттар, демеушілік қаржы, гранттар және рұқсат етілген қызметтен түсетін кіріс кіруі мүмкін. Коммерциялық емес ұйым өз міндеттемелері бойынша өз мүлкімен жауап береді. Ал құрылтайшылар ұйымның қарызы үшін жалпы жағдайда жауап бермейді [13].","id":"lesson-7-paragraph-22"},{"text":"Мысалы, қоғамдық қор кеңсе жалдап, жалдау ақысын уақытында төлемеді делік. Бұл жағдайда жалға беруші сотқа арыз беріп, қордың есепшотындағы ақшаға немесе өзге мүлкіне өндіріп алу қоя алады. Бірақ қор құрылтайшыларының жеке мүлкі ұйымның қарызы үшін алынбайды (егер жеке кепілдік берілмесе).","html":"Мысалы, қоғамдық қор кеңсе жалдап, жалдау ақысын уақытында төлемеді делік. Бұл жағдайда жалға беруші сотқа арыз беріп, қордың есепшотындағы ақшаға немесе өзге мүлкіне өндіріп алу қоя алады. Бірақ қор құрылтайшыларының жеке мүлкі ұйымның қарызы үшін алынбайды (егер жеке кепілдік берілмесе).","id":"lesson-7-paragraph-23"},{"text":"Коммерциялық емес ұйымдар азаматтық айналымға қатыса алады: шарт жасайды (жалдау, сатып алу, қызмет көрсету), қызметкерлерді жұмысқа алады, банкте есепшот ашады, мүлік сатып алады немесе сыйға қабылдайды, сотқа талап қоюға құқылы.","html":"Коммерциялық емес ұйымдар азаматтық айналымға қатыса алады: шарт жасайды (жалдау, сатып алу, қызмет көрсету), қызметкерлерді жұмысқа алады, банкте есепшот ашады, мүлік сатып алады немесе сыйға қабылдайды, сотқа талап қоюға құқылы.","id":"lesson-7-paragraph-24"},{"text":"Бірақ олардың мәмілелері жарғылық мақсаттарға қайшы келмеуі керек. Егер мәміле ұйым мақсатына сай болмаса, ол тәуекел тудырады немесе жарамсыз деп танылуы мүмкін. Мысалы, “Жастарды қолдау қоғамдық бірлестігі” жастарға арналған тренингтер өткізеді. Ол осы тренингтер үшін демеушіден қаржы алып, аудитория жалға алса - қалыпты. Бірақ ұйым жастар ісімен қатысы жоқ қызметке қаржы салса - бұл жарғы мақсатына қайшы әрекет.","html":"Бірақ олардың мәмілелері жарғылық мақсаттарға қайшы келмеуі керек. Егер мәміле ұйым мақсатына сай болмаса, ол тәуекел тудырады немесе жарамсыз деп танылуы мүмкін. Мысалы, “Жастарды қолдау қоғамдық бірлестігі” жастарға арналған тренингтер өткізеді. Ол осы тренингтер үшін демеушіден қаржы алып, аудитория жалға алса - қалыпты. Бірақ ұйым жастар ісімен қатысы жоқ қызметке қаржы салса - бұл жарғы мақсатына қайшы әрекет.","id":"lesson-7-paragraph-25"},{"text":"Коммерциялық емес ұйым қайта ұйымдастырылуы немесе таратылуы мүмкін. Тарату ерікті түрде құрылтайшылар шешімімен немесе мәжбүрлі түрде сот шешімімен жүзеге асады. Коммерциялық емес ұйым таратылғаннан кейін оның мүлкі құрылтайшылар арасында үлестірілмейді. Ол ұйым мақсатына ұқсас бағыттарға беріледі немесе заңда көрсетілген тәртіппен жұмсалады.","html":"Коммерциялық емес ұйым қайта ұйымдастырылуы немесе таратылуы мүмкін. Тарату ерікті түрде құрылтайшылар шешімімен немесе мәжбүрлі түрде сот шешімімен жүзеге асады. Коммерциялық емес ұйым таратылғаннан кейін оның мүлкі құрылтайшылар арасында үлестірілмейді. Ол ұйым мақсатына ұқсас бағыттарға беріледі немесе заңда көрсетілген тәртіппен жұмсалады.","id":"lesson-7-paragraph-26"},{"text":"Коммерциялық емес ұйымдар азаматтық құқықтың маңызды субъектілерінің бірі. Олар пайда табуды мақсат етпей, заңды тұлға ретінде азаматтық айналымға қатысады. Сонымен бірге олардың қызметі әрдайым жарғыда көрсетілген мақсаттар шеңберінде жүзеге асырылуы тиіс.","html":"Коммерциялық емес ұйымдар азаматтық құқықтың маңызды субъектілерінің бірі. Олар пайда табуды мақсат етпей, заңды тұлға ретінде азаматтық айналымға қатысады. Сонымен бірге олардың қызметі әрдайым жарғыда көрсетілген мақсаттар шеңберінде жүзеге асырылуы тиіс.","id":"lesson-7-paragraph-27"}],"words":746,"legacyAnchors":{"lesson-7-section-1":"lesson-7-paragraph-1","lesson-7-section-2":"lesson-7-paragraph-5","lesson-7-section-3":"lesson-7-paragraph-9","lesson-7-section-4":"lesson-7-paragraph-22","lesson-7-section-5":"lesson-7-paragraph-26"}},"8":{"title":"8-ТАҚЫРЫП. АЗАМАТТЫҚ ҚҰҚЫҚ ОБЪЕКТІЛЕРІ ТУРАЛЫ ЖАЛПЫ ЕРЕЖЕЛЕР","blocks":[{"text":"Азаматтық құқық қоғамдағы мүліктік қатынастарды, сондай-ақ мүлікке байланысты жеке мүліктік емес қатынастарды реттейтін құқық саласы болып табылады. Азаматтық құқық қатынастары белгілі бір субъектілер арасында туындайды және ол қатынастар әрқашан нақты бір игілікке, затқа немесе құқыққа бағытталады. Осы бағытталған игілік азаматтық құқықта «объект» деп аталады.","html":"Азаматтық құқық қоғамдағы мүліктік қатынастарды, сондай-ақ мүлікке байланысты жеке мүліктік емес қатынастарды реттейтін құқық саласы болып табылады. Азаматтық құқық қатынастары белгілі бір субъектілер арасында туындайды және ол қатынастар әрқашан нақты бір игілікке, затқа немесе құқыққа бағытталады. Осы бағытталған игілік азаматтық құқықта «объект» деп аталады.","id":"lesson-8-paragraph-1"},{"text":"Азаматтық құқық объектілері – азаматтық құқық субъектілерінің құқықтары мен міндеттері бағытталатын материалдық және материалдық емес игіліктер [19].","html":"Азаматтық құқық объектілері – азаматтық құқық субъектілерінің құқықтары мен міндеттері бағытталатын материалдық және материалдық емес игіліктер [19].","id":"lesson-8-paragraph-2"},{"text":"Бұл түсінік Қазақстан Республикасының азаматтық заңнамасында көрініс тапқан. Азаматтық кодекс азаматтық құқық объектілерінің түрлерін, олардың айналымдағы орнын, құқықтық режимін және қорғалу тәртібін анықтайды.","html":"Бұл түсінік Қазақстан Республикасының азаматтық заңнамасында көрініс тапқан. Азаматтық кодекс азаматтық құқық объектілерінің түрлерін, олардың айналымдағы орнын, құқықтық режимін және қорғалу тәртібін анықтайды.","id":"lesson-8-paragraph-3"},{"text":"Азаматтық құқық объектілерін дұрыс анықтау азаматтық айналымда өте маңызды. Себебі кез келген мәміле (сату-сатып алу, жалға беру, сыйға тарту, айырбас және т.б.) нақты бір объектіге қатысты жасалады. Сонымен қатар объектінің түріне қарай оған қолданылатын құқықтық талаптар да өзгереді. Мысалы, жылжымайтын мүлікке қатысты мәмілелер мемлекеттік тіркеуден өтуді қажет етеді, ал кейбір объектілер айналымнан алынған немесе айналымы шектелген болуы мүмкін.","html":"Азаматтық құқық объектілерін дұрыс анықтау азаматтық айналымда өте маңызды. Себебі кез келген мәміле (сату-сатып алу, жалға беру, сыйға тарту, айырбас және т.б.) нақты бір объектіге қатысты жасалады. Сонымен қатар объектінің түріне қарай оған қолданылатын құқықтық талаптар да өзгереді. Мысалы, жылжымайтын мүлікке қатысты мәмілелер мемлекеттік тіркеуден өтуді қажет етеді, ал кейбір объектілер айналымнан алынған немесе айналымы шектелген болуы мүмкін.","id":"lesson-8-paragraph-4"},{"text":"Азаматтық құқық объектілері азаматтық құқық қатынасының мазмұнын айқындайды. Нақты айтқанда: қандай құқықтар пайда болатынын; қандай міндеттер жүктелетінін; объектіні беру, пайдалану, қорғау тәртіптерін; бұзылған құқықты қалпына келтіру жолдарын анықтайды. Демек, объект ұғымы азаматтық құқық теориясы мен тәжірибесінің негізгі категорияларының бірі болып саналады.","html":"Азаматтық құқық объектілері азаматтық құқық қатынасының мазмұнын айқындайды. Нақты айтқанда: қандай құқықтар пайда болатынын; қандай міндеттер жүктелетінін; объектіні беру, пайдалану, қорғау тәртіптерін; бұзылған құқықты қалпына келтіру жолдарын анықтайды. Демек, объект ұғымы азаматтық құқық теориясы мен тәжірибесінің негізгі категорияларының бірі болып саналады.","id":"lesson-8-paragraph-5"},{"text":"Қазақстан Республикасының Азаматтық кодексі азаматтық құқық объектілерінің бірнеше түрін көрсетеді. Азаматтық құқық объектілеріне: заттар, ақша, бағалы қағаздар, мүліктік құқықтар, жұмыстар, қызметтер, ақпарат, интеллектуалдық қызмет нәтижелері және материалдық емес игіліктер жатады.","html":"Қазақстан Республикасының Азаматтық кодексі азаматтық құқық объектілерінің бірнеше түрін көрсетеді. Азаматтық құқық объектілеріне: заттар, ақша, бағалы қағаздар, мүліктік құқықтар, жұмыстар, қызметтер, ақпарат, интеллектуалдық қызмет нәтижелері және материалдық емес игіліктер жатады.","id":"lesson-8-paragraph-6"},{"text":"Азаматтық құқықтағы ең кең таралған объект - заттар. Зат дегеніміз азаматтық айналымда қолданылатын, адамның қажеттілігін қанағаттандыратын материалдық дүниелер. Заттар қатарына тұрғын үй, ғимараттар, техника, жиһаз, көлік, жер учаскесі, тұрмыстық тауарлар сияқты мүліктер кіреді.","html":"Азаматтық құқықтағы ең кең таралған объект - заттар. Зат дегеніміз азаматтық айналымда қолданылатын, адамның қажеттілігін қанағаттандыратын материалдық дүниелер. Заттар қатарына тұрғын үй, ғимараттар, техника, жиһаз, көлік, жер учаскесі, тұрмыстық тауарлар сияқты мүліктер кіреді.","id":"lesson-8-paragraph-7"},{"text":"Азаматтық құқық объектілерінің ерекше түрі - ақша. Ақша азаматтық айналымда төлем құралы ретінде қызмет етеді және міндеттемелерді орындаудың негізгі тәсілі болып табылады. Ақша арқылы тауарлар мен қызметтер үшін төлем жүргізіледі, қарыз қайтарылады, жалақы төленеді, айыппұлдар өтеледі.","html":"Азаматтық құқық объектілерінің ерекше түрі - ақша. Ақша азаматтық айналымда төлем құралы ретінде қызмет етеді және міндеттемелерді орындаудың негізгі тәсілі болып табылады. Ақша арқылы тауарлар мен қызметтер үшін төлем жүргізіледі, қарыз қайтарылады, жалақы төленеді, айыппұлдар өтеледі.","id":"lesson-8-paragraph-8"},{"text":"Бағалы қағаздар – белгілі бір мүліктік құқықтарды куәландыратын құжаттар немесе электрондық жазбалар. Бағалы қағаздардың азаматтық айналымда маңызы үлкен, себебі олар капиталдың және мүліктік құқықтардың қозғалысын қамтамасыз етеді.","html":"Бағалы қағаздар – белгілі бір мүліктік құқықтарды куәландыратын құжаттар немесе электрондық жазбалар. Бағалы қағаздардың азаматтық айналымда маңызы үлкен, себебі олар капиталдың және мүліктік құқықтардың қозғалысын қамтамасыз етеді.","id":"lesson-8-paragraph-9"},{"text":"Азаматтық құқық объектісі тек материалдық зат қана емес. Кей жағдайларда құқықтың өзі де азаматтық айналым объектісі болады. Мұндай объектілер мүліктік құқықтар деп аталады. Мүліктік құқықтар - тұлғаның басқа тұлғадан белгілі бір мүлікті немесе мүліктік сипаттағы әрекетті талап етуге байланысты құқықтары. Мысалы, қарызды қайтаруды талап ету құқығы, жалдау ақысын алу құқығы, шарт бойынша төлемді талап ету құқығы және тағы басқа талап ету құқықтары.","html":"Азаматтық құқық объектісі тек материалдық зат қана емес. Кей жағдайларда құқықтың өзі де азаматтық айналым объектісі болады. Мұндай объектілер мүліктік құқықтар деп аталады. Мүліктік құқықтар - тұлғаның басқа тұлғадан белгілі бір мүлікті немесе мүліктік сипаттағы әрекетті талап етуге байланысты құқықтары. Мысалы, қарызды қайтаруды талап ету құқығы, жалдау ақысын алу құқығы, шарт бойынша төлемді талап ету құқығы және тағы басқа талап ету құқықтары.","id":"lesson-8-paragraph-10"},{"text":"Азаматтық айналымдағы қатынастардың бір бөлігі мүлікті берумен емес, жұмыс орындаумен немесе қызмет көрсетумен байланысты. Сондықтан азаматтық құқық объектілерінің қатарына жұмыстар мен қызметтер де кіреді.","html":"Азаматтық айналымдағы қатынастардың бір бөлігі мүлікті берумен емес, жұмыс орындаумен немесе қызмет көрсетумен байланысты. Сондықтан азаматтық құқық объектілерінің қатарына жұмыстар мен қызметтер де кіреді.","id":"lesson-8-paragraph-11"},{"text":"Жұмыс - белгілі бір материалдық нәтиже беретін әрекет. Мысалы, үй салу, жөндеу жасау, көлік құрастыру, бұйым дайындау және т.б. Жұмыс нәтижесі әдетте нақты материалдық түрде көрінеді. Қызмет - материалдық нәтиже міндетті емес, бірақ белгілі бір пайдалы әрекеттің орындалуы. Мысалы, медициналық көмек көрсету, құқықтық кеңес беру, ақпараттық қызмет, тасымалдау, күзет қызметі және т.б. Жұмыс пен қызмет объект болған жағдайда азаматтық құқықта ең маңызды талаптар мыналар: жұмыстың немесе қызметтің мазмұны нақты көрсетілуі, сапа талаптары белгіленуі, орындау мерзімі бекітілуі және ақы төлеу тәртібі анықталуы.","html":"Жұмыс - белгілі бір материалдық нәтиже беретін әрекет. Мысалы, үй салу, жөндеу жасау, көлік құрастыру, бұйым дайындау және т.б. Жұмыс нәтижесі әдетте нақты материалдық түрде көрінеді. Қызмет - материалдық нәтиже міндетті емес, бірақ белгілі бір пайдалы әрекеттің орындалуы. Мысалы, медициналық көмек көрсету, құқықтық кеңес беру, ақпараттық қызмет, тасымалдау, күзет қызметі және т.б. Жұмыс пен қызмет объект болған жағдайда азаматтық құқықта ең маңызды талаптар мыналар: жұмыстың немесе қызметтің мазмұны нақты көрсетілуі, сапа талаптары белгіленуі, орындау мерзімі бекітілуі және ақы төлеу тәртібі анықталуы.","id":"lesson-8-paragraph-12"},{"text":"Қазіргі цифрлық қоғамда ақпараттың құндылығы артты. Ақпарат азаматтық құқық объектісі ретінде көптеген қатынастарда кездеседі. Ақпарат ұйым үшін маңызды коммерциялық құпия болуы мүмкін немесе тұлғаның жеке деректеріне қатысты болуы мүмкін. Ақпарат объект ретінде қарастырылғанда оның құқықтық қорғалуы келесі бағытта жүзеге асады: құпия ақпаратты заңсыз жария етпеу, авторлық немесе сабақтас құқықпен қорғалатын ақпаратты заңсыз пайдаланбау және жеке өмірге қол сұқпаушылықты сақтау [20].","html":"Қазіргі цифрлық қоғамда ақпараттың құндылығы артты. Ақпарат азаматтық құқық объектісі ретінде көптеген қатынастарда кездеседі. Ақпарат ұйым үшін маңызды коммерциялық құпия болуы мүмкін немесе тұлғаның жеке деректеріне қатысты болуы мүмкін. Ақпарат объект ретінде қарастырылғанда оның құқықтық қорғалуы келесі бағытта жүзеге асады: құпия ақпаратты заңсыз жария етпеу, авторлық немесе сабақтас құқықпен қорғалатын ақпаратты заңсыз пайдаланбау және жеке өмірге қол сұқпаушылықты сақтау [20].","id":"lesson-8-paragraph-13"},{"text":"Интеллектуалдық меншік объектілері – адамның шығармашылық еңбегінің нәтижелері. Бұған әдеби, ғылыми, көркем туындылар, өнертабыстар, бағдарламалар және өзге де нәтижелер жатады. Интеллектуалдық меншік объектілеріне сондай-ақ тауар белгілері, қызмет көрсету белгілері, фирмалық атаулар, өндірістік үлгілер секілді кәсіпкерлік айналымдағы дараландыру құралдары жатады [21].","html":"Интеллектуалдық меншік объектілері – адамның шығармашылық еңбегінің нәтижелері. Бұған әдеби, ғылыми, көркем туындылар, өнертабыстар, бағдарламалар және өзге де нәтижелер жатады. Интеллектуалдық меншік объектілеріне сондай-ақ тауар белгілері, қызмет көрсету белгілері, фирмалық атаулар, өндірістік үлгілер секілді кәсіпкерлік айналымдағы дараландыру құралдары жатады [21].","id":"lesson-8-paragraph-14"},{"text":"Азаматтық құқық объектілерінің тағы бір маңызды тобы - материалдық емес игіліктер. Бұлар адамның жеке басына қатысты, ақшаға тікелей бағаланбайтын игіліктер. Оларға: ар-намыс пен қадір-қасиет, іскерлік бедел, жеке өмір құпиясы, есімге құқық, авторлықты тану құқығы және басқа да жеке мүліктік емес құқықтар жатады. Материалдық емес игіліктер адаммен тығыз байланысты болғандықтан басқа тұлғаға берілмейді, сатылмайды, мұрагерлікке берілмейді, бірақ олар бұзылған жағдайда сот арқылы қорғалуға жатады.","html":"Азаматтық құқық объектілерінің тағы бір маңызды тобы - материалдық емес игіліктер. Бұлар адамның жеке басына қатысты, ақшаға тікелей бағаланбайтын игіліктер. Оларға: ар-намыс пен қадір-қасиет, іскерлік бедел, жеке өмір құпиясы, есімге құқық, авторлықты тану құқығы және басқа да жеке мүліктік емес құқықтар жатады. Материалдық емес игіліктер адаммен тығыз байланысты болғандықтан басқа тұлғаға берілмейді, сатылмайды, мұрагерлікке берілмейді, бірақ олар бұзылған жағдайда сот арқылы қорғалуға жатады.","id":"lesson-8-paragraph-15"},{"text":"Жоғарыда аталған азаматтық құқық объектілері азаматтық айналымға қатысып, адамдар мен ұйымдар арасында беріліп, пайдаланылып, айырбасталып отырады. Осыған байланысты азаматтық құқықта “айналым қабілеттілігі” ұғымы қолданылады. Азаматтық құқық объектілерінің айналым қабілеттілігі - белгілі бір объектінің азаматтық айналымда еркін қатысу мүмкіндігі, яғни оны иелену, пайдалану, билік ету, сату, сыйға тарту, жалға беру, мұраға қалдыру, кепілге қою сияқты әрекеттердің заңмен рұқсат етілу немесе шектелу дәрежесі. Айналым қабілеттілігі институты азаматтық қатынастардың қауіпсіз әрі заңды түрде жүзеге асуын қамтамасыз етеді. Өйткені барлық объектілер бірдей еркін айналымға жіберіле бермейді. Кейбір объектілер қоғамдық қауіпсіздікке, мемлекет мүддесіне немесе адам денсаулығына қауіп төндіруі мүмкін. Сондықтан заң белгілі бір объектілерді еркін айналымға жібермеуі немесе оларды ерекше бақылауға алуы ықтимал.","html":"Жоғарыда аталған азаматтық құқық объектілері азаматтық айналымға қатысып, адамдар мен ұйымдар арасында беріліп, пайдаланылып, айырбасталып отырады. Осыған байланысты азаматтық құқықта “айналым қабілеттілігі” ұғымы қолданылады. Азаматтық құқық объектілерінің айналым қабілеттілігі - белгілі бір объектінің азаматтық айналымда еркін қатысу мүмкіндігі, яғни оны иелену, пайдалану, билік ету, сату, сыйға тарту, жалға беру, мұраға қалдыру, кепілге қою сияқты әрекеттердің заңмен рұқсат етілу немесе шектелу дәрежесі. Айналым қабілеттілігі институты азаматтық қатынастардың қауіпсіз әрі заңды түрде жүзеге асуын қамтамасыз етеді. Өйткені барлық объектілер бірдей еркін айналымға жіберіле бермейді. Кейбір объектілер қоғамдық қауіпсіздікке, мемлекет мүддесіне немесе адам денсаулығына қауіп төндіруі мүмкін. Сондықтан заң белгілі бір объектілерді еркін айналымға жібермеуі немесе оларды ерекше бақылауға алуы ықтимал.","id":"lesson-8-paragraph-16"},{"text":"Қазақстан Республикасының азаматтық заңнамасына сәйкес азаматтық құқық объектілері айналымға қатысуына қарай үш негізгі топқа бөлінеді:","html":"Қазақстан Республикасының азаматтық заңнамасына сәйкес азаматтық құқық объектілері айналымға қатысуына қарай үш негізгі топқа бөлінеді:","id":"lesson-8-paragraph-17"},{"text":"еркін айналымдағы объектілер;","html":"еркін айналымдағы объектілер;","list":{"id":"1","ordered":false,"marker":"-","start":1},"id":"lesson-8-paragraph-18"},{"text":"айналымы шектелген объектілер;","html":"айналымы шектелген объектілер;","list":{"id":"1","ordered":false,"marker":"-","start":1},"id":"lesson-8-paragraph-19"},{"text":"айналымнан алынған объектілер.","html":"айналымнан алынған объектілер.","list":{"id":"1","ordered":false,"marker":"-","start":1},"id":"lesson-8-paragraph-20"},{"text":"Еркін айналымдағы объектілер - азаматтық айналымда кедергісіз қолданылатын, кез келген субъектілер арасында еркін берілетін, сатылатын немесе басқа мәмілелермен өткізілетін объектілер. Бұл объектілерге заңмен тыйым салынбаған мүліктердің көпшілігі жатады. Мысалы: тұрмыстық техника, жиһаз, киім, азық-түлік, ақша, көлік, азаматтық мақсаттағы тауарлар және т.б.","html":"Еркін айналымдағы объектілер - азаматтық айналымда кедергісіз қолданылатын, кез келген субъектілер арасында еркін берілетін, сатылатын немесе басқа мәмілелермен өткізілетін объектілер. Бұл объектілерге заңмен тыйым салынбаған мүліктердің көпшілігі жатады. Мысалы: тұрмыстық техника, жиһаз, киім, азық-түлік, ақша, көлік, азаматтық мақсаттағы тауарлар және т.б.","id":"lesson-8-paragraph-21"},{"text":"Еркін айналымдағы объектілермен мәміле жасау үшін арнайы рұқсат (лицензия) талап етілмейді. Алайда кейбір мүліктерге қатысты ерекше рәсімдер болуы мүмкін. Мысалы, көлік құралын сату кезінде тіркеу органдарындағы рәсімдер немесе жылжымайтын мүлікке қатысты нотариалдық куәландыру және мемлекеттік тіркеу.","html":"Еркін айналымдағы объектілермен мәміле жасау үшін арнайы рұқсат (лицензия) талап етілмейді. Алайда кейбір мүліктерге қатысты ерекше рәсімдер болуы мүмкін. Мысалы, көлік құралын сату кезінде тіркеу органдарындағы рәсімдер немесе жылжымайтын мүлікке қатысты нотариалдық куәландыру және мемлекеттік тіркеу.","id":"lesson-8-paragraph-22"},{"text":"Айналымы шектелген объектілер – азаматтық айналымға қатыса алатын, бірақ тек заңда белгіленген ерекше шарттармен, арнайы рұқсатпен немесе белгілі бір тұлғалар шеңберінде ғана иеленуге болатын объектілер. Бұл объектілерге қатысты айналым шектеулері қоғамдық мүддені қорғауға бағытталады. Яғни азаматтық айналымға толық тыйым салынбайды, тек белгілі бір тәртіппен реттеледі.","html":"Айналымы шектелген объектілер – азаматтық айналымға қатыса алатын, бірақ тек заңда белгіленген ерекше шарттармен, арнайы рұқсатпен немесе белгілі бір тұлғалар шеңберінде ғана иеленуге болатын объектілер. Бұл объектілерге қатысты айналым шектеулері қоғамдық мүддені қорғауға бағытталады. Яғни азаматтық айналымға толық тыйым салынбайды, тек белгілі бір тәртіппен реттеледі.","id":"lesson-8-paragraph-23"},{"text":"Айналымы шектелген объектілерге лицензия арқылы сатылатын кейбір тауарлар, арнайы рұқсатпен қолданылатын кейбір құрал-жабдықтар, белгілі санаттағы жер учаскелері, жекелеген сирек табиғи ресурстар жатады. Мұндай объектілер бойынша мәміле жасау кезінде заң талаптарын бұзу мәмілені жарамсыз етуі немесе әкімшілік не қылмыстық жауапкершілікке әкелуі мүмкін.","html":"Айналымы шектелген объектілерге лицензия арқылы сатылатын кейбір тауарлар, арнайы рұқсатпен қолданылатын кейбір құрал-жабдықтар, белгілі санаттағы жер учаскелері, жекелеген сирек табиғи ресурстар жатады. Мұндай объектілер бойынша мәміле жасау кезінде заң талаптарын бұзу мәмілені жарамсыз етуі немесе әкімшілік не қылмыстық жауапкершілікке әкелуі мүмкін.","id":"lesson-8-paragraph-24"},{"text":"Айналымнан алынған объектілер – азаматтық айналымда мүлде қатыса алмайтын, жеке тұлғалар мен ұйымдардың меншік объектісі бола алмайтын объектілер. Бұл объектілерге қатысты негізгі белгі - олар азаматтық мәмілелердің пәні бола алмайды. Яғни оларды сату, сатып алу, сыйға тарту, мұраға қалдыру, жалға беру, кепілге қою мүмкін емес. Айналымнан алынған объектілерге әдетте қоғамға қауіпті немесе мемлекет бақылауында болуы тиіс объектілерге: кейбір қару түрлері, ерекше қауіпті заттар, мемлекет иелігіндегі кейбір мүліктер және т.б. жатады. Бұл объектілер бойынша жасалған мәмілелер заңсыз деп танылып, құқықтық салдары туындамайды. Объектілердің мәртебесін дұрыс анықтау мәмілені заңға сай жасауға, құқық бұзушылықтардың алдын алуға және азаматтық дауларды дұрыс шешуге көмектеседі.","html":"Айналымнан алынған объектілер – азаматтық айналымда мүлде қатыса алмайтын, жеке тұлғалар мен ұйымдардың меншік объектісі бола алмайтын объектілер. Бұл объектілерге қатысты негізгі белгі - олар азаматтық мәмілелердің пәні бола алмайды. Яғни оларды сату, сатып алу, сыйға тарту, мұраға қалдыру, жалға беру, кепілге қою мүмкін емес. Айналымнан алынған объектілерге әдетте қоғамға қауіпті немесе мемлекет бақылауында болуы тиіс объектілерге: кейбір қару түрлері, ерекше қауіпті заттар, мемлекет иелігіндегі кейбір мүліктер және т.б. жатады. Бұл объектілер бойынша жасалған мәмілелер заңсыз деп танылып, құқықтық салдары туындамайды. Объектілердің мәртебесін дұрыс анықтау мәмілені заңға сай жасауға, құқық бұзушылықтардың алдын алуға және азаматтық дауларды дұрыс шешуге көмектеседі.","id":"lesson-8-paragraph-25"},{"text":"Заттардың өз ішінде де құқықтық режимі бойынша маңызды жіктелуі бар. Біріншісі - жылжымайтын және жылжымалы мүлік. Жылжымайтын мүлікке жер және жермен тығыз байланыстағы объектілер жатады. Мұндай мүлікке құқық мемлекеттік тіркеуден өтеді. Жылжымалы мүлікке қалған барлық мүлік жатады. Екіншісі - бөлінетін және бөлінбейтін заттар. Егер затты бөліп пайдалануға болса және бөлгенде мәні жоғалмаса – бөлінетін. Егер бөліп жіберу нәтижесінде оның мәні жоғалса – бөлінбейтін. Үшіншісі – тұтынылатын және тұтынылмайтын заттар. Тұтынылатын зат қолданған кезде жойылады, тұтынылмайтын зат ұзақ уақыт қолданылады.","html":"Заттардың өз ішінде де құқықтық режимі бойынша маңызды жіктелуі бар. Біріншісі - жылжымайтын және жылжымалы мүлік. Жылжымайтын мүлікке жер және жермен тығыз байланыстағы объектілер жатады. Мұндай мүлікке құқық мемлекеттік тіркеуден өтеді. Жылжымалы мүлікке қалған барлық мүлік жатады. Екіншісі - бөлінетін және бөлінбейтін заттар. Егер затты бөліп пайдалануға болса және бөлгенде мәні жоғалмаса – бөлінетін. Егер бөліп жіберу нәтижесінде оның мәні жоғалса – бөлінбейтін. Үшіншісі – тұтынылатын және тұтынылмайтын заттар. Тұтынылатын зат қолданған кезде жойылады, тұтынылмайтын зат ұзақ уақыт қолданылады.","id":"lesson-8-paragraph-26"},{"text":"Азаматтық құқық объектілеріне қатысты құқық бұзылған жағдайда заңнама қорғау механизмдерін ұсынады. Негізгі қорғау тәсілдері ретінде төмендегі тәсілдер қолданылады:","html":"Азаматтық құқық объектілеріне қатысты құқық бұзылған жағдайда заңнама қорғау механизмдерін ұсынады. Негізгі қорғау тәсілдері ретінде төмендегі тәсілдер қолданылады:","id":"lesson-8-paragraph-27"},{"text":"– құқықты тану;","html":"– құқықты тану;","id":"lesson-8-paragraph-28"},{"text":"– құқық бұзушылықты тоқтату;","html":"– құқық бұзушылықты тоқтату;","id":"lesson-8-paragraph-29"},{"text":"– залалды өтеу;","html":"– залалды өтеу;","id":"lesson-8-paragraph-30"},{"text":"– моральдық зиянды өтеу;","html":"– моральдық зиянды өтеу;","id":"lesson-8-paragraph-31"},{"text":"– мүлікті заңсыз иеленуден қайтару;","html":"– мүлікті заңсыз иеленуден қайтару;","id":"lesson-8-paragraph-32"},{"text":"– мәмілені жарамсыз деп тану;","html":"– мәмілені жарамсыз деп тану;","id":"lesson-8-paragraph-33"},{"text":"– міндеттемені мәжбүрлеп орындату.","html":"– міндеттемені мәжбүрлеп орындату.","id":"lesson-8-paragraph-34"},{"text":"Мысалы, меншік иесінің мүлкін басқа адам заңсыз ұстап отырса, меншік иесі оны сот арқылы қайтарып алуға құқылы. Ал азаматтың ар-намысы мен қадір-қасиетіне нұқсан келтірілсе, ол теріске шығаруды талап ете алады және моральдық зиянды өндіруді сұрауға құқылы.","html":"Мысалы, меншік иесінің мүлкін басқа адам заңсыз ұстап отырса, меншік иесі оны сот арқылы қайтарып алуға құқылы. Ал азаматтың ар-намысы мен қадір-қасиетіне нұқсан келтірілсе, ол теріске шығаруды талап ете алады және моральдық зиянды өндіруді сұрауға құқылы.","id":"lesson-8-paragraph-35"},{"text":"Қорытындылай келе, азаматтық құқық объектілері - азаматтық құқық қатынастарының маңызды элементі. Азаматтық айналымдағы кез келген құқықтық қатынас белгілі бір объектіге бағытталады. Ал осы объектілерді дұрыс тану азаматтық құқық нормаларын дұрыс қолдануға, мәміле жасауда заң талаптарын сақтауға және құқық бұзылған жағдайда тиімді қорғау тәсілін таңдауға мүмкіндік береді.","html":"Қорытындылай келе, азаматтық құқық объектілері - азаматтық құқық қатынастарының маңызды элементі. Азаматтық айналымдағы кез келген құқықтық қатынас белгілі бір объектіге бағытталады. Ал осы объектілерді дұрыс тану азаматтық құқық нормаларын дұрыс қолдануға, мәміле жасауда заң талаптарын сақтауға және құқық бұзылған жағдайда тиімді қорғау тәсілін таңдауға мүмкіндік береді.","id":"lesson-8-paragraph-36"}],"words":1240,"legacyAnchors":{"lesson-8-section-1":"lesson-8-paragraph-1","lesson-8-section-2":"lesson-8-paragraph-6","lesson-8-section-3":"lesson-8-paragraph-16","lesson-8-section-4":"lesson-8-paragraph-26","lesson-8-section-5":"lesson-8-paragraph-27"}},"9":{"title":"9-ТАҚЫРЫП. АЗАМАТТЫҚ ҚҰҚЫҚ ОБЪЕКТІЛЕРІ РЕТІНДЕ БАҒАЛЫ ҚАҒАЗДАР, МҮЛІКТІК ЕМЕС ИГІЛІКТЕР МЕН ҚҰҚЫҚТАР","blocks":[{"text":"Азаматтық құқық объектілері азаматтық құқықтық қатынастардың негізгі элементтерінің бірі болып табылады. Азаматтық құқық субъектілері арасындағы кез келген құқықтық қатынас белгілі бір объектіге бағытталады. Қазақстан Республикасының Азаматтық кодексіне сәйкес азаматтық құқық объектілері ретінде заттар, ақша, бағалы қағаздар, мүліктік құқықтар, жұмыстар мен қызметтер, ақпарат, интеллектуалдық қызмет нәтижелері және материалдық емес игіліктер танылатындығы туралы 8-тақырыпта егжей-тегжейлі айтылды. Ал бұл тақырыпта азаматтық құқық объектілерінің ішінде бағалы қағаздар, мүліктік құқықтар және материалдық емес игіліктердің құқықтық табиғаты, айналымдағы орны мен қорғалу ерекшеліктері жан-жақты қарастырылады. Өйткені бұл объектілер қазіргі таңда азаматтық құқықтық қатынастардың тікей объектісі ретінде жиі танылып келеді.","html":"Азаматтық құқық объектілері азаматтық құқықтық қатынастардың негізгі элементтерінің бірі болып табылады. Азаматтық құқық субъектілері арасындағы кез келген құқықтық қатынас белгілі бір объектіге бағытталады. Қазақстан Республикасының Азаматтық кодексіне сәйкес азаматтық құқық объектілері ретінде заттар, ақша, бағалы қағаздар, мүліктік құқықтар, жұмыстар мен қызметтер, ақпарат, интеллектуалдық қызмет нәтижелері және материалдық емес игіліктер танылатындығы туралы 8-тақырыпта егжей-тегжейлі айтылды. Ал бұл тақырыпта азаматтық құқық объектілерінің ішінде бағалы қағаздар, мүліктік құқықтар және материалдық емес игіліктердің құқықтық табиғаты, айналымдағы орны мен қорғалу ерекшеліктері жан-жақты қарастырылады. Өйткені бұл объектілер қазіргі таңда азаматтық құқықтық қатынастардың тікей объектісі ретінде жиі танылып келеді.","id":"lesson-9-paragraph-1"},{"text":"Бағалы қағаздар азаматтық құқық объектілерінің маңызды әрі күрделі түрлерінің бірі болып саналады. Қазақстан Республикасының Азаматтық кодексінің 129-бабына сәйкес бағалы қағаз - белгіленген нысан мен міндетті реквизиттері бар, мүліктік құқықтарды куәландыратын және оны ұсыну арқылы ғана іске асыруға болатын құжат немесе электрондық жазба [2].","html":"Бағалы қағаздар азаматтық құқық объектілерінің маңызды әрі күрделі түрлерінің бірі болып саналады. Қазақстан Республикасының Азаматтық кодексінің 129-бабына сәйкес бағалы қағаз - белгіленген нысан мен міндетті реквизиттері бар, мүліктік құқықтарды куәландыратын және оны ұсыну арқылы ғана іске асыруға болатын құжат немесе электрондық жазба [2].","id":"lesson-9-paragraph-2"},{"text":"Бағалы қағаздардың негізгі ерекшелігі - олар белгілі бір мүліктік құқықты бекітеді және азаматтық айналымда еркін айнала алады. Мысалы, акция иесіне акционерлік қоғамның пайдасынан дивиденд алу және қоғамды басқаруға қатысу құқығын береді. Облигация иесі эмитенттен белгіленген мерзімде қарыз сомасын және сыйақы алуға құқылы.","html":"Бағалы қағаздардың негізгі ерекшелігі - олар белгілі бір мүліктік құқықты бекітеді және азаматтық айналымда еркін айнала алады. Мысалы, акция иесіне акционерлік қоғамның пайдасынан дивиденд алу және қоғамды басқаруға қатысу құқығын береді. Облигация иесі эмитенттен белгіленген мерзімде қарыз сомасын және сыйақы алуға құқылы.","id":"lesson-9-paragraph-3"},{"text":"Бағалы қағаздардың азаматтық айналымдағы рөлі өте жоғары. Олар капиталдың қозғалысын қамтамасыз етеді, инвестициялық қатынастарды дамытады және кәсіпкерлік қызметтің тиімділігін арттырады. Қарапайым мысал ретінде Нұрлан есімді азамат компанияның акцияларын сатып алып, сол арқылы компания табысынан үлес алады. Бұл жағдайда акция - азаматтық құқық объектісі, ал азаматтың дивиденд алу құқығы - мүліктік құқық болып табылады.","html":"Бағалы қағаздардың азаматтық айналымдағы рөлі өте жоғары. Олар капиталдың қозғалысын қамтамасыз етеді, инвестициялық қатынастарды дамытады және кәсіпкерлік қызметтің тиімділігін арттырады. Қарапайым мысал ретінде Нұрлан есімді азамат компанияның акцияларын сатып алып, сол арқылы компания табысынан үлес алады. Бұл жағдайда акция - азаматтық құқық объектісі, ал азаматтың дивиденд алу құқығы - мүліктік құқық болып табылады.","id":"lesson-9-paragraph-4"},{"text":"Бағалы қағаздардың төмендегідей бірнеше түрлері бар:","html":"Бағалы қағаздардың төмендегідей бірнеше түрлері бар:","id":"lesson-9-paragraph-5"},{"text":"Акция - акционерлік қоғам шығаратын бағалы қағаз болып табылады","html":"Акция - акционерлік қоғам шығаратын бағалы қағаз болып табылады","id":"lesson-9-paragraph-6"},{"text":"және ол оның иесіне қоғамның пайдасынан дивиденд алу, сондай-ақ қоғамды басқаруға қатысу құқықтарын береді. Акция иесі акционерлік қоғамның мүлкіне тікелей иелік етпейді, бірақ қоғам таратылған жағдайда оның мүлкінен үлес алуға құқылы.","html":"және ол оның иесіне қоғамның пайдасынан дивиденд алу, сондай-ақ қоғамды басқаруға қатысу құқықтарын береді. Акция иесі акционерлік қоғамның мүлкіне тікелей иелік етпейді, бірақ қоғам таратылған жағдайда оның мүлкінен үлес алуға құқылы.","id":"lesson-9-paragraph-7"},{"text":"Облигация – қарыздық бағалы қағаз, ол облигация иесінің эмитенттен белгіленген мерзімде облигацияның номиналдық құнын және пайыз (сыйақы) алу құқығын білдіреді. Облигация иесі эмитенттің кредиторы болып саналады.","html":"Облигация – қарыздық бағалы қағаз, ол облигация иесінің эмитенттен белгіленген мерзімде облигацияның номиналдық құнын және пайыз (сыйақы) алу құқығын білдіреді. Облигация иесі эмитенттің кредиторы болып саналады.","id":"lesson-9-paragraph-8"},{"text":"Вексель – белгілі бір ақша сомасын белгіленген мерзімде төлеу жөніндегі жазбаша міндеттеме болып табылады. Ол көбіне кәсіпкерлік айналымда төлемді кейінге қалдыру құралы ретінде пайдаланылады.","html":"Вексель – белгілі бір ақша сомасын белгіленген мерзімде төлеу жөніндегі жазбаша міндеттеме болып табылады. Ол көбіне кәсіпкерлік айналымда төлемді кейінге қалдыру құралы ретінде пайдаланылады.","id":"lesson-9-paragraph-9"},{"text":"Чек – чек берушінің банкке чек ұстаушыға белгілі бір ақша сомасын төлеу туралы жазбаша өкімі. Чек төлем құралы ретінде қолданылады.","html":"Чек – чек берушінің банкке чек ұстаушыға белгілі бір ақша сомасын төлеу туралы жазбаша өкімі. Чек төлем құралы ретінде қолданылады.","id":"lesson-9-paragraph-10"},{"text":"Депозиттік және жинақ сертификаттары – банктегі салымның бар екенін және салымды белгіленген мерзімде алу құқығын куәландыратын бағалы қағаздар.","html":"Депозиттік және жинақ сертификаттары – банктегі салымның бар екенін және салымды белгіленген мерзімде алу құқығын куәландыратын бағалы қағаздар.","id":"lesson-9-paragraph-11"},{"text":"Коносамент – теңіз немесе жүк тасымалдау қатынастарында қолданылатын бағалы қағаз, ол жүкке меншік құқығын және оны алуға құқық береді [22].","html":"Коносамент – теңіз немесе жүк тасымалдау қатынастарында қолданылатын бағалы қағаз, ол жүкке меншік құқығын және оны алуға құқық береді [22].","id":"lesson-9-paragraph-12"},{"text":"Бағалы қағаздар құжаттық және құжатсыз нысанда болуы мүмкін. Қазіргі таңда Қазақстанда бағалы қағаздардың басым бөлігі электрондық түрде айналымға енгізілген. Бұл олардың қауіпсіздігін арттырып, азаматтық айналымды жеңілдетеді [23].","html":"Бағалы қағаздар құжаттық және құжатсыз нысанда болуы мүмкін. Қазіргі таңда Қазақстанда бағалы қағаздардың басым бөлігі электрондық түрде айналымға енгізілген. Бұл олардың қауіпсіздігін арттырып, азаматтық айналымды жеңілдетеді [23].","id":"lesson-9-paragraph-13"},{"text":"Мүліктік құқықтар - азаматтық құқық объектілерінің ерекше санаты. Олар материалдық зат ретінде емес, белгілі бір мүлікті немесе мүліктік сипаттағы әрекетті талап ету құқығы ретінде көрініс табады. Қазақстан Республикасының Азаматтық кодексінің 115-бабына сәйкес мүліктік құқықтар азаматтық құқық объектілеріне жатады.","html":"Мүліктік құқықтар - азаматтық құқық объектілерінің ерекше санаты. Олар материалдық зат ретінде емес, белгілі бір мүлікті немесе мүліктік сипаттағы әрекетті талап ету құқығы ретінде көрініс табады. Қазақстан Республикасының Азаматтық кодексінің 115-бабына сәйкес мүліктік құқықтар азаматтық құқық объектілеріне жатады.","id":"lesson-9-paragraph-14"},{"text":"Мүліктік құқықтардың басты ерекшелігі - олардың экономикалық мазмұны мен ақшалай бағалануы. Мысалы, Абзал есімді азамат досына қарыз берсе, Абзалдың досынан қарызды қайтаруды талап ету құқығы мүліктік құқық болып табылады. Бұл құқықты басқа тұлғаға беруге, кепілге қоюға немесе мұраға қалдыруға болады. Мүліктік құқықтарға шарттан туындайтын талап ету құқықтары, авторлық сыйақы алу құқығы, жалдау ақысын алу құқығы және тағы басқа құқықтар жатады. Азаматтық айналымда мүліктік құқықтар жиі мәміле объектісі болады. Мысалы, талап ету құқығын басқа тұлғаға беру цессия шарты арқылы жүзеге асырылады. Мүліктік құқықтардың айналым қабілеттілігі заңмен шектелуі мүмкін. Кейбір құқықтар тек белгілі бір тұлғаға ғана тиесілі болып, басқаға берілмейді. Мысалы, алимент алу құқығы жеке сипатқа ие болғандықтан айналымға жатпайды.","html":"Мүліктік құқықтардың басты ерекшелігі - олардың экономикалық мазмұны мен ақшалай бағалануы. Мысалы, Абзал есімді азамат досына қарыз берсе, Абзалдың досынан қарызды қайтаруды талап ету құқығы мүліктік құқық болып табылады. Бұл құқықты басқа тұлғаға беруге, кепілге қоюға немесе мұраға қалдыруға болады. Мүліктік құқықтарға шарттан туындайтын талап ету құқықтары, авторлық сыйақы алу құқығы, жалдау ақысын алу құқығы және тағы басқа құқықтар жатады. Азаматтық айналымда мүліктік құқықтар жиі мәміле объектісі болады. Мысалы, талап ету құқығын басқа тұлғаға беру цессия шарты арқылы жүзеге асырылады. Мүліктік құқықтардың айналым қабілеттілігі заңмен шектелуі мүмкін. Кейбір құқықтар тек белгілі бір тұлғаға ғана тиесілі болып, басқаға берілмейді. Мысалы, алимент алу құқығы жеке сипатқа ие болғандықтан айналымға жатпайды.","id":"lesson-9-paragraph-15"},{"text":"Материалдық емес игіліктер азаматтық құқық объектілерінің ерекше тобына жатады. Қазақстан Республикасының Азаматтық кодексінің 143-бабына сәйкес материалдық емес игіліктерге адамның өмірі, денсаулығы, ар-намысы, қадір-қасиеті, іскерлік беделі, жеке өмірге қол сұқпаушылық, есімге құқық және басқа да жеке мүліктік емес құқықтар жатады. Бұл игіліктердің басты ерекшелігі - олардың экономикалық мазмұны жоқ және тікелей ақшалай бағаланбайды. Олар адаммен ажырамас байланыста болады және басқа тұлғаға берілмейді. Мысалы, азаматтың ар-намысы мен қадір-қасиетін сату немесе сыйға тарту мүмкін емес.","html":"Материалдық емес игіліктер азаматтық құқық объектілерінің ерекше тобына жатады. Қазақстан Республикасының Азаматтық кодексінің 143-бабына сәйкес материалдық емес игіліктерге адамның өмірі, денсаулығы, ар-намысы, қадір-қасиеті, іскерлік беделі, жеке өмірге қол сұқпаушылық, есімге құқық және басқа да жеке мүліктік емес құқықтар жатады. Бұл игіліктердің басты ерекшелігі - олардың экономикалық мазмұны жоқ және тікелей ақшалай бағаланбайды. Олар адаммен ажырамас байланыста болады және басқа тұлғаға берілмейді. Мысалы, азаматтың ар-намысы мен қадір-қасиетін сату немесе сыйға тарту мүмкін емес.","id":"lesson-9-paragraph-16"},{"text":"Дегенмен материалдық емес игіліктер бұзылған жағдайда азаматтық-құқықтық қорғау тәсілдері қолданылады. Мысалы, Айбар, Айдос есімді көршісі туралы жалған мәліметтер таратып, оның ар-намысына нұқсан келтірілсе, Айдос сот арқылы жалған мәліметті теріске шығаруды және моральдық зиянды өтеуді талап етуге құқылы.","html":"Дегенмен материалдық емес игіліктер бұзылған жағдайда азаматтық-құқықтық қорғау тәсілдері қолданылады. Мысалы, Айбар, Айдос есімді көршісі туралы жалған мәліметтер таратып, оның ар-намысына нұқсан келтірілсе, Айдос сот арқылы жалған мәліметті теріске шығаруды және моральдық зиянды өтеуді талап етуге құқылы.","id":"lesson-9-paragraph-17"},{"text":"Материалдық емес игіліктерді қорғау азаматтық құқықтағы маңызды бағыттардың бірі болып табылады. Қазіргі цифрлық қоғамда жеке өмірге қол сұқпаушылық, жеке деректерді қорғау мәселелері ерекше маңызға ие болып отыр [24].","html":"Материалдық емес игіліктерді қорғау азаматтық құқықтағы маңызды бағыттардың бірі болып табылады. Қазіргі цифрлық қоғамда жеке өмірге қол сұқпаушылық, жеке деректерді қорғау мәселелері ерекше маңызға ие болып отыр [24].","id":"lesson-9-paragraph-18"},{"text":"Қорытындылай келе, бағалы қағаздар, мүліктік құқықтар және материалдық емес игіліктер азаматтық құқық объектілерінің маңызды түрлері болып табылады. Бағалы қағаздар экономикалық айналымның негізін құраса, мүліктік құқықтар міндеттемелік қатынастардың мазмұнын айқындайды. Ал материалдық емес игіліктер адамның жеке басының құқықтарын қорғауға бағытталған. Сонымен қатар азаматтық құқық объектілерін дұрыс анықтау азаматтық-құқықтық қатынастарды тиімді реттеуге, мәмілелерді заңға сай жасауға және бұзылған құқықтарды уақтылы қорғауға мүмкіндік береді.","html":"Қорытындылай келе, бағалы қағаздар, мүліктік құқықтар және материалдық емес игіліктер азаматтық құқық объектілерінің маңызды түрлері болып табылады. Бағалы қағаздар экономикалық айналымның негізін құраса, мүліктік құқықтар міндеттемелік қатынастардың мазмұнын айқындайды. Ал материалдық емес игіліктер адамның жеке басының құқықтарын қорғауға бағытталған. Сонымен қатар азаматтық құқық объектілерін дұрыс анықтау азаматтық-құқықтық қатынастарды тиімді реттеуге, мәмілелерді заңға сай жасауға және бұзылған құқықтарды уақтылы қорғауға мүмкіндік береді.","id":"lesson-9-paragraph-19"}],"words":755,"legacyAnchors":{"lesson-9-section-1":"lesson-9-paragraph-1","lesson-9-section-2":"lesson-9-paragraph-5","lesson-9-section-3":"lesson-9-paragraph-14","lesson-9-section-4":"lesson-9-paragraph-16"}},"10":{"title":"10-ТАҚЫРЫП. МӘМІЛЕ","blocks":[{"text":"Азаматтық құқық саласында мәміле ұғымы ерекше маңызды орын алады. Қоғамдағы адамдар мен ұйымдар арасындағы экономикалық, мүліктік және құқықтық қатынастардың басым көпшілігі мәмілелер арқылы жүзеге асырылады. Сатып алу-сату, жалға беру, сыйға тарту, қарыз алу, қызмет көрсету сияқты күнделікті өмірде жиі кездесетін әрекеттердің барлығы мәміле болып табылады. Қазақстан Республикасының Азаматтық кодексінде мәмілеге арнайы құқықтық анықтама берілген. Мәміле арқылы азаматтар мен заңды тұлғалар өз құқықтары мен міндеттерін белгілейді, өзгертеді немесе тоқтатады. Сондықтан мәміле азаматтық құқықтық қатынастардың негізін құрайтын басты құрал болып саналады [25].","html":"Азаматтық құқық саласында мәміле ұғымы ерекше маңызды орын алады. Қоғамдағы адамдар мен ұйымдар арасындағы экономикалық, мүліктік және құқықтық қатынастардың басым көпшілігі мәмілелер арқылы жүзеге асырылады. Сатып алу-сату, жалға беру, сыйға тарту, қарыз алу, қызмет көрсету сияқты күнделікті өмірде жиі кездесетін әрекеттердің барлығы мәміле болып табылады. Қазақстан Республикасының Азаматтық кодексінде мәмілеге арнайы құқықтық анықтама берілген. Мәміле арқылы азаматтар мен заңды тұлғалар өз құқықтары мен міндеттерін белгілейді, өзгертеді немесе тоқтатады. Сондықтан мәміле азаматтық құқықтық қатынастардың негізін құрайтын басты құрал болып саналады [25].","id":"lesson-10-paragraph-1"},{"text":"Қазақстан Республикасының Азаматтық кодексіне сәйкес, мәміле деп азаматтар мен заңды тұлғалардың азаматтық құқықтар мен міндеттерді белгілеуге, өзгертуге немесе тоқтатуға бағытталған әрекеттері танылады. Бұл анықтамадан мәміленің бірнеше төмендегідей негізгі белгілерін көруге болады:","html":"Қазақстан Республикасының Азаматтық кодексіне сәйкес, мәміле деп азаматтар мен заңды тұлғалардың азаматтық құқықтар мен міндеттерді белгілеуге, өзгертуге немесе тоқтатуға бағытталған әрекеттері танылады. Бұл анықтамадан мәміленің бірнеше төмендегідей негізгі белгілерін көруге болады:","id":"lesson-10-paragraph-2"},{"text":"Біріншіден, мәміле – бұл саналы әрекет. Яғни мәміле адамның еркімен жасалады. Адам өз еркін білдірмейінше, мәміле пайда болмайды.","html":"Біріншіден, мәміле – бұл саналы әрекет. Яғни мәміле адамның еркімен жасалады. Адам өз еркін білдірмейінше, мәміле пайда болмайды.","id":"lesson-10-paragraph-3"},{"text":"Екіншіден, мәміле құқықтық салдарға бағытталған. Ол белгілі бір құқықтар мен міндеттердің туындауына, өзгеруіне немесе тоқтауына әкеледі.","html":"Екіншіден, мәміле құқықтық салдарға бағытталған. Ол белгілі бір құқықтар мен міндеттердің туындауына, өзгеруіне немесе тоқтауына әкеледі.","id":"lesson-10-paragraph-4"},{"text":"Үшіншіден, мәміле азаматтық құқық субъектілері арасында жасалады. Оларға жеке тұлғалар, заңды тұлғалар және мемлекет жатады.","html":"Үшіншіден, мәміле азаматтық құқық субъектілері арасында жасалады. Оларға жеке тұлғалар, заңды тұлғалар және мемлекет жатады.","id":"lesson-10-paragraph-5"},{"text":"Мәміленің басты мақсаты - қатысушылардың мүддесін қамтамасыз ету. Мысалы, сатып алушы тауар алуға мүдделі болса, сатушы ақша алуға мүдделі болады. Осылайша мәміле тараптардың қажеттіліктерін қанағаттандырады. Қазіргі нарықтық экономика жағдайында мәміленің рөлі ерекше артты. Кәсіпкерлік қызмет, инвестиция, сауда, қызмет көрсету салаларының барлығы мәміле арқылы жүзеге асырылады.","html":"Мәміленің басты мақсаты - қатысушылардың мүддесін қамтамасыз ету. Мысалы, сатып алушы тауар алуға мүдделі болса, сатушы ақша алуға мүдделі болады. Осылайша мәміле тараптардың қажеттіліктерін қанағаттандырады. Қазіргі нарықтық экономика жағдайында мәміленің рөлі ерекше артты. Кәсіпкерлік қызмет, инвестиция, сауда, қызмет көрсету салаларының барлығы мәміле арқылы жүзеге асырылады.","id":"lesson-10-paragraph-6"},{"text":"Мәмілелер бірнеше белгілер бойынша жіктеледі. Тараптар санына қарай мәмілелер біржақты, екіжақты және көпжақты мәміле деп бөлінеді. Біржақты мәміле - бір тараптың еркі жеткілікті болатын мәміле. Мысалы: өсиет жасау, сенімхат беру, конкурсты жариялау. Екіжақты мәміле - екі тараптың келісімімен жасалатын мәміле. Мысалы: сатып алу-сату, жалға беру, қарыз шарты. Көпжақты мәміле - үш немесе одан да көп тараптың қатысуымен жасалатын мәміле. Мысалы: құрылтай шарты, бірлескен қызмет туралы шарт.","html":"Мәмілелер бірнеше белгілер бойынша жіктеледі. Тараптар санына қарай мәмілелер біржақты, екіжақты және көпжақты мәміле деп бөлінеді. Біржақты мәміле - бір тараптың еркі жеткілікті болатын мәміле. Мысалы: өсиет жасау, сенімхат беру, конкурсты жариялау. Екіжақты мәміле - екі тараптың келісімімен жасалатын мәміле. Мысалы: сатып алу-сату, жалға беру, қарыз шарты. Көпжақты мәміле - үш немесе одан да көп тараптың қатысуымен жасалатын мәміле. Мысалы: құрылтай шарты, бірлескен қызмет туралы шарт.","id":"lesson-10-paragraph-7"},{"text":"Мақсатына қарай: өтемді мәміле - тараптар бір-біріне қарсы міндеттер алады. Мысалы, сатып алу-сату, жалдау шарты. Өтемсіз мәміле - бір тарап екінші тарапқа тегін мүлік береді. Мысал ретінде сыйға тарту шартын айтуға болады.","html":"Мақсатына қарай: өтемді мәміле - тараптар бір-біріне қарсы міндеттер алады. Мысалы, сатып алу-сату, жалдау шарты. Өтемсіз мәміле - бір тарап екінші тарапқа тегін мүлік береді. Мысал ретінде сыйға тарту шартын айтуға болады.","id":"lesson-10-paragraph-8"},{"text":"Жасалу уақытына қарай: консенсуалды мәміле - тараптардың келісімі жасалған сәттен бастап күшіне енеді. Мысалы, сатып алу-сату шарты. Нақты мәміле - мүлік берілгеннен кейін ғана күшіне енеді. Мысал ретінде қарыз шартын айтуға болады.","html":"Жасалу уақытына қарай: консенсуалды мәміле - тараптардың келісімі жасалған сәттен бастап күшіне енеді. Мысалы, сатып алу-сату шарты. Нақты мәміле - мүлік берілгеннен кейін ғана күшіне енеді. Мысал ретінде қарыз шартын айтуға болады.","id":"lesson-10-paragraph-9"},{"text":"Мәміле заңда белгіленген нысанда жасалуы тиіс. Нысан - мәміленің сыртқы көрінісі. Ауызша мәміле - тараптардың ауызша келісімі арқылы жасалады. Мысалы, дүкеннен нан сатып алу, таксиге отыру жағдайларын жатқызсақ болады. Ауызша мәміле әдетте күнделікті тұрмыста, шағын сомада және дереу орындалатын жағдайларда қолданылады.","html":"Мәміле заңда белгіленген нысанда жасалуы тиіс. Нысан - мәміленің сыртқы көрінісі. Ауызша мәміле - тараптардың ауызша келісімі арқылы жасалады. Мысалы, дүкеннен нан сатып алу, таксиге отыру жағдайларын жатқызсақ болады. Ауызша мәміле әдетте күнделікті тұрмыста, шағын сомада және дереу орындалатын жағдайларда қолданылады.","id":"lesson-10-paragraph-10"},{"text":"Жазбаша мәміле қағаз түрінде немесе электронды түрде рәсімделеді. Жазбаша мәміле қарапайым жазбаша және нотариалды куәландырылған болуы мүмкін [26].","html":"Жазбаша мәміле қағаз түрінде немесе электронды түрде рәсімделеді. Жазбаша мәміле қарапайым жазбаша және нотариалды куәландырылған болуы мүмкін [26].","id":"lesson-10-paragraph-11"},{"text":"Мысалға алатын болсақ, несие шарты, жалдау шарты, сатып алу-сату келісімі жазбаша нысанда жасалады. Кейбір мәмілелер міндетті түрде нотариус арқылы куәландырылуы тиіс. Мысалы, жылжымайтын мүлікті сату шарты, өсиет және неке шарты міндетті түрде нотариалды куәландырылуға жатады. Нысан талаптары сақталмаса, мәміле жарамсыз деп танылуы мүмкін.","html":"Мысалға алатын болсақ, несие шарты, жалдау шарты, сатып алу-сату келісімі жазбаша нысанда жасалады. Кейбір мәмілелер міндетті түрде нотариус арқылы куәландырылуы тиіс. Мысалы, жылжымайтын мүлікті сату шарты, өсиет және неке шарты міндетті түрде нотариалды куәландырылуға жатады. Нысан талаптары сақталмаса, мәміле жарамсыз деп танылуы мүмкін.","id":"lesson-10-paragraph-12"},{"text":"Мәміле заң бойынша жарамды болу үшін жарамдылық шарттары сақталу қажет. Мәміле жасайтын тұлғалар әрекетке қабілетті, есі дұрыс және заңмен шектелмеген болуы тиіс. Мысалы, кәмелетке толмаған немесе әрекетке қабілетсіз адам кейбір мәмілелерді өз бетінше жасай алмайды. Адам мәмілені еркін түрде жасауы тиіс. Егер мәміле алдау, күш қолдану неммесе қорқыту арқылы жасалса, ол жарамсыз деп танылады. Сондай-ақ, мәміле заң талаптарына қайшы келмеуі керек. Мысалы: заңсыз заттарды сату, жалған құжат жасау - жарамсыз мәміле. Мәміленің белгіленген нысанда жасалмауы оның заңды күшін жоғалтуы мүмкін.","html":"Мәміле заң бойынша жарамды болу үшін жарамдылық шарттары сақталу қажет. Мәміле жасайтын тұлғалар әрекетке қабілетті, есі дұрыс және заңмен шектелмеген болуы тиіс. Мысалы, кәмелетке толмаған немесе әрекетке қабілетсіз адам кейбір мәмілелерді өз бетінше жасай алмайды. Адам мәмілені еркін түрде жасауы тиіс. Егер мәміле алдау, күш қолдану неммесе қорқыту арқылы жасалса, ол жарамсыз деп танылады. Сондай-ақ, мәміле заң талаптарына қайшы келмеуі керек. Мысалы: заңсыз заттарды сату, жалған құжат жасау - жарамсыз мәміле. Мәміленің белгіленген нысанда жасалмауы оның заңды күшін жоғалтуы мүмкін.","id":"lesson-10-paragraph-13"},{"text":"Жарамсыз мәміле - заң талаптарына сәйкес келмейтін және құқықтық салдар тудырмайтын мәміле. Жарамсыз деп танылатын мәміле - сот шешімімен жарамсыз болады. Өздігінен жарамсыз мәміле - заң бойынша бірден жарамсыз деп саналады. Жарамсыз мәміле жасалған жағдайда тараптар алған мүлікті бір-біріне қайтарады, келтірілген зиян өтеледі, кейде жауапкершілік жүктеледі.Мысалы, заңсыз мәміле арқылы алынған ақша кері қайтарылады. Осы жағдайда қолданылатын негізгі құқықтық тетік реституция болып табылады.","html":"Жарамсыз мәміле - заң талаптарына сәйкес келмейтін және құқықтық салдар тудырмайтын мәміле. Жарамсыз деп танылатын мәміле - сот шешімімен жарамсыз болады. Өздігінен жарамсыз мәміле - заң бойынша бірден жарамсыз деп саналады. Жарамсыз мәміле жасалған жағдайда тараптар алған мүлікті бір-біріне қайтарады, келтірілген зиян өтеледі, кейде жауапкершілік жүктеледі.Мысалы, заңсыз мәміле арқылы алынған ақша кері қайтарылады. Осы жағдайда қолданылатын негізгі құқықтық тетік реституция болып табылады.","id":"lesson-10-paragraph-14"},{"text":"Реституция - жарамсыз мәміленің салдарын жою мақсатында тараптардың бір-біріне алған мүлкін, ақшасын немесе өзге де мүліктік игіліктерін қайтаруы. Оның басты мақсаты - тараптарды мәміле жасалғанға дейінгі бастапқы жағдайына келтіру [27].","html":"Реституция - жарамсыз мәміленің салдарын жою мақсатында тараптардың бір-біріне алған мүлкін, ақшасын немесе өзге де мүліктік игіліктерін қайтаруы. Оның басты мақсаты - тараптарды мәміле жасалғанға дейінгі бастапқы жағдайына келтіру [27].","id":"lesson-10-paragraph-15"},{"text":"Егер мәміле жарамсыз деп танылса, әдетте екіжақты реституция қолданылады. Бұл жағдайда әр тарап өзіне берілген мүлікті немесе ақшаны кері қайтарады. Мысалы, азамат заң талаптарын сақтамай пәтер сатып алса, сот мәмілені жарамсыз деп таныған кезде пәтер сатушыға қайтарылады, ал сатып алушыға төленген ақша қайтарылады. Кейбір жағдайларда біржақты реституция қолданылады. Мұндай кезде кінәсіз тарап алған мүлкін сақтап қалады немесе қайтарып алады, ал заң бұзған тарап ешқандай өтем алмайды. Мысалы, егер бір адам екіншісін алдап ақша алса, сот шешімімен алданған адам өз ақшасын қайта алады, ал алаяққа ештеңе берілмейді. Ал егер тараптар заңсыз мәміле жасағанын біле тұра әрекет етсе, реституция қолданылмай, алынған мүлік мемлекет кірісіне алынуы мүмкін. Бұл заң бұзушылықтың алдын алу және қоғам мүддесін қорғау мақсатында жүзеге асырылады. Осылайша, реституция жарамсыз мәміленің негізгі құқықтық салдары болып табылады. Ол тараптардың мүліктік жағдайын қалпына келтіруге, әділеттілікті қамтамасыз етуге және заңсыз жолмен алынған пайдаға жол бермеуге бағытталған. Сондықтан жарамсыз мәміле мен реституция өзара тығыз байланысты және азаматтық құқықтағы маңызды институттардың бірі болып саналады.","html":"Егер мәміле жарамсыз деп танылса, әдетте екіжақты реституция қолданылады. Бұл жағдайда әр тарап өзіне берілген мүлікті немесе ақшаны кері қайтарады. Мысалы, азамат заң талаптарын сақтамай пәтер сатып алса, сот мәмілені жарамсыз деп таныған кезде пәтер сатушыға қайтарылады, ал сатып алушыға төленген ақша қайтарылады. Кейбір жағдайларда біржақты реституция қолданылады. Мұндай кезде кінәсіз тарап алған мүлкін сақтап қалады немесе қайтарып алады, ал заң бұзған тарап ешқандай өтем алмайды. Мысалы, егер бір адам екіншісін алдап ақша алса, сот шешімімен алданған адам өз ақшасын қайта алады, ал алаяққа ештеңе берілмейді. Ал егер тараптар заңсыз мәміле жасағанын біле тұра әрекет етсе, реституция қолданылмай, алынған мүлік мемлекет кірісіне алынуы мүмкін. Бұл заң бұзушылықтың алдын алу және қоғам мүддесін қорғау мақсатында жүзеге асырылады. Осылайша, реституция жарамсыз мәміленің негізгі құқықтық салдары болып табылады. Ол тараптардың мүліктік жағдайын қалпына келтіруге, әділеттілікті қамтамасыз етуге және заңсыз жолмен алынған пайдаға жол бермеуге бағытталған. Сондықтан жарамсыз мәміле мен реституция өзара тығыз байланысты және азаматтық құқықтағы маңызды институттардың бірі болып саналады.","id":"lesson-10-paragraph-16"},{"text":"Қазіргі қоғамда мәміле күнделікті өмірдің ажырамас бөлігіне айналды. Сондықтан әрбір азамат мәміле жасаудың құқықтық негіздерін білуі қажет. Бұл өз құқықтарын қорғауға, заң бұзушылықтардың алдын алуға және заңды қатынастар орнатуға мүмкіндік береді.","html":"Қазіргі қоғамда мәміле күнделікті өмірдің ажырамас бөлігіне айналды. Сондықтан әрбір азамат мәміле жасаудың құқықтық негіздерін білуі қажет. Бұл өз құқықтарын қорғауға, заң бұзушылықтардың алдын алуға және заңды қатынастар орнатуға мүмкіндік береді.","id":"lesson-10-paragraph-17"}],"words":798,"legacyAnchors":{"lesson-10-section-1":"lesson-10-paragraph-1","lesson-10-section-2":"lesson-10-paragraph-7","lesson-10-section-3":"lesson-10-paragraph-10","lesson-10-section-4":"lesson-10-paragraph-13","lesson-10-section-5":"lesson-10-paragraph-14"}},"11":{"title":"11-ТАҚЫРЫП. ӨКІЛДІК ЖӘНЕ СЕНІМХАТ","blocks":[{"text":"Қазіргі қоғамда азаматтар мен ұйымдар күнделікті өмірде әртүрлі құқықтық қатынастарға түседі. Олар мүліктік мәмілелер жасайды, шарттарға отырады, қызмет көрсетеді және түрлі заңды әрекеттерді жүзеге асырады. Алайда әрбір адам барлық құқықтық іс-әрекеттерді жеке өзі орындауға әрдайым мүмкіндік таба бермейді. Уақыттың жетіспеуі, денсаулық жағдайы, қашықтық немесе басқа да себептер адамның өз құқықтарын тікелей жүзеге асыруына кедергі келтіруі мүмкін. Осындай жағдайларда өкілдік пен сенімхат институттары қолданылады. Олар тұлғаның құқықтары мен мүдделерін басқа адам арқылы жүзеге асыруға мүмкіндік береді. Қазақстан Республикасының Азаматтық кодексінде өкілдік пен сенімхатқа қатысты арнайы нормалар бекітілген және олардың қолданылу тәртібі нақты реттелген.","html":"Қазіргі қоғамда азаматтар мен ұйымдар күнделікті өмірде әртүрлі құқықтық қатынастарға түседі. Олар мүліктік мәмілелер жасайды, шарттарға отырады, қызмет көрсетеді және түрлі заңды әрекеттерді жүзеге асырады. Алайда әрбір адам барлық құқықтық іс-әрекеттерді жеке өзі орындауға әрдайым мүмкіндік таба бермейді. Уақыттың жетіспеуі, денсаулық жағдайы, қашықтық немесе басқа да себептер адамның өз құқықтарын тікелей жүзеге асыруына кедергі келтіруі мүмкін. Осындай жағдайларда өкілдік пен сенімхат институттары қолданылады. Олар тұлғаның құқықтары мен мүдделерін басқа адам арқылы жүзеге асыруға мүмкіндік береді. Қазақстан Республикасының Азаматтық кодексінде өкілдік пен сенімхатқа қатысты арнайы нормалар бекітілген және олардың қолданылу тәртібі нақты реттелген.","id":"lesson-11-paragraph-1"},{"text":"Өкілдік пен сенімхат азаматтық айналымды жеңілдетуге, құқықтық қатынастардың тұрақтылығын қамтамасыз етуге және азаматтардың құқықтарын қорғауға бағытталған маңызды құқықтық құралдар болып табылады.","html":"Өкілдік пен сенімхат азаматтық айналымды жеңілдетуге, құқықтық қатынастардың тұрақтылығын қамтамасыз етуге және азаматтардың құқықтарын қорғауға бағытталған маңызды құқықтық құралдар болып табылады.","id":"lesson-11-paragraph-2"},{"text":"Қазақстан Республикасының Азаматтық кодексіне сәйкес, өкілдік деп бір тұлғаның басқа тұлғаның атынан және оның мүддесі үшін құқықтық әрекеттер жасауы танылады. Бұл жағдайда өкілдің жасаған әрекеттері тікелей өкілдік берушінің құқықтары мен міндеттерін туындатады, өзгертеді немесе тоқтатады. Өкіл өз атынан емес, өкілдік берушінің атынан әрекет етеді. Сондықтан оның құқықтық салдары өкілге емес, өкілдік берушіге қатысты туындайды. Мысалы, азамат өз пәтерін сатуға мүмкіндігі болмаған жағдайда, басқа тұлғаға осы әрекетті орындауға өкілеттік беруі мүмкін. Бұл жағдайда пәтерді сататын адам - өкіл, ал меншік иесі - өкілдік беруші болып табылады.","html":"Қазақстан Республикасының Азаматтық кодексіне сәйкес, өкілдік деп бір тұлғаның басқа тұлғаның атынан және оның мүддесі үшін құқықтық әрекеттер жасауы танылады. Бұл жағдайда өкілдің жасаған әрекеттері тікелей өкілдік берушінің құқықтары мен міндеттерін туындатады, өзгертеді немесе тоқтатады. Өкіл өз атынан емес, өкілдік берушінің атынан әрекет етеді. Сондықтан оның құқықтық салдары өкілге емес, өкілдік берушіге қатысты туындайды. Мысалы, азамат өз пәтерін сатуға мүмкіндігі болмаған жағдайда, басқа тұлғаға осы әрекетті орындауға өкілеттік беруі мүмкін. Бұл жағдайда пәтерді сататын адам - өкіл, ал меншік иесі - өкілдік беруші болып табылады.","id":"lesson-11-paragraph-3"},{"text":"Өкілдіктің негізгі белгілері мыналардан көрінеді: өкіл басқа тұлғаның атынан әрекет етеді, оның әрекеті құқықтық салдар туындатады, өкілеттік заңға немесе сенімхатқа негізделеді және өкіл өкілдік берушінің мүддесін қорғауға міндетті. Өкілдік азаматтардың құқықтарын тиімді жүзеге асыруына мүмкіндік беріп, азаматтық айналымның дамуына оң әсер етеді.","html":"Өкілдіктің негізгі белгілері мыналардан көрінеді: өкіл басқа тұлғаның атынан әрекет етеді, оның әрекеті құқықтық салдар туындатады, өкілеттік заңға немесе сенімхатқа негізделеді және өкіл өкілдік берушінің мүддесін қорғауға міндетті. Өкілдік азаматтардың құқықтарын тиімді жүзеге асыруына мүмкіндік беріп, азаматтық айналымның дамуына оң әсер етеді.","id":"lesson-11-paragraph-4"},{"text":"Өкілдік құқықтық негізіне және пайда болу жолына қарай төмендегідей бірнеше түрге бөлінеді:","html":"Өкілдік құқықтық негізіне және пайда болу жолына қарай төмендегідей бірнеше түрге бөлінеді:","id":"lesson-11-paragraph-5"},{"text":"Заңды өкілдік заңның тікелей нұсқауы бойынша пайда болады. Мұндай жағдайда арнайы сенімхат талап етілмейді. Заңды өкілдік көбінесе әрекетке қабілетсіз немесе қабілеті шектеулі тұлғалардың құқықтарын қорғауға бағытталған. Мысалы, ата-аналар кәмелетке толмаған балаларының заңды өкілі болып табылады. Қорғаншылар мен қамқоршылар да өз қамқорлығындағы адамдардың мүддесін заңды түрде қорғайды.","html":"Заңды өкілдік заңның тікелей нұсқауы бойынша пайда болады. Мұндай жағдайда арнайы сенімхат талап етілмейді. Заңды өкілдік көбінесе әрекетке қабілетсіз немесе қабілеті шектеулі тұлғалардың құқықтарын қорғауға бағытталған. Мысалы, ата-аналар кәмелетке толмаған балаларының заңды өкілі болып табылады. Қорғаншылар мен қамқоршылар да өз қамқорлығындағы адамдардың мүддесін заңды түрде қорғайды.","id":"lesson-11-paragraph-6"},{"text":"Шарттық өкілдік тараптардың өзара келісімі негізінде жүзеге асырылады. Ол сенімхат немесе азаматтық-құқықтық шарт арқылы рәсімделеді. Мысалы, адвокаттың клиентті қорғауы, агенттің кәсіпкердің атынан мәміле жасауы, делдалдың сауда келісімін ұйымдастыруы шарттық өкілдікке жатады. Бұл жағдайда өкіл мен өкілдік беруші арасында нақты құқықтық міндеттер белгіленеді.","html":"Шарттық өкілдік тараптардың өзара келісімі негізінде жүзеге асырылады. Ол сенімхат немесе азаматтық-құқықтық шарт арқылы рәсімделеді. Мысалы, адвокаттың клиентті қорғауы, агенттің кәсіпкердің атынан мәміле жасауы, делдалдың сауда келісімін ұйымдастыруы шарттық өкілдікке жатады. Бұл жағдайда өкіл мен өкілдік беруші арасында нақты құқықтық міндеттер белгіленеді.","id":"lesson-11-paragraph-7"},{"text":"Әкімшілік өкілдік ұйымдардың ішкі құрылымына байланысты пайда болады. Ұйым басшылары мен қызметкерлері өз лауазымдық өкілеттігі шегінде ұйым атынан әрекет етеді. Мысалы, директордың келісімшарттарға қол қоюы немесе бөлім басшысының ресми құжаттарды рәсімдеуі әкімшілік өкілдікке жатады.","html":"Әкімшілік өкілдік ұйымдардың ішкі құрылымына байланысты пайда болады. Ұйым басшылары мен қызметкерлері өз лауазымдық өкілеттігі шегінде ұйым атынан әрекет етеді. Мысалы, директордың келісімшарттарға қол қоюы немесе бөлім басшысының ресми құжаттарды рәсімдеуі әкімшілік өкілдікке жатады.","id":"lesson-11-paragraph-8"},{"text":"Өкіл берілген өкілеттік шегінде әрекет етуге, қажетті ақпарат алуға және шығындарын өтеуді талап етуге құқылы. Сонымен қатар ол өз міндеттерін адал орындауға, өкілеттікті асыра пайдаланбауға, берілген тапсырма бойынша есеп беруге міндетті. Егер өкіл өз өкілеттігін теріс пайдаланса, келтірілген зиян үшін жауап береді [28].","html":"Өкіл берілген өкілеттік шегінде әрекет етуге, қажетті ақпарат алуға және шығындарын өтеуді талап етуге құқылы. Сонымен қатар ол өз міндеттерін адал орындауға, өкілеттікті асыра пайдаланбауға, берілген тапсырма бойынша есеп беруге міндетті. Егер өкіл өз өкілеттігін теріс пайдаланса, келтірілген зиян үшін жауап береді [28].","id":"lesson-11-paragraph-9"},{"text":"Өкілдік пен сенімхат азаматтық құқықтың маңызды институттарының бірі болып табылады. Олар азаматтар мен ұйымдарға өз құқықтарын басқа тұлғалар арқылы жүзеге асыруға мүмкіндік береді. Бұл институттар азаматтық айналымды жеңілдетіп, құқықтық қатынастардың тұрақтылығын қамтамасыз етеді. Сенімхат өкілдің өкілеттігін растайтын негізгі құжат ретінде ерекше маңызға ие. Ол заң талаптарына сай рәсімделмеген жағдайда, жасалған мәміле жарамсыз деп танылуы мүмкін. Сондықтан сенімхат беру кезінде заң нормаларын қатаң сақтау қажет.","html":"Өкілдік пен сенімхат азаматтық құқықтың маңызды институттарының бірі болып табылады. Олар азаматтар мен ұйымдарға өз құқықтарын басқа тұлғалар арқылы жүзеге асыруға мүмкіндік береді. Бұл институттар азаматтық айналымды жеңілдетіп, құқықтық қатынастардың тұрақтылығын қамтамасыз етеді. Сенімхат өкілдің өкілеттігін растайтын негізгі құжат ретінде ерекше маңызға ие. Ол заң талаптарына сай рәсімделмеген жағдайда, жасалған мәміле жарамсыз деп танылуы мүмкін. Сондықтан сенімхат беру кезінде заң нормаларын қатаң сақтау қажет.","id":"lesson-11-paragraph-10"},{"text":"Сенімхат - бір тұлғаның басқа тұлғаға өзінің атынан белгілі бір құқықтық әрекеттер жасауға беретін жазбаша өкілеттігі. Сенімхат өкілдің өкілеттігін растайтын негізгі құжат болып табылады. Ол арқылы өкілдің қандай әрекеттерді орындауға құқығы бар екені анықталады. Сенімхатсыз көптеген құқықтық әрекеттерді жүзеге асыру мүмкін емес. Мысалы, банктен ақша алу, мүлікті сату, көлікті тіркеу, сотта өкіл болу сияқты әрекеттер көбінесе сенімхат арқылы жүзеге асырылады.","html":"Сенімхат - бір тұлғаның басқа тұлғаға өзінің атынан белгілі бір құқықтық әрекеттер жасауға беретін жазбаша өкілеттігі. Сенімхат өкілдің өкілеттігін растайтын негізгі құжат болып табылады. Ол арқылы өкілдің қандай әрекеттерді орындауға құқығы бар екені анықталады. Сенімхатсыз көптеген құқықтық әрекеттерді жүзеге асыру мүмкін емес. Мысалы, банктен ақша алу, мүлікті сату, көлікті тіркеу, сотта өкіл болу сияқты әрекеттер көбінесе сенімхат арқылы жүзеге асырылады.","id":"lesson-11-paragraph-11"},{"text":"Сенімхат міндетті түрде жазбаша нысанда жасалады. Кейбір жағдайларда ол нотариус арқылы куәландырылуы тиіс. Нотариалды куәландыру жылжымайтын мүлікке қатысты мәмілелерде, мемлекеттік тіркеуге жататын әрекеттерде және мұрагерлік мәселелерде талап етіледі.","html":"Сенімхат міндетті түрде жазбаша нысанда жасалады. Кейбір жағдайларда ол нотариус арқылы куәландырылуы тиіс. Нотариалды куәландыру жылжымайтын мүлікке қатысты мәмілелерде, мемлекеттік тіркеуге жататын әрекеттерде және мұрагерлік мәселелерде талап етіледі.","id":"lesson-11-paragraph-12"},{"text":"Сенімхатта мынадай міндетті мәліметтер көрсетілуі қажет: берілген күні, сенімхат беруші мен өкілдің аты-жөні, өкілеттіктің көлемі, мерзімі және қолы. Егер берілген күні көрсетілмесе, сенімхат жарамсыз деп танылады.","html":"Сенімхатта мынадай міндетті мәліметтер көрсетілуі қажет: берілген күні, сенімхат беруші мен өкілдің аты-жөні, өкілеттіктің көлемі, мерзімі және қолы. Егер берілген күні көрсетілмесе, сенімхат жарамсыз деп танылады.","id":"lesson-11-paragraph-13"},{"text":"Сенімхат мазмұнына қарай бірнеше түрге бөлінеді. Бір реттік сенімхат белгілі бір ғана әрекет жасауға беріледі. Арнайы сенімхат белгілі бір мерзім ішінде бірнеше ұқсас әрекет жасауға мүмкіндік береді. Ал жалпы сенімхат өкілге кең көлемде өкілеттік береді және мүлікті басқаруға немесе істерді толық жүргізуге құқық береді.","html":"Сенімхат мазмұнына қарай бірнеше түрге бөлінеді. Бір реттік сенімхат белгілі бір ғана әрекет жасауға беріледі. Арнайы сенімхат белгілі бір мерзім ішінде бірнеше ұқсас әрекет жасауға мүмкіндік береді. Ал жалпы сенімхат өкілге кең көлемде өкілеттік береді және мүлікті басқаруға немесе істерді толық жүргізуге құқық береді.","id":"lesson-11-paragraph-14"},{"text":"Сенімхатта оның қолданылу мерзімі көрсетілуі мүмкін. Егер мерзім көрсетілмесе, ол бір жылға жарамды болып есептеледі. Заң бойынша сенімхаттың ең ұзақ мерзімі үш жылдан аспауы тиіс.","html":"Сенімхатта оның қолданылу мерзімі көрсетілуі мүмкін. Егер мерзім көрсетілмесе, ол бір жылға жарамды болып есептеледі. Заң бойынша сенімхаттың ең ұзақ мерзімі үш жылдан аспауы тиіс.","id":"lesson-11-paragraph-15"},{"text":"Сенімхат белгілі бір мерзімге немесе белгілі бір мақсатты орындау үшін беріледі. Алайда кейбір жағдайларда ол өзінің заңды күшін жояды және тоқтатылады. Қазақстан Республикасының Азаматтық кодексіне сәйкес, сенімхаттың тоқтатылуы өкіл мен сенімхат беруші арасындағы құқықтық қатынастардың аяқталғанын білдіреді. Сенімхат мына жағдайларда тоқтатылады: мерзімінің аяқталуы, сенімхат берушінің немесе өкілдің бас тартуы, тараптардың қайтыс болуы, әрекетке қабілетсіз деп танылуы. Сенімхат тоқтатылған кезде өкіл барлық алынған құжаттарды қайтаруға міндетті.","html":"Сенімхат белгілі бір мерзімге немесе белгілі бір мақсатты орындау үшін беріледі. Алайда кейбір жағдайларда ол өзінің заңды күшін жояды және тоқтатылады. Қазақстан Республикасының Азаматтық кодексіне сәйкес, сенімхаттың тоқтатылуы өкіл мен сенімхат беруші арасындағы құқықтық қатынастардың аяқталғанын білдіреді. Сенімхат мына жағдайларда тоқтатылады: мерзімінің аяқталуы, сенімхат берушінің немесе өкілдің бас тартуы, тараптардың қайтыс болуы, әрекетке қабілетсіз деп танылуы. Сенімхат тоқтатылған кезде өкіл барлық алынған құжаттарды қайтаруға міндетті.","id":"lesson-11-paragraph-16"},{"text":"Сенімхат тоқтатылған сәттен бастап өкілдің өкілдік ету құқығы жойылады. Яғни ол сенімхат берушінің атынан қандай да бір мәміле жасауға немесе құқықтық әрекеттер орындауға құқылы болмайды. Егер өкіл сенімхат тоқтатылғаннан кейін әрекет жасаса, мұндай әрекеттер заңсыз болып есептеледі және құқықтық салдар туындатпайды. Сенімхат тоқтатылған жағдайда өкіл сенімхат берушіге барлық алынған құжаттарды, мүлікті және пайдаланылмаған өкілеттіктерді қайтаруға міндетті. Сонымен қатар, өкіл өзінің атқарған әрекеттері туралы есеп беруге тиіс. Бұл сенімхат берушінің мүддесін қорғау мақсатында жүзеге асырылады.","html":"Сенімхат тоқтатылған сәттен бастап өкілдің өкілдік ету құқығы жойылады. Яғни ол сенімхат берушінің атынан қандай да бір мәміле жасауға немесе құқықтық әрекеттер орындауға құқылы болмайды. Егер өкіл сенімхат тоқтатылғаннан кейін әрекет жасаса, мұндай әрекеттер заңсыз болып есептеледі және құқықтық салдар туындатпайды. Сенімхат тоқтатылған жағдайда өкіл сенімхат берушіге барлық алынған құжаттарды, мүлікті және пайдаланылмаған өкілеттіктерді қайтаруға міндетті. Сонымен қатар, өкіл өзінің атқарған әрекеттері туралы есеп беруге тиіс. Бұл сенімхат берушінің мүддесін қорғау мақсатында жүзеге асырылады.","id":"lesson-11-paragraph-17"},{"text":"Егер сенімхат өкілдің кінәсінен немесе заңсыз әрекеттерінің салдарынан тоқтатылса, өкіл келтірілген зиянды өтеуге міндетті болады. Ал егер сенімхат беруші өз еркімен бас тартса, өкіл бұрын жасалған заңды әрекеттері үшін жауап бермейді.","html":"Егер сенімхат өкілдің кінәсінен немесе заңсыз әрекеттерінің салдарынан тоқтатылса, өкіл келтірілген зиянды өтеуге міндетті болады. Ал егер сенімхат беруші өз еркімен бас тартса, өкіл бұрын жасалған заңды әрекеттері үшін жауап бермейді.","id":"lesson-11-paragraph-18"},{"text":"Сенімхат тоқтатылғаннан кейін үшінші тұлғаларға бұл туралы хабарлау маңызды. Егер үшінші тұлғалар сенімхаттың тоқтатылғанын білмесе және адал түрде мәміле жасаса, кейбір жағдайларда олардың құқықтары қорғалуы мүмкін. Сондықтан сенімхат беруші сенімхаттың тоқтатылғаны туралы мүдделі тұлғаларды уақтылы хабардар етуі қажет.","html":"Сенімхат тоқтатылғаннан кейін үшінші тұлғаларға бұл туралы хабарлау маңызды. Егер үшінші тұлғалар сенімхаттың тоқтатылғанын білмесе және адал түрде мәміле жасаса, кейбір жағдайларда олардың құқықтары қорғалуы мүмкін. Сондықтан сенімхат беруші сенімхаттың тоқтатылғаны туралы мүдделі тұлғаларды уақтылы хабардар етуі қажет.","id":"lesson-11-paragraph-19"},{"text":"Сенімхаттың тоқтатылуы өкілдің өкілеттігін толық тоқтатуға әкеледі және тараптар арасында жаңа құқықтық қатынастардың туындауына жол бермейді. Бұл азаматтық құқықтағы тәртіпті сақтауға және заңдылықты қамтамасыз етуге бағытталған маңызды құқықтық механизм болып табылады [29].","html":"Сенімхаттың тоқтатылуы өкілдің өкілеттігін толық тоқтатуға әкеледі және тараптар арасында жаңа құқықтық қатынастардың туындауына жол бермейді. Бұл азаматтық құқықтағы тәртіпті сақтауға және заңдылықты қамтамасыз етуге бағытталған маңызды құқықтық механизм болып табылады [29].","id":"lesson-11-paragraph-20"},{"text":"Қазіргі қоғамда өкілдік пен сенімхаттың рөлі артып келеді. Әрбір азамат осы институттардың мазмұнын жақсы меңгеріп, оларды дұрыс пайдалана білуі керек. Бұл олардың өз құқықтарын қорғауға, заңды қатынастарды тиімді жүргізуге және құқықтық мәдениетті арттыруға мүмкіндік береді.","html":"Қазіргі қоғамда өкілдік пен сенімхаттың рөлі артып келеді. Әрбір азамат осы институттардың мазмұнын жақсы меңгеріп, оларды дұрыс пайдалана білуі керек. Бұл олардың өз құқықтарын қорғауға, заңды қатынастарды тиімді жүргізуге және құқықтық мәдениетті арттыруға мүмкіндік береді.","id":"lesson-11-paragraph-21"}],"words":939,"legacyAnchors":{"lesson-11-section-1":"lesson-11-paragraph-1","lesson-11-section-2":"lesson-11-paragraph-3","lesson-11-section-3":"lesson-11-paragraph-5","lesson-11-section-4":"lesson-11-paragraph-9","lesson-11-section-5":"lesson-11-paragraph-11","lesson-11-section-6":"lesson-11-paragraph-14","lesson-11-section-7":"lesson-11-paragraph-16"}},"12":{"title":"12-ТАҚЫРЫП. АЗАМАТТЫҚ ҚҰҚЫҚТАҒЫ МЕРЗІМДЕР","blocks":[{"text":"Азаматтық құқықтағы мерзімдер - азаматтық құқықтық қатынастарда құқықтар мен міндеттердің туындауы, өзгеруі және тоқтатылуы байланысты болатын уақыт аралықтары немесе нақты күндер. Уақыт факторы азаматтық айналымның ажырамас элементі болып табылады, себебі кез келген құқықтық әрекет белгілі бір мерзім шегінде жүзеге асырылады.","html":"Азаматтық құқықтағы мерзімдер - азаматтық құқықтық қатынастарда құқықтар мен міндеттердің туындауы, өзгеруі және тоқтатылуы байланысты болатын уақыт аралықтары немесе нақты күндер. Уақыт факторы азаматтық айналымның ажырамас элементі болып табылады, себебі кез келген құқықтық әрекет белгілі бір мерзім шегінде жүзеге асырылады.","id":"lesson-12-paragraph-1"},{"text":"Азаматтық құқықтық қатынастардың басым бөлігі уақыт өлшемімен тікелей байланысты. Мәміленің жасалуы, шарттың әрекет ету кезеңі, міндеттеменің орындалуы, құқықты қорғау мүмкіндігі - барлығы да заңмен немесе шартпен белгіленген мерзімдер арқылы айқындалады. Осы тұрғыдан алғанда мерзімдер азаматтық құқықтың маңызды институттарының бірі болып табылады.","html":"Азаматтық құқықтық қатынастардың басым бөлігі уақыт өлшемімен тікелей байланысты. Мәміленің жасалуы, шарттың әрекет ету кезеңі, міндеттеменің орындалуы, құқықты қорғау мүмкіндігі - барлығы да заңмен немесе шартпен белгіленген мерзімдер арқылы айқындалады. Осы тұрғыдан алғанда мерзімдер азаматтық құқықтың маңызды институттарының бірі болып табылады.","id":"lesson-12-paragraph-2"},{"text":"Қазақстан Республикасының Азаматтық кодексінде мерзімдерге арналған арнайы нормалар көзделген. Бұл нормалар мерзімдердің түрлерін, оларды белгілеу тәсілдерін, есептелу тәртібін, тоқтатылуын, үзілуін және құқықтық салдарын реттейді. Мерзімдерді құқықтық реттеу азаматтық айналымда тұрақтылықты, айқындықты және қатысушылардың сенімділігін қамтамасыз етеді.","html":"Қазақстан Республикасының Азаматтық кодексінде мерзімдерге арналған арнайы нормалар көзделген. Бұл нормалар мерзімдердің түрлерін, оларды белгілеу тәсілдерін, есептелу тәртібін, тоқтатылуын, үзілуін және құқықтық салдарын реттейді. Мерзімдерді құқықтық реттеу азаматтық айналымда тұрақтылықты, айқындықты және қатысушылардың сенімділігін қамтамасыз етеді.","id":"lesson-12-paragraph-3"},{"text":"Мерзімдердің азаматтық құқықтағы маңызы бірнеше қырынан көрінеді. Біріншіден, олар азаматтық айналымды ретке келтіреді. Екіншіден, құқықтар мен міндеттердің уақытында орындалуына ықпал етеді. Үшіншіден, шарттық тәртіпті нығайтады және тараптардың жауапкершілігін арттырады. Төртіншіден, даулардың алдын алуға мүмкіндік береді. Соңында, құқықтық тұрақтылық пен құқықтық анықтылықты қалыптастырады.","html":"Мерзімдердің азаматтық құқықтағы маңызы бірнеше қырынан көрінеді. Біріншіден, олар азаматтық айналымды ретке келтіреді. Екіншіден, құқықтар мен міндеттердің уақытында орындалуына ықпал етеді. Үшіншіден, шарттық тәртіпті нығайтады және тараптардың жауапкершілігін арттырады. Төртіншіден, даулардың алдын алуға мүмкіндік береді. Соңында, құқықтық тұрақтылық пен құқықтық анықтылықты қалыптастырады.","id":"lesson-12-paragraph-4"},{"text":"Осылайша, мерзімдер азаматтық құқықтық қатынастардың тиімді және үйлесімді дамуына жағдай жасайтын маңызды құқықтық құрал болып табылады.","html":"Осылайша, мерзімдер азаматтық құқықтық қатынастардың тиімді және үйлесімді дамуына жағдай жасайтын маңызды құқықтық құрал болып табылады.","id":"lesson-12-paragraph-5"},{"text":"Азаматтық құқықтағы мерзімдердің түрлері және есептелуі. Азаматтық құқықтағы мерзімдер бірнеше негіздер бойынша жіктеледі. Белгілену тәсіліне қарай мерзімдер күнтізбелік күнмен, уақыт кезеңімен немесе белгілі бір оқиғамен байланыстырылып белгіленуі мүмкін.","html":"Азаматтық құқықтағы мерзімдердің түрлері және есептелуі. Азаматтық құқықтағы мерзімдер бірнеше негіздер бойынша жіктеледі. Белгілену тәсіліне қарай мерзімдер күнтізбелік күнмен, уақыт кезеңімен немесе белгілі бір оқиғамен байланыстырылып белгіленуі мүмкін.","id":"lesson-12-paragraph-6"},{"text":"Күнтізбелік күнмен белгіленетін мерзімдер нақты күнді көрсетеді. Мысалы, «2026 жылғы 1 қаңтарға дейін» немесе «2027 жылғы 10 наурызға дейін» деген сияқты нақты даталар көрсетіледі. Мұндай жағдайда мерзім дәл сол күнге дейін қолданылады.","html":"Күнтізбелік күнмен белгіленетін мерзімдер нақты күнді көрсетеді. Мысалы, «2026 жылғы 1 қаңтарға дейін» немесе «2027 жылғы 10 наурызға дейін» деген сияқты нақты даталар көрсетіледі. Мұндай жағдайда мерзім дәл сол күнге дейін қолданылады.","id":"lesson-12-paragraph-7"},{"text":"Уақыт кезеңімен белгіленетін мерзімдер белгілі бір уақыт аралығымен өлшенеді. Мысалы, «10 күн ішінде», «6 ай мерзімге», «2 жылға» деген тұжырым осы санатқа жатады. Бұл жағдайда мерзім белгілі бір уақыт бірлігімен айқындалады.","html":"Уақыт кезеңімен белгіленетін мерзімдер белгілі бір уақыт аралығымен өлшенеді. Мысалы, «10 күн ішінде», «6 ай мерзімге», «2 жылға» деген тұжырым осы санатқа жатады. Бұл жағдайда мерзім белгілі бір уақыт бірлігімен айқындалады.","id":"lesson-12-paragraph-8"},{"text":"Оқиғамен байланысты мерзімдер белгілі бір заңды немесе нақты оқиғаның болуына тәуелді болады. Мысалы, «жүк тапсырылған күннен бастап», «тіркеу аяқталғаннан кейін» деген жағдайларда мерзім оқиғаның басталуына байланысты есептеледі.","html":"Оқиғамен байланысты мерзімдер белгілі бір заңды немесе нақты оқиғаның болуына тәуелді болады. Мысалы, «жүк тапсырылған күннен бастап», «тіркеу аяқталғаннан кейін» деген жағдайларда мерзім оқиғаның басталуына байланысты есептеледі.","id":"lesson-12-paragraph-9"},{"text":"Құқықтық мағынасына қарай мерзімдер құқықты жүзеге асыру мерзімдері, міндеттемені орындау мерзімдері және қорғау мерзімдері болып бөлінеді.","html":"Құқықтық мағынасына қарай мерзімдер құқықты жүзеге асыру мерзімдері, міндеттемені орындау мерзімдері және қорғау мерзімдері болып бөлінеді.","id":"lesson-12-paragraph-10"},{"text":"Құқықты жүзеге асыру мерзімдері - тұлғаның өз субъективтік құқығын пайдалануына берілген уақыт аралығы. Мысалы, мұраны қабылдау мерзімі немесе кепілдік мерзімі.","html":"Құқықты жүзеге асыру мерзімдері - тұлғаның өз субъективтік құқығын пайдалануына берілген уақыт аралығы. Мысалы, мұраны қабылдау мерзімі немесе кепілдік мерзімі.","id":"lesson-12-paragraph-11"},{"text":"Міндеттемені орындау мерзімдері - борышкердің өз міндетін орындауға тиісті уақыты. Бұған қарызды қайтару, жұмысты аяқтау немесе қызмет көрсету мерзімдері жатады.","html":"Міндеттемені орындау мерзімдері - борышкердің өз міндетін орындауға тиісті уақыты. Бұған қарызды қайтару, жұмысты аяқтау немесе қызмет көрсету мерзімдері жатады.","id":"lesson-12-paragraph-12"},{"text":"Құқықты қорғау мерзімдері - бұзылған құқықты қорғауға арналған мерзімдер. Олардың ішіндегі ең маңыздысы - талап қою мерзімі.","html":"Құқықты қорғау мерзімдері - бұзылған құқықты қорғауға арналған мерзімдер. Олардың ішіндегі ең маңыздысы - талап қою мерзімі.","id":"lesson-12-paragraph-13"},{"text":"Мерзімдерді есептеу тәртібі Қазақстан Республикасының Азаматтық кодексіндегі мерзімдерді есептеудің нақты ережелері бойынша жүзеге асырылады. Күнмен есептелетін мерзім оқиға болған күннен кейінгі келесі күннен басталады. Бұл қағида мерзімді есептеуде әділдік пен айқындықты қамтамасыз етеді. Аймен есептелетін мерзім соңғы айдың тиісті күнімен аяқталады. Егер соңғы айда сәйкес күн болмаса, мерзім сол айдың соңғы күні аяқталады. Жылмен есептелетін мерзім тиісті ай мен күнге сәйкес аяқталады.","html":"Мерзімдерді есептеу тәртібі Қазақстан Республикасының Азаматтық кодексіндегі мерзімдерді есептеудің нақты ережелері бойынша жүзеге асырылады. Күнмен есептелетін мерзім оқиға болған күннен кейінгі келесі күннен басталады. Бұл қағида мерзімді есептеуде әділдік пен айқындықты қамтамасыз етеді. Аймен есептелетін мерзім соңғы айдың тиісті күнімен аяқталады. Егер соңғы айда сәйкес күн болмаса, мерзім сол айдың соңғы күні аяқталады. Жылмен есептелетін мерзім тиісті ай мен күнге сәйкес аяқталады.","id":"lesson-12-paragraph-14"},{"text":"Егер мерзімнің соңғы күні демалыс немесе мереке күніне сәйкес келсе, онда мерзім келесі жұмыс күні аяқталады. Бұл ереже тұлғалардың құқықтарын жүзеге асыру мүмкіндігін шектемеу мақсатында енгізілген.","html":"Егер мерзімнің соңғы күні демалыс немесе мереке күніне сәйкес келсе, онда мерзім келесі жұмыс күні аяқталады. Бұл ереже тұлғалардың құқықтарын жүзеге асыру мүмкіндігін шектемеу мақсатында енгізілген.","id":"lesson-12-paragraph-15"},{"text":"Мерзімдерді есептеудің бірыңғай тәртібі құқық қолдану тәжірибесінде біркелкілікті қамтамасыз етеді және даулардың алдын алады.","html":"Мерзімдерді есептеудің бірыңғай тәртібі құқық қолдану тәжірибесінде біркелкілікті қамтамасыз етеді және даулардың алдын алады.","id":"lesson-12-paragraph-16"},{"text":"Талап қою мерзімі - тұлғаның бұзылған немесе даулы азаматтық құқығын сот арқылы қорғау үшін заңмен белгіленген уақыт аралығы. Бұл институттың негізгі мақсаты - азаматтық айналымдағы тұрақтылықты қамтамасыз ету, дауларды уақытылы шешу және ескі талаптардың негізсіз қойылуына жол бермеу. Уақыт өткен сайын дәлелдемелер жойылуы, куәлардың есінде мән-жайлардың көмескіленуі мүмкін. Сондықтан талап қою мерзімі құқықтық сенімділікті арттыру құралы ретінде қызмет етеді [30].","html":"Талап қою мерзімі - тұлғаның бұзылған немесе даулы азаматтық құқығын сот арқылы қорғау үшін заңмен белгіленген уақыт аралығы. Бұл институттың негізгі мақсаты - азаматтық айналымдағы тұрақтылықты қамтамасыз ету, дауларды уақытылы шешу және ескі талаптардың негізсіз қойылуына жол бермеу. Уақыт өткен сайын дәлелдемелер жойылуы, куәлардың есінде мән-жайлардың көмескіленуі мүмкін. Сондықтан талап қою мерзімі құқықтық сенімділікті арттыру құралы ретінде қызмет етеді [30].","id":"lesson-12-paragraph-17"},{"text":"Талап қою мерзімі құқықтың өзін жоймайды, бірақ оны сот арқылы қорғау мүмкіндігін шектейді. Бұл - оның басты ерекшелігі.","html":"Талап қою мерзімі құқықтың өзін жоймайды, бірақ оны сот арқылы қорғау мүмкіндігін шектейді. Бұл - оның басты ерекшелігі.","id":"lesson-12-paragraph-18"},{"text":"Қазақстан Республикасының Азаматтық кодексіне сәйкес талап қою мерзімдері жалпы және арнайы болып бөлінеді [31].","html":"Қазақстан Республикасының Азаматтық кодексіне сәйкес талап қою мерзімдері жалпы және арнайы болып бөлінеді [31].","id":"lesson-12-paragraph-19"},{"text":"Жалпы талап қою мерзімі - үш жыл. Егер заңда нақты қатынасқа қатысты арнайы мерзім белгіленбесе, үш жылдық мерзім қолданылады. Бұл мерзім, мысалы, қарызды өндіріп алу немесе шартты бұзу туралы талаптарға қолданылады. Арнайы талап қою мерзімдері жекелеген құқықтық қатынастар үшін белгіленеді. Мысалы, тасымалдау шарты, сақтандыру қатынастары немесе тауар сапасына байланысты даулар бойынша қысқартылған мерзімдер қарастырылуы мүмкін. Арнайы мерзімдер жалпы мерзімге қарағанда басым қолданылады.","html":"Жалпы талап қою мерзімі - үш жыл. Егер заңда нақты қатынасқа қатысты арнайы мерзім белгіленбесе, үш жылдық мерзім қолданылады. Бұл мерзім, мысалы, қарызды өндіріп алу немесе шартты бұзу туралы талаптарға қолданылады. Арнайы талап қою мерзімдері жекелеген құқықтық қатынастар үшін белгіленеді. Мысалы, тасымалдау шарты, сақтандыру қатынастары немесе тауар сапасына байланысты даулар бойынша қысқартылған мерзімдер қарастырылуы мүмкін. Арнайы мерзімдер жалпы мерзімге қарағанда басым қолданылады.","id":"lesson-12-paragraph-20"},{"text":"Талап қою мерзімі тұлға өз құқығының бұзылғанын білген немесе білуге тиіс болған күннен бастап есептеледі. Бұл қағида субъективтік элементті ескереді және азаматтың құқықтарын әділ қорғауға бағытталған. Мысалы, егер азамат өзінің мүлкі заңсыз иеленілгенін бірнеше жылдан кейін ғана анықтаса, мерзім сол анықтаған сәттен бастап есептеледі.","html":"Талап қою мерзімі тұлға өз құқығының бұзылғанын білген немесе білуге тиіс болған күннен бастап есептеледі. Бұл қағида субъективтік элементті ескереді және азаматтың құқықтарын әділ қорғауға бағытталған. Мысалы, егер азамат өзінің мүлкі заңсыз иеленілгенін бірнеше жылдан кейін ғана анықтаса, мерзім сол анықтаған сәттен бастап есептеледі.","id":"lesson-12-paragraph-21"},{"text":"Талап қою мерзімі белгілі бір жағдайларда тоқтатыла немесе үзіле алады.","html":"Талап қою мерзімі белгілі бір жағдайларда тоқтатыла немесе үзіле алады.","id":"lesson-12-paragraph-22"},{"text":"Тоқтатылуы - мерзімнің уақытша тоқтай тұруы. Бұған төтенше жағдайлар, әскери қызмет, талап қою мүмкіндігінің объективті түрде болмауы сияқты мән-жайлар жатады. Тоқтату негіздері жойылғаннан кейін мерзім жалғасады. Үзілуі - мерзімнің қайтадан жаңадан басталуы. Талап сотқа берілген кезде немесе борышкер өз міндетін мойындаған жағдайда мерзім үзіледі. Үзілгеннен кейін мерзім толық көлемде қайта есептеле бастайды.","html":"Тоқтатылуы - мерзімнің уақытша тоқтай тұруы. Бұған төтенше жағдайлар, әскери қызмет, талап қою мүмкіндігінің объективті түрде болмауы сияқты мән-жайлар жатады. Тоқтату негіздері жойылғаннан кейін мерзім жалғасады. Үзілуі - мерзімнің қайтадан жаңадан басталуы. Талап сотқа берілген кезде немесе борышкер өз міндетін мойындаған жағдайда мерзім үзіледі. Үзілгеннен кейін мерзім толық көлемде қайта есептеле бастайды.","id":"lesson-12-paragraph-23"},{"text":"Талап қою мерзімінің өтуінің құқықтық салдары көп. Талап қою мерзімінің өтуі құқықтың өзін тоқтатпағанымен, оны сот арқылы қорғау мүмкіндігін шектейді. Сонымен қатар, сот талап қою мерзімін өз бастамасымен қолданбайды, ол тек жауапкердің өтініші бойынша ескеріледі. Яғни, егер жауапкер мерзімнің өтіп кеткенін көрсетпесе, сот істі мәні бойынша қарауы мүмкін. Мерзім өтіп кеткен жағдайда талап қанағаттандырылмауы ықтимал. Алайда егер борышкер міндетін ерікті түрде орындаса, ол орындалғанды кері талап ете алмайды.","html":"Талап қою мерзімінің өтуінің құқықтық салдары көп. Талап қою мерзімінің өтуі құқықтың өзін тоқтатпағанымен, оны сот арқылы қорғау мүмкіндігін шектейді. Сонымен қатар, сот талап қою мерзімін өз бастамасымен қолданбайды, ол тек жауапкердің өтініші бойынша ескеріледі. Яғни, егер жауапкер мерзімнің өтіп кеткенін көрсетпесе, сот істі мәні бойынша қарауы мүмкін. Мерзім өтіп кеткен жағдайда талап қанағаттандырылмауы ықтимал. Алайда егер борышкер міндетін ерікті түрде орындаса, ол орындалғанды кері талап ете алмайды.","id":"lesson-12-paragraph-24"},{"text":"Сонымен азаматтық құқықтағы мерзімдер - құқықтық реттеудің маңызды элементі. Олар құқықтар мен міндеттердің уақытында жүзеге асырылуын қамтамасыз етіп, азаматтық айналымның тұрақтылығын нығайтады.","html":"Сонымен азаматтық құқықтағы мерзімдер - құқықтық реттеудің маңызды элементі. Олар құқықтар мен міндеттердің уақытында жүзеге асырылуын қамтамасыз етіп, азаматтық айналымның тұрақтылығын нығайтады.","id":"lesson-12-paragraph-25"},{"text":"Талап қою мерзімі азаматтық құқықтық қатынастардың уақыт шегінде қорғалуын қамтамасыз ететін негізгі институт болып табылады. Ол құқықтық анықтылықты қалыптастырады, тараптардың жауапкершілігін арттырады және азаматтық айналымдағы сенімділікті күшейтеді.","html":"Талап қою мерзімі азаматтық құқықтық қатынастардың уақыт шегінде қорғалуын қамтамасыз ететін негізгі институт болып табылады. Ол құқықтық анықтылықты қалыптастырады, тараптардың жауапкершілігін арттырады және азаматтық айналымдағы сенімділікті күшейтеді.","id":"lesson-12-paragraph-26"},{"text":"Сондықтан азаматтық құқық субъектілері мерзімдердің ұғымын, түрлерін, есептелу тәртібін және құқықтық салдарын терең меңгеруі тиіс. Бұл құқықтарды тиімді қорғаудың және заңды мүдделерді сақтаудың негізгі шарты болып табылады.","html":"Сондықтан азаматтық құқық субъектілері мерзімдердің ұғымын, түрлерін, есептелу тәртібін және құқықтық салдарын терең меңгеруі тиіс. Бұл құқықтарды тиімді қорғаудың және заңды мүдделерді сақтаудың негізгі шарты болып табылады.","id":"lesson-12-paragraph-27"}],"words":872,"legacyAnchors":{"lesson-12-section-1":"lesson-12-paragraph-1","lesson-12-section-2":"lesson-12-paragraph-6","lesson-12-section-3":"lesson-12-paragraph-14","lesson-12-section-4":"lesson-12-paragraph-17","lesson-12-section-5":"lesson-12-paragraph-22"}},"13":{"title":"13-ТАҚЫРЫП. МЕНШІК ҚҰҚЫҒЫ ТУРАЛЫ ЖАЛПЫ ЕРЕЖЕЛЕР","blocks":[{"text":"Меншік құқығы – азаматтық құқықтың негізгі институттарының бірі болып табылады. Ол тұлғаның мүлікті иелену, пайдалану және оған билік ету мүмкіндігін заң жүзінде бекітеді. Қоғамның экономикалық дамуы, нарықтық қатынастардың қалыптасуы мен тұрақты қызмет етуі тікелей меншік қатынастарының дұрыс реттелуіне байланысты [32].","html":"Меншік құқығы – азаматтық құқықтың негізгі институттарының бірі болып табылады. Ол тұлғаның мүлікті иелену, пайдалану және оған билік ету мүмкіндігін заң жүзінде бекітеді. Қоғамның экономикалық дамуы, нарықтық қатынастардың қалыптасуы мен тұрақты қызмет етуі тікелей меншік қатынастарының дұрыс реттелуіне байланысты [32].","id":"lesson-13-paragraph-1"},{"text":"Меншік қатынастары адамзат қоғамымен бірге қалыптасты. Алғашқы қауымдық құрылыста мүлікке ұжымдық меншік басым болды. Жер, еңбек құралдары, өнімдер ортақ пайдаланылды. Құл иеленушілік дәуірде жеке меншік институты қалыптаса бастады. Мүлікпен қатар адамдардың өзі де меншік объектісіне айналды. Феодалдық қоғамда жерге меншік негізгі рөл атқарды. Жер феодалдарға тиесілі болды, ал шаруалар болса оны пайдаланушы ретінде ғана қызмет етті. Капиталистік қоғамда жеке меншік басты экономикалық негізге айналды. Өндіріс құралдарына жеке меншік қалыптасып, нарықтық экономика дамыды. Кеңес Одағы кезеңінде мемлекеттік меншік үстемдік етті. Жеке меншік шектеліп, негізгі өндіріс құралдары мемлекет меншігіне берілді. Қазақстан тәуелсіздік алғаннан кейін жеке меншік институты қайта қалыптасып, нарықтық экономикаға көшу жүзеге асырылды.","html":"Меншік қатынастары адамзат қоғамымен бірге қалыптасты. Алғашқы қауымдық құрылыста мүлікке ұжымдық меншік басым болды. Жер, еңбек құралдары, өнімдер ортақ пайдаланылды. Құл иеленушілік дәуірде жеке меншік институты қалыптаса бастады. Мүлікпен қатар адамдардың өзі де меншік объектісіне айналды. Феодалдық қоғамда жерге меншік негізгі рөл атқарды. Жер феодалдарға тиесілі болды, ал шаруалар болса оны пайдаланушы ретінде ғана қызмет етті. Капиталистік қоғамда жеке меншік басты экономикалық негізге айналды. Өндіріс құралдарына жеке меншік қалыптасып, нарықтық экономика дамыды. Кеңес Одағы кезеңінде мемлекеттік меншік үстемдік етті. Жеке меншік шектеліп, негізгі өндіріс құралдары мемлекет меншігіне берілді. Қазақстан тәуелсіздік алғаннан кейін жеке меншік институты қайта қалыптасып, нарықтық экономикаға көшу жүзеге асырылды.","id":"lesson-13-paragraph-2"},{"text":"Қазақстан Республикасының Конституциясында меншік құқығына ерекше мән берілген. Конституцияның 26-бабына сәйкес, азаматтар заңды түрде алған мүлкін жеке меншігінде ұстауға құқылы, меншікке қол сұғылмайды және сот шешімінсіз мүліктен айыруға жол берілмейді. Бұл нормалар меншік құқығының мызғымастығын және мемлекеттік қорғауда екенін білдіреді [33].","html":"Қазақстан Республикасының Конституциясында меншік құқығына ерекше мән берілген. Конституцияның 26-бабына сәйкес, азаматтар заңды түрде алған мүлкін жеке меншігінде ұстауға құқылы, меншікке қол сұғылмайды және сот шешімінсіз мүліктен айыруға жол берілмейді. Бұл нормалар меншік құқығының мызғымастығын және мемлекеттік қорғауда екенін білдіреді [33].","id":"lesson-13-paragraph-3"},{"text":"Азаматтық кодекс осы конституциялық қағидаларды нақтылай отырып, меншік қатынастарын егжей-тегжейлі реттейді. Меншік құқығы институты азаматтардың, заңды тұлғалардың және мемлекеттің мүліктік мүдделерін қорғаудың басты кепілі болып саналады.","html":"Азаматтық кодекс осы конституциялық қағидаларды нақтылай отырып, меншік қатынастарын егжей-тегжейлі реттейді. Меншік құқығы институты азаматтардың, заңды тұлғалардың және мемлекеттің мүліктік мүдделерін қорғаудың басты кепілі болып саналады.","id":"lesson-13-paragraph-4"},{"text":"Қазақстан Республикасының Азаматтық кодексіне сәйкес, меншік құқығы - тұлғаның өзіне тиесілі мүлікті өз қалауынша иеленуіне, пайдалануына және оған билік етуіне заңмен қамтамасыз етілген құқығы.","html":"Қазақстан Республикасының Азаматтық кодексіне сәйкес, меншік құқығы - тұлғаның өзіне тиесілі мүлікті өз қалауынша иеленуіне, пайдалануына және оған билік етуіне заңмен қамтамасыз етілген құқығы.","id":"lesson-13-paragraph-5"},{"text":"Меншік құқығы төмендегі үш негізгі өкілеттіктен тұрады:","html":"Меншік құқығы төмендегі үш негізгі өкілеттіктен тұрады:","id":"lesson-13-paragraph-6"},{"text":"- иелену құқығы – мүлікті өзінде нақты ұстау мүмкіндігі;","html":"- иелену құқығы – мүлікті өзінде нақты ұстау мүмкіндігі;","id":"lesson-13-paragraph-7"},{"text":"- пайдалану құқығы – мүліктің пайдалы қасиеттерін қолдану;","html":"- пайдалану құқығы – мүліктің пайдалы қасиеттерін қолдану;","id":"lesson-13-paragraph-8"},{"text":"- билік ету құқығы – мүліктің тағдырын айқындау (сату,","html":"- билік ету құқығы – мүліктің тағдырын айқындау (сату,","id":"lesson-13-paragraph-9"},{"text":"сыйлау, жалға беру және т.б.).","html":"сыйлау, жалға беру және т.б.).","id":"lesson-13-paragraph-10"},{"text":"Осы үш өкілеттік бірлікте меншік иесінің толық құқығын қалыптастырады. Егер осы элементтердің біреуі шектелсе, меншік құқығы да толық жүзеге асырылмайды.","html":"Осы үш өкілеттік бірлікте меншік иесінің толық құқығын қалыптастырады. Егер осы элементтердің біреуі шектелсе, меншік құқығы да толық жүзеге асырылмайды.","id":"lesson-13-paragraph-11"},{"text":"Меншік құқығы мүліктік қатынастардың негізін құрайды және экономикалық айналымның тұрақтылығын қамтамасыз етеді.","html":"Меншік құқығы мүліктік қатынастардың негізін құрайды және экономикалық айналымның тұрақтылығын қамтамасыз етеді.","id":"lesson-13-paragraph-12"},{"text":"Қазақстан Республикасының Азаматтық заңнамасына сәйкес меншік құқығының төмендегідей түрлері бар:","html":"Қазақстан Республикасының Азаматтық заңнамасына сәйкес меншік құқығының төмендегідей түрлері бар:","id":"lesson-13-paragraph-13"},{"text":"Жеке меншік. Жеке меншік азаматтарға және заңды тұлғаларға тиесілі","html":"Жеке меншік. Жеке меншік азаматтарға және заңды тұлғаларға тиесілі","list":{"id":"3","ordered":true,"marker":"%1.","start":1},"id":"lesson-13-paragraph-14"},{"text":"болады. Ол жеке тұлғалардың, коммерциялық және коммерциялық емес ұйымдардың меншігі. Жеке меншік экономикалық белсенділіктің, кәсіпкерліктің дамуына негіз болады.","html":"болады. Ол жеке тұлғалардың, коммерциялық және коммерциялық емес ұйымдардың меншігі. Жеке меншік экономикалық белсенділіктің, кәсіпкерліктің дамуына негіз болады.","id":"lesson-13-paragraph-15"},{"text":"Мемлекеттік меншік. Мемлекеттік меншік республикалық және","html":"Мемлекеттік меншік. Мемлекеттік меншік республикалық және","list":{"id":"3","ordered":true,"marker":"%1.","start":1},"id":"lesson-13-paragraph-16"},{"text":"коммуналдық меншікке бөлінеді. Республикалық меншікке мемлекет иелік етеді. Коммуналдық меншік жергілікті атқарушы органдарға тиесілі. Мемлекеттік меншік қоғамдық қажеттіліктерді қамтамасыз етуге бағытталған.","html":"коммуналдық меншікке бөлінеді. Республикалық меншікке мемлекет иелік етеді. Коммуналдық меншік жергілікті атқарушы органдарға тиесілі. Мемлекеттік меншік қоғамдық қажеттіліктерді қамтамасыз етуге бағытталған.","id":"lesson-13-paragraph-17"},{"text":"Ортақ меншік. Ортақ меншік екі немесе одан да көп тұлғаға тиесілі","html":"Ортақ меншік. Ортақ меншік екі немесе одан да көп тұлғаға тиесілі","list":{"id":"3","ordered":true,"marker":"%1.","start":1},"id":"lesson-13-paragraph-18"},{"text":"мүлік болып табылады.Ол екі түрге бөлінеді: үлестік меншік - әр қатысушының үлесі анықталған және бірлескен меншік - үлестер алдын ала белгіленбеген. Ортақ меншік көбінесе отбасы, серіктестік қатынастарда кездеседі.","html":"мүлік болып табылады.Ол екі түрге бөлінеді: үлестік меншік - әр қатысушының үлесі анықталған және бірлескен меншік - үлестер алдын ала белгіленбеген. Ортақ меншік көбінесе отбасы, серіктестік қатынастарда кездеседі.","id":"lesson-13-paragraph-19"},{"text":"Меншік құқығының объектілері ретінде мүліктік игіліктер танылады. Оларға: заттар, ақша, бағалы қағаздар, мүліктік құқықтар, мүліктік кешендер. Заттар қозғалатын және қозғалмайтын болып бөлінеді. Қозғалмайтын мүлікке жер, ғимараттар, құрылыстар жатады. Бұл бөлініс құқықтық режимді анықтауда маңызды рөл атқарады.","html":"Меншік құқығының объектілері ретінде мүліктік игіліктер танылады. Оларға: заттар, ақша, бағалы қағаздар, мүліктік құқықтар, мүліктік кешендер. Заттар қозғалатын және қозғалмайтын болып бөлінеді. Қозғалмайтын мүлікке жер, ғимараттар, құрылыстар жатады. Бұл бөлініс құқықтық режимді анықтауда маңызды рөл атқарады.","id":"lesson-13-paragraph-20"},{"text":"Меншік құқығы бастапқы және туынды негіздер арқылы пайда болады. Бастапқы негіздер бұрынғы меншік иесінің құқығына тәуелсіз туындайды. Мысалы, бастапқы негіздерге жаңа зат жасау, иесіз мүлікті иелену, олжаны табу, өңдеу нәтижесінде меншік құқығының пайда болуын жатқызсақ болады. Туынды негіздер бұрынғы меншік иесінің еркіне негізделеді, яғни сатып алу-сату шарты, сыйға тарту шарты, мұрагерлік, айырбас шарты сияқты шарттарды жасасу арқылы пайда болады және бұл жағдайда меншік құқығы бір тұлғадан екінші тұлғаға өтеді.","html":"Меншік құқығы бастапқы және туынды негіздер арқылы пайда болады. Бастапқы негіздер бұрынғы меншік иесінің құқығына тәуелсіз туындайды. Мысалы, бастапқы негіздерге жаңа зат жасау, иесіз мүлікті иелену, олжаны табу, өңдеу нәтижесінде меншік құқығының пайда болуын жатқызсақ болады. Туынды негіздер бұрынғы меншік иесінің еркіне негізделеді, яғни сатып алу-сату шарты, сыйға тарту шарты, мұрагерлік, айырбас шарты сияқты шарттарды жасасу арқылы пайда болады және бұл жағдайда меншік құқығы бір тұлғадан екінші тұлғаға өтеді.","id":"lesson-13-paragraph-21"},{"text":"Меншік құқығы келесі жағдайларда тоқтатылады:","html":"Меншік құқығы келесі жағдайларда тоқтатылады:","id":"lesson-13-paragraph-22"},{"text":"мүлікті ерікті түрде беру;","html":"мүлікті ерікті түрде беру;","list":{"id":"2","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-23"},{"text":"жою;","html":"жою;","list":{"id":"2","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-24"},{"text":"тәркілеу;","html":"тәркілеу;","list":{"id":"2","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-25"},{"text":"реквизиция;","html":"реквизиция;","list":{"id":"2","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-26"},{"text":"сот шешімімен алу;","html":"сот шешімімен алу;","list":{"id":"2","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-27"},{"text":"мемлекет мұқтажы үшін алу.","html":"мемлекет мұқтажы үшін алу.","list":{"id":"2","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-28"},{"text":"Меншік иесінің келісімінсіз алып қою тек заңда көзделген жағдайларда ғана мүмкін.","html":"Меншік иесінің келісімінсіз алып қою тек заңда көзделген жағдайларда ғана мүмкін.","id":"lesson-13-paragraph-29"},{"text":"Меншік құқығын қорғау азаматтық құқықтың маңызды бағыты болып табылады. Меншік құқығын қорғаудың негізгі тәсілдері болып:","html":"Меншік құқығын қорғау азаматтық құқықтың маңызды бағыты болып табылады. Меншік құқығын қорғаудың негізгі тәсілдері болып:","id":"lesson-13-paragraph-30"},{"text":"виндикациялық талап – заңсыз иеленушіден мүлікті қайтарып алу;","html":"виндикациялық талап – заңсыз иеленушіден мүлікті қайтарып алу;","list":{"id":"1","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-31"},{"text":"негаторлық талап – құқықты бұзуды тоқтату;","html":"негаторлық талап – құқықты бұзуды тоқтату;","list":{"id":"1","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-32"},{"text":"залалды өтеу;","html":"залалды өтеу;","list":{"id":"1","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-33"},{"text":"құқықты тану б.т. [34].","html":"құқықты тану б.т. [34].","list":{"id":"1","ordered":false,"marker":"✓","start":1},"id":"lesson-13-paragraph-34"},{"text":"Бұл құралдар меншік иесінің құқықтарын қалпына келтіруге мүмкіндік береді.","html":"Бұл құралдар меншік иесінің құқықтарын қалпына келтіруге мүмкіндік береді.","id":"lesson-13-paragraph-35"},{"text":"Меншік құқығы - азаматтық құқық жүйесінің негізін құрайтын маңызды институт. Ол тұлғаның мүліктік тәуелсіздігін, экономикалық еркіндігін және қоғамдағы тұрақтылығын қамтамасыз етеді. Қазақстан Республикасының заңнамасы меншік құқығын кеңінен қорғап, оның барлық түрлерінің теңдігін қамтамасыз етеді. Тарихи дамуы барысында меншік институты қоғамның әлеуметтік-экономикалық жағдайына сай өзгеріп отырды. Қазіргі кезеңде меншік қатынастары нарықтық экономиканың негізгі тірегі ретінде дамып, құқықтық мемлекеттің қалыптасуына қызмет етуде.","html":"Меншік құқығы - азаматтық құқық жүйесінің негізін құрайтын маңызды институт. Ол тұлғаның мүліктік тәуелсіздігін, экономикалық еркіндігін және қоғамдағы тұрақтылығын қамтамасыз етеді. Қазақстан Республикасының заңнамасы меншік құқығын кеңінен қорғап, оның барлық түрлерінің теңдігін қамтамасыз етеді. Тарихи дамуы барысында меншік институты қоғамның әлеуметтік-экономикалық жағдайына сай өзгеріп отырды. Қазіргі кезеңде меншік қатынастары нарықтық экономиканың негізгі тірегі ретінде дамып, құқықтық мемлекеттің қалыптасуына қызмет етуде.","id":"lesson-13-paragraph-36"}],"words":645,"legacyAnchors":{"lesson-13-section-1":"lesson-13-paragraph-1","lesson-13-section-2":"lesson-13-paragraph-5","lesson-13-section-3":"lesson-13-paragraph-13","lesson-13-section-4":"lesson-13-paragraph-20","lesson-13-section-5":"lesson-13-paragraph-21","lesson-13-section-6":"lesson-13-paragraph-30"}},"14":{"title":"14-ТАҚЫРЫП. МІНДЕТТЕМЕЛІК ҚҰҚЫҚ ТУРАЛЫ ЖАЛПЫ ЕРЕЖЕЛЕР","blocks":[{"text":"Міндеттемелік құқық - азаматтық құқықтың негізгі салаларының бірі болып табылады. Ол мүліктік айналым барысында туындайтын қатынастарды реттейді және тараптардың құқықтары мен міндеттерін айқындайды. Қазіргі нарықтық экономика жағдайында міндеттемелік құқықтың маңызы ерекше, себебі тауар айналымы, қызмет көрсету, жұмыстарды орындау, шарттық қатынастар осы сала арқылы жүзеге асады. Қазақстан Республикасының Азаматтық кодексінде міндеттемелік құқыққа арнайы бөлім арналған және онда міндеттемелердің пайда болуы, орындалуы, өзгертілуі мен тоқтатылуы жан-жақты реттелген. Міндеттемелік құқық азаматтардың, ұйымдардың және мемлекеттің экономикалық мүдделерін қорғауға бағытталған.","html":"Міндеттемелік құқық - азаматтық құқықтың негізгі салаларының бірі болып табылады. Ол мүліктік айналым барысында туындайтын қатынастарды реттейді және тараптардың құқықтары мен міндеттерін айқындайды. Қазіргі нарықтық экономика жағдайында міндеттемелік құқықтың маңызы ерекше, себебі тауар айналымы, қызмет көрсету, жұмыстарды орындау, шарттық қатынастар осы сала арқылы жүзеге асады. Қазақстан Республикасының Азаматтық кодексінде міндеттемелік құқыққа арнайы бөлім арналған және онда міндеттемелердің пайда болуы, орындалуы, өзгертілуі мен тоқтатылуы жан-жақты реттелген. Міндеттемелік құқық азаматтардың, ұйымдардың және мемлекеттің экономикалық мүдделерін қорғауға бағытталған.","id":"lesson-14-paragraph-1"},{"text":"Қазақстан Республикасының Азаматтық кодексінің 268-бабына сәйкес, міндеттеме деп бір тұлғаның (борышкердің) басқа тұлғаның (несие берушінің) пайдасына белгілі бір әрекет жасауға немесе әрекеттен бас тартуға міндетті болуы танылады [2].","html":"Қазақстан Республикасының Азаматтық кодексінің 268-бабына сәйкес, міндеттеме деп бір тұлғаның (борышкердің) басқа тұлғаның (несие берушінің) пайдасына белгілі бір әрекет жасауға немесе әрекеттен бас тартуға міндетті болуы танылады [2].","id":"lesson-14-paragraph-2"},{"text":"Мысалы, азамат Айбек дүкеннен тоңазытқыш сатып алып, ақшасын төлеуге міндеттенеді, ал дүкен тауарды беруге міндетті болады. Бұл - міндеттемелік қатынас. Міндеттемеде екі негізгі тарап болады: борышкер және несие беруші. Борышкер міндетті орындауға жауапты болса, несие беруші оны талап етуге құқылы. Міндеттемелік құқықтың басты мақсаты - тараптар арасындағы келісімдердің орындалуын қамтамасыз ету.","html":"Мысалы, азамат Айбек дүкеннен тоңазытқыш сатып алып, ақшасын төлеуге міндеттенеді, ал дүкен тауарды беруге міндетті болады. Бұл - міндеттемелік қатынас. Міндеттемеде екі негізгі тарап болады: борышкер және несие беруші. Борышкер міндетті орындауға жауапты болса, несие беруші оны талап етуге құқылы. Міндеттемелік құқықтың басты мақсаты - тараптар арасындағы келісімдердің орындалуын қамтамасыз ету.","id":"lesson-14-paragraph-3"},{"text":"ҚР Азаматтық кодексінің 271-бабына сәйкес, міндеттемелер шарттардан, зиян келтіруден, негізсіз баюдан, заң актілерінен және өзге де заңды әрекеттерден туындайды [2].","html":"ҚР Азаматтық кодексінің 271-бабына сәйкес, міндеттемелер шарттардан, зиян келтіруден, негізсіз баюдан, заң актілерінен және өзге де заңды әрекеттерден туындайды [2].","id":"lesson-14-paragraph-4"},{"text":"Ең кең тараған міндеттеме - шарттан пайда болатын міндеттемелер. Мысалы, сатып алу-сату, жалдау, мердігерлік, тасымалдау шарттарынан туындаған міндеттемелер. Ержан пәтер жалдау туралы шарт жасап, ай сайын жалдау ақысын төлеуге міндеттенеді, ал жалға беруші пәтерді пайдалануға беруге міндетті.","html":"Ең кең тараған міндеттеме - шарттан пайда болатын міндеттемелер. Мысалы, сатып алу-сату, жалдау, мердігерлік, тасымалдау шарттарынан туындаған міндеттемелер. Ержан пәтер жалдау туралы шарт жасап, ай сайын жалдау ақысын төлеуге міндеттенеді, ал жалға беруші пәтерді пайдалануға беруге міндетті.","id":"lesson-14-paragraph-5"},{"text":"Зиян келтіруден туындайтын міндеттемелер де маңызды орын алады. Мәселен, жол-көлік оқиғасында жүргізуші басқа адамның көлігін бүлдірсе, келтірілген шығынды өтеуге міндетті.","html":"Зиян келтіруден туындайтын міндеттемелер де маңызды орын алады. Мәселен, жол-көлік оқиғасында жүргізуші басқа адамның көлігін бүлдірсе, келтірілген шығынды өтеуге міндетті.","id":"lesson-14-paragraph-6"},{"text":"Негізсіз баю кезінде бір тұлға заңды негізсіз басқа адамның есебінен мүлік алса, оны қайтаруы тиіс. Яғни бұл кезде де міндеттеме туындап отыр. Мысалы, банктің қателігі арқылы артық ақша аударылған жағдайда, алушы бұл соманы кері қайтаруға міндетті болады.","html":"Негізсіз баю кезінде бір тұлға заңды негізсіз басқа адамның есебінен мүлік алса, оны қайтаруы тиіс. Яғни бұл кезде де міндеттеме туындап отыр. Мысалы, банктің қателігі арқылы артық ақша аударылған жағдайда, алушы бұл соманы кері қайтаруға міндетті болады.","id":"lesson-14-paragraph-7"},{"text":"Міндеттеменің мазмұны борышкердің міндеттері мен несие берушінің құқықтарынан тұрады. Оның негізгі элементтеріне тараптар, нысан және мазмұн жатады. Міндеттеменің нысанасы ретінде мүлікті беру, ақша төлеу, жұмыс орындау, қызмет көрсету немесе белгілі бір әрекеттен бас тарту танылады. Мысалы, құрылыс компаниясы тұрғын үй салуға міндеттенсе, тапсырыс беруші келісілген соманы төлеуге міндетті болады. Бір міндеттемеде бірнеше борышкер немесе бірнеше несие беруші қатысуы да мүмкін.","html":"Міндеттеменің мазмұны борышкердің міндеттері мен несие берушінің құқықтарынан тұрады. Оның негізгі элементтеріне тараптар, нысан және мазмұн жатады. Міндеттеменің нысанасы ретінде мүлікті беру, ақша төлеу, жұмыс орындау, қызмет көрсету немесе белгілі бір әрекеттен бас тарту танылады. Мысалы, құрылыс компаниясы тұрғын үй салуға міндеттенсе, тапсырыс беруші келісілген соманы төлеуге міндетті болады. Бір міндеттемеде бірнеше борышкер немесе бірнеше несие беруші қатысуы да мүмкін.","id":"lesson-14-paragraph-8"},{"text":"ҚР Азаматтық кодексінің 272-бабына сәйкес, міндеттемелер тиісінше, яғни шартта және заңда көзделген талаптарға сай орындалуы тиіс. Орындау сапалы, толық, белгіленген мерзімде және тиісті жерде жүзеге асырылуы қажет [2].","html":"ҚР Азаматтық кодексінің 272-бабына сәйкес, міндеттемелер тиісінше, яғни шартта және заңда көзделген талаптарға сай орындалуы тиіс. Орындау сапалы, толық, белгіленген мерзімде және тиісті жерде жүзеге асырылуы қажет [2].","id":"lesson-14-paragraph-9"},{"text":"Мысалы, шарт бойынша тауар 1-маусымда жеткізілуі тиіс болса, оны кешіктіруге жол берілмейді. Егер борышкер міндеттемені өзі орындауға тиіс деп белгіленсе, оны басқа адамға жүктеуге болмайды, егер заңда немесе шартта өзгеше көрсетілмесе. Орындау мерзімі шартта көрсетілмеген жағдайда, несие берушінің талабынан кейін ақылға қонымды мерзімде орындалуы қажет.","html":"Мысалы, шарт бойынша тауар 1-маусымда жеткізілуі тиіс болса, оны кешіктіруге жол берілмейді. Егер борышкер міндеттемені өзі орындауға тиіс деп белгіленсе, оны басқа адамға жүктеуге болмайды, егер заңда немесе шартта өзгеше көрсетілмесе. Орындау мерзімі шартта көрсетілмеген жағдайда, несие берушінің талабынан кейін ақылға қонымды мерзімде орындалуы қажет.","id":"lesson-14-paragraph-10"},{"text":"Міндеттемелердің орындалуын қамтамасыз ету үшін арнайы құқықтық тәсілдер қолданылады. ҚР Азаматтық кодексінің 292-бабына сәйкес, оларға айыппұл, кепіл, кепілдік, кепілпұл және кепіл болушылық жатады. Айыппұл борышкер міндеттемені бұзған жағдайда қосымша төлем ретінде белгіленеді. Мысалы, құрылыс компаниясы үйді уақытында тапсырмаса, айыппұл төлейді. Кепіл арқылы борышкер қарызын өтемеген жағдайда кепілдегі мүлік сатылып, берешек жабылады. Ал кепілпұл шарттың жасалғанын және орындалуын қамтамасыз ететін ақша сомасы болып табылады.","html":"Міндеттемелердің орындалуын қамтамасыз ету үшін арнайы құқықтық тәсілдер қолданылады. ҚР Азаматтық кодексінің 292-бабына сәйкес, оларға айыппұл, кепіл, кепілдік, кепілпұл және кепіл болушылық жатады. Айыппұл борышкер міндеттемені бұзған жағдайда қосымша төлем ретінде белгіленеді. Мысалы, құрылыс компаниясы үйді уақытында тапсырмаса, айыппұл төлейді. Кепіл арқылы борышкер қарызын өтемеген жағдайда кепілдегі мүлік сатылып, берешек жабылады. Ал кепілпұл шарттың жасалғанын және орындалуын қамтамасыз ететін ақша сомасы болып табылады.","id":"lesson-14-paragraph-11"},{"text":"Міндеттемені орындамау немесе тиісінше орындамау құқық бұзушылық болып есептеледі. ҚР Азаматтық кодексінің 349-бабына сәйкес, борышкер міндеттемені бұзғаны үшін жауапкершілікке тартылады. Жауапкершілік залалды өтеу, айыппұл төлеу, өсімпұл төлеу немесе шартты бұзу түрінде көрініс табады. Мысалы, жеткізуші сапасыз тауар берсе, сатып алушы ақшасын қайтаруды немесе тауарды ауыстыруды талап етуге құқылы.","html":"Міндеттемені орындамау немесе тиісінше орындамау құқық бұзушылық болып есептеледі. ҚР Азаматтық кодексінің 349-бабына сәйкес, борышкер міндеттемені бұзғаны үшін жауапкершілікке тартылады. Жауапкершілік залалды өтеу, айыппұл төлеу, өсімпұл төлеу немесе шартты бұзу түрінде көрініс табады. Мысалы, жеткізуші сапасыз тауар берсе, сатып алушы ақшасын қайтаруды немесе тауарды ауыстыруды талап етуге құқылы.","id":"lesson-14-paragraph-12"},{"text":"ҚР Азаматтық кодексінің 367-бабына сәйкес, міндеттемелер бірнеше негіз бойынша тоқтатылады. Ең алдымен, міндеттеме тиісінше орындалған кезде тоқтатылады. Сонымен қатар тараптардың келісімі бойынша, борышты кешіру арқылы, борышкер мен несие берушінің бір тұлғаға айналуы нәтижесінде немесе орындау мүмкін болмаған жағдайда да міндеттеме тоқтатылуы мүмкін [35]. Мысалы, қарыз толық өтелсе, міндеттемелік қатынас өз күшін жояды.","html":"ҚР Азаматтық кодексінің 367-бабына сәйкес, міндеттемелер бірнеше негіз бойынша тоқтатылады. Ең алдымен, міндеттеме тиісінше орындалған кезде тоқтатылады. Сонымен қатар тараптардың келісімі бойынша, борышты кешіру арқылы, борышкер мен несие берушінің бір тұлғаға айналуы нәтижесінде немесе орындау мүмкін болмаған жағдайда да міндеттеме тоқтатылуы мүмкін [35]. Мысалы, қарыз толық өтелсе, міндеттемелік қатынас өз күшін жояды.","id":"lesson-14-paragraph-13"},{"text":"Міндеттемелік құқықтың тәжірибелік маңызы өте үлкен. Ол сауда-саттықта, қызмет көрсетуде, несие қатынастарында, жалдау шарттарында, құрылыс саласында және басқа да көптеген салаларда қолданылады. Әрбір азамат міндеттемелік құқық нормаларын білу арқылы өз құқықтарын тиімді қорғай алады, заң талаптарын сақтай отырып әрекет етеді және даулы жағдайлардың алдын алады.","html":"Міндеттемелік құқықтың тәжірибелік маңызы өте үлкен. Ол сауда-саттықта, қызмет көрсетуде, несие қатынастарында, жалдау шарттарында, құрылыс саласында және басқа да көптеген салаларда қолданылады. Әрбір азамат міндеттемелік құқық нормаларын білу арқылы өз құқықтарын тиімді қорғай алады, заң талаптарын сақтай отырып әрекет етеді және даулы жағдайлардың алдын алады.","id":"lesson-14-paragraph-14"},{"text":"Қорытындылай келе, міндеттемелік құқық азаматтық құқық жүйесінің маңызды және ажырамас бөлігі болып табылады. Ол азаматтық айналымның тұрақтылығын, шарттардың орындалуын және тараптардың өзара сенімін қамтамасыз етеді. Қазақстан Республикасының азаматтық заңнамасы міндеттемелерді жан-жақты реттеп, олардың әділ және тиімді жүзеге асырылуына жағдай жасайды. Міндеттемелік құқық нормаларын дұрыс қолдану экономикалық қатынастардың дамуына, құқықтық мәдениеттің қалыптасуына және азаматтардың құқықтарының сенімді қорғалуына ықпал етеді.","html":"Қорытындылай келе, міндеттемелік құқық азаматтық құқық жүйесінің маңызды және ажырамас бөлігі болып табылады. Ол азаматтық айналымның тұрақтылығын, шарттардың орындалуын және тараптардың өзара сенімін қамтамасыз етеді. Қазақстан Республикасының азаматтық заңнамасы міндеттемелерді жан-жақты реттеп, олардың әділ және тиімді жүзеге асырылуына жағдай жасайды. Міндеттемелік құқық нормаларын дұрыс қолдану экономикалық қатынастардың дамуына, құқықтық мәдениеттің қалыптасуына және азаматтардың құқықтарының сенімді қорғалуына ықпал етеді.","id":"lesson-14-paragraph-15"}],"words":667,"legacyAnchors":{"lesson-14-section-1":"lesson-14-paragraph-1","lesson-14-section-2":"lesson-14-paragraph-4","lesson-14-section-3":"lesson-14-paragraph-8","lesson-14-section-4":"lesson-14-paragraph-11","lesson-14-section-5":"lesson-14-paragraph-13"}},"15":{"title":"15-ТАҚЫРЫП. ШАРТ ТУРАЛЫ ЖАЛПЫ ЕРЕЖЕЛЕР","blocks":[{"text":"Шарт азаматтық құқықтағы ең маңызды құқықтық институттардың бірі болып табылады. Ол азаматтар мен ұйымдар арасындағы мүліктік және мүліктік емес қатынастарды реттеудің негізгі нысаны саналады. Қазіргі нарықтық экономика жағдайында тауар айналымы, қызмет көрсету, жұмыс орындау, несие беру, жалға алу және басқа да көптеген қатынастар шарт негізінде жүзеге асырылады. Сондықтан шарттық қатынастардың дұрыс ұйымдастырылуы азаматтық айналымның тұрақтылығын қамтамасыз етудің басты кепілі болып табылады [25].","html":"Шарт азаматтық құқықтағы ең маңызды құқықтық институттардың бірі болып табылады. Ол азаматтар мен ұйымдар арасындағы мүліктік және мүліктік емес қатынастарды реттеудің негізгі нысаны саналады. Қазіргі нарықтық экономика жағдайында тауар айналымы, қызмет көрсету, жұмыс орындау, несие беру, жалға алу және басқа да көптеген қатынастар шарт негізінде жүзеге асырылады. Сондықтан шарттық қатынастардың дұрыс ұйымдастырылуы азаматтық айналымның тұрақтылығын қамтамасыз етудің басты кепілі болып табылады [25].","id":"lesson-15-paragraph-1"},{"text":"Қазақстан Республикасының Азаматтық кодексінің 378-бабына сәйкес, шарт деп екі немесе одан да көп тұлғаның азаматтық құқықтар мен міндеттерді белгілеу, өзгерту немесе тоқтату туралы келісімі танылады [2]. Осы анықтамадан шарттың тараптардың өзара ерік білдіруі арқылы жасалатын құқықтық акт екенін байқауға болады. Шарт тараптар арасында құқықтар мен міндеттердің туындауына, өзгеруіне немесе тоқтатылуына негіз болады.","html":"Қазақстан Республикасының Азаматтық кодексінің 378-бабына сәйкес, шарт деп екі немесе одан да көп тұлғаның азаматтық құқықтар мен міндеттерді белгілеу, өзгерту немесе тоқтату туралы келісімі танылады [2]. Осы анықтамадан шарттың тараптардың өзара ерік білдіруі арқылы жасалатын құқықтық акт екенін байқауға болады. Шарт тараптар арасында құқықтар мен міндеттердің туындауына, өзгеруіне немесе тоқтатылуына негіз болады.","id":"lesson-15-paragraph-2"},{"text":"Шарттың негізгі белгілеріне тараптардың келісімі, еріктілік, заңға сәйкестік және құқықтық салдарлардың туындауы жатады. Әрбір шарт тараптардың еркін білдіруі негізінде жасалуы тиіс. Сонымен қатар, шарттың мазмұны қолданыстағы заңнамаға қайшы келмеуі қажет. Заң талаптарын бұза отырып жасалған шарт жарамсыз деп танылуы мүмкін.","html":"Шарттың негізгі белгілеріне тараптардың келісімі, еріктілік, заңға сәйкестік және құқықтық салдарлардың туындауы жатады. Әрбір шарт тараптардың еркін білдіруі негізінде жасалуы тиіс. Сонымен қатар, шарттың мазмұны қолданыстағы заңнамаға қайшы келмеуі қажет. Заң талаптарын бұза отырып жасалған шарт жарамсыз деп танылуы мүмкін.","id":"lesson-15-paragraph-3"},{"text":"Шарттық қатынастардың маңызды қағидаларының бірі - шарт еркіндігі қағидасы. Қазақстан Республикасының Азаматтық кодексінің 380-бабына сәйкес, азаматтар мен заңды тұлғалар шарт жасасуда еркін болады. Бұл қағида тараптардың шарт жасасу немесе жасаспау, шарт түрін таңдау, шарт талаптарын өз қалауынша белгілеу және бірнеше шарт элементтерін біріктіру мүмкіндігін білдіреді. Мысалы, тараптар сатып алу-сату және жеткізу шарттарының элементтерін бір келісімге біріктіре алады.","html":"Шарттық қатынастардың маңызды қағидаларының бірі - шарт еркіндігі қағидасы. Қазақстан Республикасының Азаматтық кодексінің 380-бабына сәйкес, азаматтар мен заңды тұлғалар шарт жасасуда еркін болады. Бұл қағида тараптардың шарт жасасу немесе жасаспау, шарт түрін таңдау, шарт талаптарын өз қалауынша белгілеу және бірнеше шарт элементтерін біріктіру мүмкіндігін білдіреді. Мысалы, тараптар сатып алу-сату және жеткізу шарттарының элементтерін бір келісімге біріктіре алады.","id":"lesson-15-paragraph-4"},{"text":"Алайда шарт еркіндігі абсолютті сипатта болмайды. Ол заң талаптарымен, қоғамдық тәртіппен және адамгершілік нормаларымен шектеледі. Кейбір жағдайларда заң белгілі бір тұлғаларды шарт жасасуға міндеттейді. Мысалы, монополист кәсіпорындар тұтынушылармен шарт жасасудан негізсіз бас тарта алмайды.","html":"Алайда шарт еркіндігі абсолютті сипатта болмайды. Ол заң талаптарымен, қоғамдық тәртіппен және адамгершілік нормаларымен шектеледі. Кейбір жағдайларда заң белгілі бір тұлғаларды шарт жасасуға міндеттейді. Мысалы, монополист кәсіпорындар тұтынушылармен шарт жасасудан негізсіз бас тарта алмайды.","id":"lesson-15-paragraph-5"},{"text":"Шарттың мазмұны тараптардың құқықтары мен міндеттерінің жиынтығынан тұрады. Шарт талаптары маңызды, әдеттегі және кездейсоқ болып бөлінеді. Маңызды талаптарсыз шарт жасалған болып саналмайды. Оларға шарт нысанасы, заңда маңызды деп танылған талаптар және тараптардың өздері маңызды деп белгілеген талаптар жатады. Мысалы, сатып алу-сату шартында тауардың атауы мен саны көрсетілмесе, мұндай шарт жарамсыз болуы мүмкін.","html":"Шарттың мазмұны тараптардың құқықтары мен міндеттерінің жиынтығынан тұрады. Шарт талаптары маңызды, әдеттегі және кездейсоқ болып бөлінеді. Маңызды талаптарсыз шарт жасалған болып саналмайды. Оларға шарт нысанасы, заңда маңызды деп танылған талаптар және тараптардың өздері маңызды деп белгілеген талаптар жатады. Мысалы, сатып алу-сату шартында тауардың атауы мен саны көрсетілмесе, мұндай шарт жарамсыз болуы мүмкін.","id":"lesson-15-paragraph-6"},{"text":"Әдеттегі талаптар заңда белгіленгендіктен, шартта көрсетілмесе де қолданылады. Ал кездейсоқ талаптар тараптардың өз еркімен енгізіледі. Мысалы, айыппұл мөлшері, қосымша кепілдіктер немесе ерекше жауапкершілік шарттары.","html":"Әдеттегі талаптар заңда белгіленгендіктен, шартта көрсетілмесе де қолданылады. Ал кездейсоқ талаптар тараптардың өз еркімен енгізіледі. Мысалы, айыппұл мөлшері, қосымша кепілдіктер немесе ерекше жауапкершілік шарттары.","id":"lesson-15-paragraph-7"},{"text":"Шарттар әртүрлі белгілеріне қарай бірнеше түрге бөлінеді. Міндеттемелердің сипатына қарай біржақты және екіжақты шарттар болады. Біржақты шартта бір тарапта ғана міндет жүктеледі, ал екінші тарапта тек құқық болады. Мысалы, сыйға тарту шарты. Екіжақты шартта екі тарапта да құқықтар мен міндеттер болады, мысалы, сатып алу-сату шарты.","html":"Шарттар әртүрлі белгілеріне қарай бірнеше түрге бөлінеді. Міндеттемелердің сипатына қарай біржақты және екіжақты шарттар болады. Біржақты шартта бір тарапта ғана міндет жүктеледі, ал екінші тарапта тек құқық болады. Мысалы, сыйға тарту шарты. Екіжақты шартта екі тарапта да құқықтар мен міндеттер болады, мысалы, сатып алу-сату шарты.","id":"lesson-15-paragraph-8"},{"text":"Ақылы және ақысыз шарттар да кең таралған. Ақылы шартта тараптар бір-біріне мүліктік эквивалент береді, ал ақысыз шартта мұндай төлем көзделмейді. Жалдау шарты ақылы, ал тегін пайдалану шарты ақысыз болып табылады.","html":"Ақылы және ақысыз шарттар да кең таралған. Ақылы шартта тараптар бір-біріне мүліктік эквивалент береді, ал ақысыз шартта мұндай төлем көзделмейді. Жалдау шарты ақылы, ал тегін пайдалану шарты ақысыз болып табылады.","id":"lesson-15-paragraph-9"},{"text":"Заңнамада жария шарт және қосылу шарты сияқты арнайы шарт түрлері де көзделген. Жария шарт бойынша коммерциялық ұйым кез келген тұтынушымен бірдей талаптармен шарт жасасуға міндетті. Ал қосылу шартында бір тарап барлық талаптарды алдын ала белгілейді, екінші тарап оларды толық қабылдайды немесе шарттан бас тартады. Мұндай шарттар көбінесе банктік және сақтандыру саласында кездеседі.","html":"Заңнамада жария шарт және қосылу шарты сияқты арнайы шарт түрлері де көзделген. Жария шарт бойынша коммерциялық ұйым кез келген тұтынушымен бірдей талаптармен шарт жасасуға міндетті. Ал қосылу шартында бір тарап барлық талаптарды алдын ала белгілейді, екінші тарап оларды толық қабылдайды немесе шарттан бас тартады. Мұндай шарттар көбінесе банктік және сақтандыру саласында кездеседі.","id":"lesson-15-paragraph-10"},{"text":"Шарт жасасу оферта мен акцепт арқылы жүзеге асырылады. Оферта - шарт жасасу туралы нақты және толық ұсыныс. Ол маңызды талаптарды қамтуы және шарт жасасуға дайындықты білдіруі тиіс. Акцепт - офертаны толық және шартсыз қабылдау болып табылады. Егер тұлға ұсынылған талаптарға келісіп, оларды орындауға кіріссе, бұл акцепт ретінде танылады.","html":"Шарт жасасу оферта мен акцепт арқылы жүзеге асырылады. Оферта - шарт жасасу туралы нақты және толық ұсыныс. Ол маңызды талаптарды қамтуы және шарт жасасуға дайындықты білдіруі тиіс. Акцепт - офертаны толық және шартсыз қабылдау болып табылады. Егер тұлға ұсынылған талаптарға келісіп, оларды орындауға кіріссе, бұл акцепт ретінде танылады.","id":"lesson-15-paragraph-11"},{"text":"Шарт белгілі бір нысанда жасалуы тиіс. Қазақстан Республикасының Азаматтық кодексіне сәйкес, шарт ауызша, жазбаша немесе нотариалдық нысанда жасалады. Маңызды мәмілелер, әсіресе жылжымайтын мүлікке қатысты шарттар, жазбаша және нотариалдық түрде рәсімделуі қажет. Шарттың нысанын сақтамау оның жарамсыз болуына әкелуі мүмкін.","html":"Шарт белгілі бір нысанда жасалуы тиіс. Қазақстан Республикасының Азаматтық кодексіне сәйкес, шарт ауызша, жазбаша немесе нотариалдық нысанда жасалады. Маңызды мәмілелер, әсіресе жылжымайтын мүлікке қатысты шарттар, жазбаша және нотариалдық түрде рәсімделуі қажет. Шарттың нысанын сақтамау оның жарамсыз болуына әкелуі мүмкін.","id":"lesson-15-paragraph-12"},{"text":"Шарт бойынша туындайтын міндеттемелер тиісінше орындалуы тиіс. ҚР Азаматтық кодексінің 272-бабына сәйкес, міндеттемелер белгіленген мерзімде, тиісті сапада, толық көлемде және келісілген жерде орындалуы қажет. Мысалы, жеткізуші тауарды кешіктірсе немесе сапасыз жеткізсе, ол шартты бұзған болып саналады.","html":"Шарт бойынша туындайтын міндеттемелер тиісінше орындалуы тиіс. ҚР Азаматтық кодексінің 272-бабына сәйкес, міндеттемелер белгіленген мерзімде, тиісті сапада, толық көлемде және келісілген жерде орындалуы қажет. Мысалы, жеткізуші тауарды кешіктірсе немесе сапасыз жеткізсе, ол шартты бұзған болып саналады.","id":"lesson-15-paragraph-13"},{"text":"Шарт тараптардың келісімімен өзгертілуі немесе бұзылуы мүмкін. ҚР АК-нің 401-бабына сәйкес, біржақты тәртіппен шартты өзгертуге немесе бұзуға тек заңда немесе шартта көзделген жағдайларда ғана жол беріледі. Егер тараптардың бірі шартты елеулі түрде бұзса, екінші тарап сотқа жүгініп, шартты бұзуды талап ете алады [2].","html":"Шарт тараптардың келісімімен өзгертілуі немесе бұзылуы мүмкін. ҚР АК-нің 401-бабына сәйкес, біржақты тәртіппен шартты өзгертуге немесе бұзуға тек заңда немесе шартта көзделген жағдайларда ғана жол беріледі. Егер тараптардың бірі шартты елеулі түрде бұзса, екінші тарап сотқа жүгініп, шартты бұзуды талап ете алады [2].","id":"lesson-15-paragraph-14"},{"text":"Заң талаптарына қайшы жасалған шарт жарамсыз деп танылады. ҚР АК 157-бабына сәйкес, алдау, қорқыту, қателесу, әрекет қабілетсіз тұлғаның қатысуы немесе заң нормаларын бұзу шарттың жарамсыздығына негіз болады. Жарамсыз шарт құқықтық салдар туындатпайды және тараптар бастапқы жағдайына қайтарылады.","html":"Заң талаптарына қайшы жасалған шарт жарамсыз деп танылады. ҚР АК 157-бабына сәйкес, алдау, қорқыту, қателесу, әрекет қабілетсіз тұлғаның қатысуы немесе заң нормаларын бұзу шарттың жарамсыздығына негіз болады. Жарамсыз шарт құқықтық салдар туындатпайды және тараптар бастапқы жағдайына қайтарылады.","id":"lesson-15-paragraph-15"},{"text":"Шартты бұзған тұлға азаматтық-құқықтық жауапкершілікке тартылады. ҚР АК 349-бабына сәйкес, мұндай жауапкершілік залалды өтеу, айыппұл немесе өсімпұл төлеу, шартты бұзу түрінде көрініс табады. Мысалы, мердігер жұмысты сапасыз орындаса, тапсырыс беруші шығынды өтеуді талап ете алады.","html":"Шартты бұзған тұлға азаматтық-құқықтық жауапкершілікке тартылады. ҚР АК 349-бабына сәйкес, мұндай жауапкершілік залалды өтеу, айыппұл немесе өсімпұл төлеу, шартты бұзу түрінде көрініс табады. Мысалы, мердігер жұмысты сапасыз орындаса, тапсырыс беруші шығынды өтеуді талап ете алады.","id":"lesson-15-paragraph-16"},{"text":"Шарт азаматтық құқықтағы негізгі құқықтық құралдардың бірі болып табылады және ол тараптардың өзара келісімі негізінде құқықтар мен міндеттерді белгілеуге, өзгертуге немесе тоқтатуға бағытталады. Шарт ерік білдірудің келісілген нысаны ретінде азаматтық айналымның тұрақтылығын қамтамасыз етеді. Шарттық қатынастардың негізінде тараптардың теңдігі, еріктілігі және мүліктік дербестігі қағидалары жатады. Шарттың мазмұны тараптардың құқықтары мен міндеттерінен тұрады және ол заң талаптарына қайшы келмеуі тиіс. Осы тұрғыдан алғанда шарт азаматтық-құқықтық міндеттемелердің басты пайда болу негізі болып саналады [36].","html":"Шарт азаматтық құқықтағы негізгі құқықтық құралдардың бірі болып табылады және ол тараптардың өзара келісімі негізінде құқықтар мен міндеттерді белгілеуге, өзгертуге немесе тоқтатуға бағытталады. Шарт ерік білдірудің келісілген нысаны ретінде азаматтық айналымның тұрақтылығын қамтамасыз етеді. Шарттық қатынастардың негізінде тараптардың теңдігі, еріктілігі және мүліктік дербестігі қағидалары жатады. Шарттың мазмұны тараптардың құқықтары мен міндеттерінен тұрады және ол заң талаптарына қайшы келмеуі тиіс. Осы тұрғыдан алғанда шарт азаматтық-құқықтық міндеттемелердің басты пайда болу негізі болып саналады [36].","id":"lesson-15-paragraph-17"},{"text":"Жоғарыдағылардың негізінде шарттық қатынастардың тәжірибелік маңызы өте жоғары екенін байқауға болады. Олар күнделікті өмірде, кәсіпкерлік қызметте, сауда-саттықта, қызмет көрсету саласында кеңінен қолданылады. Әрбір азамат шарт нормаларын білу арқылы өз құқықтарын тиімді қорғай алады және заңсыз әрекеттердің алдын алады.","html":"Жоғарыдағылардың негізінде шарттық қатынастардың тәжірибелік маңызы өте жоғары екенін байқауға болады. Олар күнделікті өмірде, кәсіпкерлік қызметте, сауда-саттықта, қызмет көрсету саласында кеңінен қолданылады. Әрбір азамат шарт нормаларын білу арқылы өз құқықтарын тиімді қорғай алады және заңсыз әрекеттердің алдын алады.","id":"lesson-15-paragraph-18"},{"text":"Қорытындылай келе, шарт азаматтық құқық жүйесінің негізгі тіректерінің бірі болып табылады. Ол тараптардың құқықтары мен міндеттерін нақты айқындап, экономикалық қатынастардың тұрақтылығын қамтамасыз етеді. Қазақстан Республикасының заңнамасы шарт институтын жан-жақты реттеп, тараптардың теңдігін, әділдігін және құқықтарының қорғалуын қамтамасыз етеді. Шарттық нормаларды дұрыс қолдану құқықтық мәдениеттің қалыптасуына, кәсіпкерліктің дамуына және азаматтық қоғамның нығаюына ықпал етеді.","html":"Қорытындылай келе, шарт азаматтық құқық жүйесінің негізгі тіректерінің бірі болып табылады. Ол тараптардың құқықтары мен міндеттерін нақты айқындап, экономикалық қатынастардың тұрақтылығын қамтамасыз етеді. Қазақстан Республикасының заңнамасы шарт институтын жан-жақты реттеп, тараптардың теңдігін, әділдігін және құқықтарының қорғалуын қамтамасыз етеді. Шарттық нормаларды дұрыс қолдану құқықтық мәдениеттің қалыптасуына, кәсіпкерліктің дамуына және азаматтық қоғамның нығаюына ықпал етеді.","id":"lesson-15-paragraph-19"}],"words":849,"legacyAnchors":{"lesson-15-section-1":"lesson-15-paragraph-1","lesson-15-section-2":"lesson-15-paragraph-4","lesson-15-section-3":"lesson-15-paragraph-6","lesson-15-section-4":"lesson-15-paragraph-8","lesson-15-section-5":"lesson-15-paragraph-11","lesson-15-section-6":"lesson-15-paragraph-13","lesson-15-section-7":"lesson-15-paragraph-17"}}};
